parameters.jsCode:
const staticData = $getWorkflowStaticData('global');
const sceneNum = 1;
const keys = $('Config: Primary Video Master1').first().json.keys;
const totalKeys = keys.length;

// ALWAYS read from static filter nodes as the absolute source of truth!
const vidFilter = $('Filter Video Scene1').first().json;

const inputRaw = ($input && $input.first()) ? $input.first().json : {};

// Check for HTTP 429 rate limit or call frequency errors
const isRateLimit = (
  inputRaw.code == 429 || inputRaw.code == '429' ||
  (inputRaw.data && (inputRaw.data.code == 429 || inputRaw.data.code == '429')) ||
  (inputRaw.msg && inputRaw.msg.includes('frequency'))
);
if (isRateLimit) {
  const delayMs = 5000 + (sceneNum * 2000);
  await new Promise(r => setTimeout(r, delayMs));
}

const restoredData = {
  startImageUrl:      vidFilter.startImageUrl,
  videoPrompt:        vidFilter.videoPrompt,
  voiceoverText:      vidFilter.voiceoverText || '',
  voiceStyle:         vidFilter.voiceStyle    || '',
  speaker:            vidFilter.speaker       || '',
  duration:           vidFilter.duration,
  title:              vidFilter.title,
  corePlot:           vidFilter.corePlot,
  tags:               vidFilter.tags,
  youtubeDescription: vidFilter.youtubeDescription,
  sceneIndex:         vidFilter.sceneIndex,
  sceneNumber:        sceneNum
};

if (staticData['fruitVideoAttempts_1'] === undefined) {
  staticData['fruitVideoAttempts_1'] = 0;
}
staticData['fruitVideoAttempts_1'] += 1;

// All keys exhausted → switch to backup provider
if (staticData['fruitVideoAttempts_1'] > totalKeys) {
  staticData['fruitUseBackupVideo_1'] = true;
  staticData['videoKeyIndex_1'] = sceneNum - 1;
  staticData['fruitVideoAttempts_1'] = 0;
  return [{
    json: {
      ...restoredData,
      useBackupProvider: true,
      code: null,
      __video: sceneNum
    }
  }];
}

if (staticData['videoKeyIndex_1'] === undefined) {
  staticData['videoKeyIndex_1'] = sceneNum - 1;
}
const currentKeyIndex = staticData['videoKeyIndex_1'] % totalKeys;
const currentKey = keys[currentKeyIndex];
staticData['videoKeyIndex_1'] += 1;

// Write new rotated key to staticData as well
if (staticData['savedVideoPrompt_1']) {
  staticData['savedVideoPrompt_1'].usedKey = currentKey;
}

return [{
  json: {
    ...restoredData,
    usedKey: currentKey,
    code: 500, // force retry in Check Key Error IF node
    useBackupProvider: false,
    __video: sceneNum
  }
}];

// Handle Primary Video Success1 v2.0 — NO visualPrompt, NO imagePrompt
const inputData = $input.first().json;
let videoUrl = inputData.video_url || '';
if (!videoUrl) {
  if (inputData.resultVideo) videoUrl = inputData.resultVideo;
  else if (inputData.data?.resultVideo) videoUrl = inputData.data.resultVideo;
  else if (inputData.videoUrl) videoUrl = inputData.videoUrl;
  else if (inputData.data?.video_url) videoUrl = inputData.data.video_url;
  else throw new Error('Could not extract video URL from primary provider');
}
const staticData = $getWorkflowStaticData('global');
const sceneNum = 1;
const savedData = staticData['savedVideoPrompt_' + sceneNum] || {};
return { json: { videoUrl, status: 'completed', provider: 'primary', sceneIndex: savedData.sceneIndex ?? inputData.sceneIndex, sceneNumber: savedData.sceneNumber ?? sceneNum, voiceoverText: savedData.voiceoverText ?? inputData.voiceoverText, voiceStyle: savedData.voiceStyle ?? inputData.voiceStyle, speaker: savedData.speaker ?? inputData.speaker, videoPrompt: savedData.videoPrompt ?? inputData.videoPrompt, duration: savedData.duration ?? inputData.duration, title: savedData.title ?? inputData.title, corePlot: savedData.corePlot ?? inputData.corePlot, tags: savedData.tags ?? inputData.tags, youtubeDescription: savedData.youtubeDescription ?? inputData.youtubeDescription } };

// Reset all counters on success
let staticData = $getWorkflowStaticData('global');
const sceneNum = 1;
const attemptsName = `fruitVideoAttempts_${sceneNum}`;
const backupName = `fruitUseBackupVideo_${sceneNum}`;

staticData[attemptsName] = 0;
staticData[backupName] = false;

return $input.all();

const keys = $('Config: Backup Video Master1').first().json.keys;
let staticData = $getWorkflowStaticData('global');
const sceneNum = 1;

// ALWAYS read from static Filter Video Scene node (direct ancestor)
const vidFilter = $('Filter Video Scene1').first().json;

if (staticData['fruitBackupVideoIndex_1'] === undefined) {
  staticData['fruitBackupVideoIndex_1'] = sceneNum - 1;
}

const currentKeyIndex = staticData['fruitBackupVideoIndex_1'] % keys.length;
const currentKey = keys[currentKeyIndex];

// Construct clean prompt
let videoPrompt = vidFilter.videoPrompt || '';
videoPrompt = videoPrompt.replace(/"/g, "'").trim();

return [{
  json: {
    startImageUrl:      vidFilter.startImageUrl,
    videoPrompt:        videoPrompt,
    sceneIndex:         vidFilter.sceneIndex,
    sceneNumber:        sceneNum,
    voiceoverText:      vidFilter.voiceoverText || '',
    voiceStyle:         vidFilter.voiceStyle || '',
    speaker:            vidFilter.speaker || '',
    duration:           vidFilter.duration,
    title:              vidFilter.title,
    corePlot:           vidFilter.corePlot,
    tags:               vidFilter.tags,
    youtubeDescription: vidFilter.youtubeDescription,
    usedKey:            currentKey,
    __backupVideo:      sceneNum,
    __index:            currentKeyIndex
  }
}];

let staticData = $getWorkflowStaticData('global');
const keys = $('Config: Backup Video Master1').first().json.keys;
const totalKeys = keys.length;
const sceneNum = 1;

const inputRaw = ($input && $input.first()) ? $input.first().json : {};

// Check for HTTP 429 rate limit or call frequency errors
if (
  inputRaw.code == 429 || 
  inputRaw.code == "429" || 
  (inputRaw.data && (inputRaw.data.code == 429 || inputRaw.data.code == "429")) || 
  (inputRaw.msg && (inputRaw.msg.includes("frequency") || inputRaw.msg.includes("rate"))) ||
  (inputRaw.error && (inputRaw.error.status == 429 || inputRaw.error.statusCode == 429)) ||
  (inputRaw.message && inputRaw.message.includes("429"))
) {
  const delayMs = 5000 + (sceneNum * 2000);
  console.log(`[RATE LIMIT DETECTED] Scene ${sceneNum}: Waiting ${delayMs}ms before rotating key and retrying...`);
  await new Promise(resolve => setTimeout(resolve, delayMs));
}

// ALWAYS read from static Filter Video Scene node (direct ancestor)
const vidFilter = $('Filter Video Scene1').first().json;

// Retrieve saved backup prompt or fallback to vidFilter
let savedData = staticData['savedBackupVideoPrompt_1'] || {};

const restoredData = {
  startImageUrl:      savedData.startImageUrl      || vidFilter.startImageUrl,
  videoPrompt:        savedData.videoPrompt        || vidFilter.videoPrompt,
  voiceoverText:      savedData.voiceoverText      || vidFilter.voiceoverText || '',
  voiceStyle:         savedData.voiceStyle         || vidFilter.voiceStyle    || '',
  speaker:            savedData.speaker            || vidFilter.speaker       || '',
  duration:           savedData.duration           || vidFilter.duration,
  title:              savedData.title              || vidFilter.title,
  corePlot:           savedData.corePlot           || vidFilter.corePlot,
  tags:               savedData.tags               || vidFilter.tags,
  youtubeDescription: savedData.youtubeDescription || vidFilter.youtubeDescription,
  sceneIndex:         savedData.sceneIndex         || vidFilter.sceneIndex,
  sceneNumber:        sceneNum
};

if (staticData['fruitBackupVideoAttempts_1'] === undefined || staticData['fruitBackupVideoAttempts_1'] > totalKeys) {
  staticData['fruitBackupVideoAttempts_1'] = 0;
}
if (staticData['fruitBackupVideoIndex_1'] === undefined) {
  staticData['fruitBackupVideoIndex_1'] = sceneNum - 1;
}

staticData['fruitBackupVideoAttempts_1'] += 1;

if (staticData['fruitBackupVideoAttempts_1'] > totalKeys) {
  console.log(`All ${totalKeys} backup video API keys exhausted for scene ${sceneNum}.`);
  staticData['fruitBackupVideoIndex_1'] = sceneNum - 1;
  staticData['fruitBackupVideoAttempts_1'] = 0;
  throw new Error(`All backup video API keys (${totalKeys}) exhausted for scene ${sceneNum}.`);
}

// Rotate to NEXT key
staticData['fruitBackupVideoIndex_1'] = (staticData['fruitBackupVideoIndex_1'] + 1) % totalKeys;
const currentKeyIndex = staticData['fruitBackupVideoIndex_1'];
const currentKey = keys[currentKeyIndex];

console.log(`[BACKUP VIDEO ROTATION] Scene ${sceneNum} - Attempt ${staticData['fruitBackupVideoAttempts_1']}/${totalKeys}: Rotating to key index ${currentKeyIndex}`);

return [{
  json: {
    ...restoredData,
    usedKey: currentKey,
    __backupVideo: sceneNum,
    __index: currentKeyIndex
  }
}];

// Handle Backup Video Success1 v2.0 — NO visualPrompt, NO imagePrompt
const inputData = $input.first().json;
let videoUrl = inputData.video_url || '';
if (!videoUrl) {
  if (inputData.resultVideo) videoUrl = inputData.resultVideo;
  else if (inputData.data?.resultVideo) videoUrl = inputData.data.resultVideo;
  else if (inputData.videoUrl) videoUrl = inputData.videoUrl;
  else if (inputData.data?.video_url) videoUrl = inputData.data.video_url;
  else throw new Error('Could not extract video URL from backup provider');
}
const staticData = $getWorkflowStaticData('global');
const sceneNum = 1;
const savedData = staticData['savedVideoPrompt_' + sceneNum] || {};
return { json: { videoUrl, status: 'completed', provider: 'backup', sceneIndex: savedData.sceneIndex ?? inputData.sceneIndex, sceneNumber: savedData.sceneNumber ?? sceneNum, voiceoverText: savedData.voiceoverText ?? inputData.voiceoverText, voiceStyle: savedData.voiceStyle ?? inputData.voiceStyle, speaker: savedData.speaker ?? inputData.speaker, videoPrompt: savedData.videoPrompt ?? inputData.videoPrompt, duration: savedData.duration ?? inputData.duration, title: savedData.title ?? inputData.title, corePlot: savedData.corePlot ?? inputData.corePlot, tags: savedData.tags ?? inputData.tags, youtubeDescription: savedData.youtubeDescription ?? inputData.youtubeDescription } };

const staticData = $getWorkflowStaticData('global');
const sceneNum = 2;
const keys = $('Config: Primary Video Master2').first().json.keys;

// ALWAYS read from static filter nodes as the absolute source of truth!
const vidFilter = $('Filter Video Scene2').first().json;

if (staticData['videoKeyIndex_2'] === undefined) {
  staticData['videoKeyIndex_2'] = sceneNum - 1;
}
const currentKeyIndex = staticData['videoKeyIndex_2'] % keys.length;
const currentKey = keys[currentKeyIndex];
staticData['videoKeyIndex_2'] += 1;

// Write back to staticData (unconditional)
staticData['savedVideoPrompt_2'] = {
  startImageUrl:      vidFilter.startImageUrl,
  videoPrompt:        vidFilter.videoPrompt,
  sceneIndex:         vidFilter.sceneIndex,
  sceneNumber:        sceneNum,
  voiceoverText:      vidFilter.voiceoverText || '',
  voiceStyle:         vidFilter.voiceStyle    || '',
  speaker:            vidFilter.speaker       || '',
  duration:           vidFilter.duration,
  title:              vidFilter.title,
  corePlot:           vidFilter.corePlot,
  tags:               vidFilter.tags,
  youtubeDescription: vidFilter.youtubeDescription,
  usedKey:            currentKey
};

return {
  json: {
    startImageUrl:      vidFilter.startImageUrl,
    videoPrompt:        vidFilter.videoPrompt,
    sceneIndex:         vidFilter.sceneIndex,
    sceneNumber:        sceneNum,
    voiceoverText:      vidFilter.voiceoverText || '',
    voiceStyle:         vidFilter.voiceStyle    || '',
