const mergeData = $input.first().json;
const urlMap = {};
const keys = Object.keys(mergeData);

keys.forEach(k => {
  if (k === 'sceneNumber' || k.match(/^sceneNumber_\d+$/)) {
    const sceneNum = parseInt(mergeData[k], 10);
    let urlKey;
    if (k === 'sceneNumber') {
      urlKey = 'videoUrl';
    } else {
      const suffix = k.slice('sceneNumber'.length);
      urlKey = 'videoUrl' + suffix;
    }

    let finalUrl = mergeData[urlKey] || '';
    if (Array.isArray(finalUrl)) finalUrl = finalUrl[0];
    if (sceneNum && finalUrl) urlMap[sceneNum] = finalUrl;
  }
});

const staticData = $getWorkflowStaticData('global');
const script = staticData.islamicFullScript || {};
const fullScenes = script.scenes || [];

if (!fullScenes || fullScenes.length === 0) {
  return [{
    json: {
      mergeFailed: true,
      error: 'No scenes found in islamicFullScript. Check Split Scenes ran correctly.'
    }
  }];
}

return fullScenes.map((scene, index) => {
  const sceneNum = index + 1;
  return {
    json: {
      sceneNumber:        sceneNum,
      sceneIndex:         index,
      voiceoverText:      scene.voiceoverText || '',
      videoPrompt:        scene.videoPrompt || '',
      duration:           scene.duration || 15,
      title:              script.title || '',
      corePlot:           script.corePlot || '',
      tags:               script.tags || [],
      youtubeDescription: script.youtubeDescription || '',
      mainCharacter:      script.mainCharacter || '',
      category:           script.category || 'Education',
      url:                urlMap[sceneNum] || '',
      type:               'video'
    }
  };
});

// R11-G: build the comment from THIS video's data. No hardcoded story, no invented facts.
let ytData = {};   try { ytData = $('Dynamic User YouTube Upload').first().json || {}; } catch (e) {}
let splitScenes = {}; try { splitScenes = $('Split Scenes').first().json || {}; } catch (e) {}
let topicOut = {};    try { topicOut = $('Parse Topic Analyzer Output').first().json || {}; } catch (e) {}
let strategy = {};    try { strategy = $('Parse Strategy Output').first().json || {}; } catch (e) {}
let chatCtx = {};     try { chatCtx = $('Filter: My Chat Only').first().json || {}; } catch (e) {}

const videoId = ytData.uploadId || ytData.id || $input.first()?.json?.uploadId || $input.first()?.json?.id;
if (!videoId) {
  return [{ json: { skipped: true, reason: 'no videoId' } }];
}

const ctx = {
  topic: topicOut.detectedTopic || topicOut.topic || chatCtx.topic || '',
  title: splitScenes.title || chatCtx.title || '',
  storyBrief: chatCtx.storyBrief || chatCtx.brief || '',
  language: strategy.language || chatCtx.language || 'English'
};

const GENERIC = ['viral youtube short', 'viral story', 'viral video', 'shorts video', ''];
const clean = (s) => String(s || '').replace(/[#*_\x60\r\n]+/g, ' ').replace(/\s+/g, ' ').trim();
const usable = (s) => { const c = clean(s); return (c && !GENERIC.includes(c.toLowerCase())) ? c : ''; };

const subject = (usable(ctx.topic) || usable(ctx.title) || usable(String(ctx.storyBrief || '').split(/[.!?]/)[0])).slice(0, 70);
const lang = String(ctx.language || 'English').toLowerCase();
const isHinglish = lang.includes('hindi') || lang.includes('hinglish') || lang.includes('urdu');

let variants;
if (subject) {
  variants = isHinglish
    ? [
        subject + ' — aapka kya khayal hai? Comment mein batao 👇',
        'Aap ' + subject + ' ki jagah hote toh kya karte? Comment karo 👇',
        subject + ' ka end aapko kaisa laga? Ek line mein batao 👇'
      ]
    : [
        subject + ' — what is your take? Drop it in the comments 👇',
        'If you were in this situation, what would you have done? 👇',
        'Did the ending land for you? One line in the comments 👇'
      ];
} else {
  variants = isHinglish
    ? ['Is video ka end aapko kaisa laga? Comment mein batao 👇']
    : ['What did you think of the ending? Tell me in the comments 👇'];
}

// deterministic per video, so the same video always gets the same comment
let h = 0;
const vid = String(videoId);
for (let i = 0; i < vid.length; i++) { h = (h * 31 + vid.charCodeAt(i)) % 1000003; }
let comment = variants[h % variants.length];

const cta = isHinglish ? ' Aisi stories ke liye Subscribe 🔔' : ' Subscribe for more 🔔';
if ((comment + cta).length <= 200) comment += cta;

return [{ json: { videoId, comment, commentLanguage: isHinglish ? 'hinglish' : 'english', commentSubject: subject || null } }];

// ==========================================================
