// ---------- ANTI-REPETITION MEMORY v2 ----------
let sheetRows = [];
try { sheetRows = $('Read Past Topics').all().map(i => i.json || {}); } catch (e) { sheetRows = []; }

const recent = sheetRows.slice(-40);

const pick = (row, ...names) => {
  for (const n of names) {
    if (row[n] !== undefined && row[n] !== null && String(row[n]).trim() !== '') return String(row[n]).trim();
  }
