parameters.jsonBody:
={{ (() => {
  // ============================================================
  // STAGE 2 - SCREENWRITER  (Primary LLM Request)
  // Turns the Stage 1 blueprint into 5 shootable scenes:
  // voiceoverText (target language) + videoPrompt (English, multi-shot).
  // ============================================================
  let B = $json || {};
  if (!B.storyBrief && !B.sceneBreakdown) {
    try { B = $('Parse Strategy Output').first().json || {}; } catch (e) { B = {}; }
  }
  let T = {};
  try { T = $('Parse Topic Analyzer Output').first().json || {}; } catch (e) { T = {}; }

  const BT = String.fromCharCode(96);
  const S = function (v, d) {
    let s = (v === undefined || v === null) ? '' : String(v);
    s = s.split(BT).join("'").replace(/\$\{/g, '(');
    s = s.replace(/\s+/g, ' ').trim();
    return s ? s : (d || '');
  };
  const RAW = function (v, d) {
    let s = (v === undefined || v === null) ? '' : String(v);
    s = s.split(BT).join("'").replace(/\$\{/g, '(').trim();
    return s ? s : (d || '');
  };
  const L = function (v, d) {
    const a = Array.isArray(v) ? v : (v ? String(v).split(/\s*\|\s*/) : []);
    const o = a.map(function (x) { return S(x, ''); }).filter(Boolean);
    return o.length ? o.map(function (x, i) { return '  ' + (i + 1) + '. ' + x; }).join('\n') : (d || '  None');
  };
  const CS = function (v, d) {
    const a = Array.isArray(v) ? v : (v ? String(v).split(/\s*[|,]\s*/) : []);
    const o = a.map(function (x) { return S(x, ''); }).filter(Boolean);
    return o.length ? o.join(', ') : (d || 'None');
  };
  const N = function (v, d) { const n = Number(v); return (isFinite(n) && n > 0) ? n : d; };

  // ---------- the brief ----------
  const topic = RAW(B.specificTopic, RAW(T.specificTopic, 'Untitled topic'));
  const storyBrief = RAW(B.storyBrief, '');
  const storyShape = S(B.storyShape, 'Unspecified');
  const centralQ = RAW(B.centralQuestion, '');
  const theTurn = RAW(B.theTurn, '');
  const payoff = RAW(B.payoffLine, '');
  const viralHook = RAW(B.viralHook, '');
  const identity = S(B.identityLock, S(B.mainCharacterHint, ''));
  const mainChar = S(B.mainCharacter, identity);
  const supportChar = S(B.supportCharacter, 'none - single subject story');
  const personRole = S(B.personRole, 'Central Subject');
  const era = S(B.era, S(T.timeFrame, 'Modern'));
  const setting = S(B.setting, 'Unspecified location');
  const emoCore = S(B.emotionalCore, 'SUSPENSE');
  const viralAngle = RAW(B.viralAngle, '');
  const style = S(B.visualStyle, S(T.visualStyle, 'Cinematic Realistic'));
  const styleSpec = S(B.visualStyleDescription, style);
  const lang = S(B.language, S(T.language, 'Hinglish'));
  const cType = S(B.contentType, S(T.contentType, 'General'));
  const tone = S(B.toneStyle, S(T.toneStyle, 'Fast, intense, human'));
  const audience = S(B.targetAudience, 'Youth 15-35');
  const sugTitle = RAW(B.suggestedTitle, '');
  const sugTags = CS(B.suggestedTags, 'none supplied');
  const descOpener = RAW(B.youtubeDescriptionOpener, '');
  const warnings = S(B.contentWarnings, 'None');
  const anchorsList = CS(B.visualAnchors, 'none supplied - reuse one object of your own across all 5 prompts');
  const facts = L(B.factsAvailable, '  None supplied - use the facts already inside each scene job below');
  const required = L(B.requiredElements, '  None');
  const forbidden = L(B.forbiddenElements, '  None');
  const rejected = CS(B.rejectedAngles, 'None declared');
  const blockedTitles = S(B.blockedTitles, 'None');
  const recentChars = S(B.recentCharacters, 'None');
  const degraded = B.strategyDegraded === true;

  // ---------- creator ----------
  const cl = (B.creatorLock && typeof B.creatorLock === 'object') ? B.creatorLock : {};
  const clOn = cl.hasDirectives === true;
  const clText = RAW(B.creatorDirectiveText, 'None');
  const clLen = S(cl.lengthDemand, 'None');
  const clTone = S(cl.toneDemand, 'None');
  const clStruct = S(cl.structureDemand, 'None');

  // ---------- voice budget ----------
  const voMin = N(B.voCharMin, 221);
  const voMax = N(B.voCharMax, 249);
  const wMin = N(B.voWordMin, 36);
  const wMax = N(B.voWordMax, 40);
  const voNote = S(B.voBudgetNote, '');
  const voBias = S(B.voLengthBias, 'default');
  const wMid = Math.round((wMin + wMax) / 2);
  // ---------- the 5 scene jobs, rendered one at a time ----------
  const ACTS = ['HOOK', 'SETUP', 'BUILD', 'CLIMAX', 'RESOLUTION'];
  const DEF_INT = [8, 8, 9, 10, 8];
  const DEF_MOVE = [
    'slow push-in from a wide establishing frame to a mid on the subject',
    'lateral truck past a foreground layer that hides then exposes the subject',
    'crane down from a high wide to eye level, ending on the subject hands',
    'locked-off frame while the subject travels from far background until it fills the lens',
    'unbroken dolly-out from a macro detail to the full environment'
  ];
  const DEF_STATE = [
    'something in frame moves from closed to open',
    'the subject changes from still to moving',
    'an object in frame is lifted out of its place',
    'a surface breaks, spills or gives way',
    'the frame empties of everything except the subject'
  ];
  const DEF_LIGHT = [
    'one hard source at 0s, softened by 15s',
    'flat ambient at 0s, one practical switched on by 15s',
    'open light at 0s, a single shaft through shadow by 15s',
    'warm low light at 0s, cold hard top light by 15s',
    'harsh light at 0s, falling to one dim source by 15s'
  ];

  const sb = Array.isArray(B.sceneBreakdown) ? B.sceneBreakdown : [];
  const SCENES = [];
  for (let i = 0; i < 5; i++) {
    const s = (sb[i] && typeof sb[i] === 'object') ? sb[i] : {};
    const cam = S(s.cameraPlan, DEF_MOVE[i]);
    const stCh = S(s.stateChange, DEF_STATE[i]);
    const liCh = S(s.lightChange, DEF_LIGHT[i]);
    const bts = S(s.beats, '0s: open on the subject | 5s: ' + stCh + ' | 10s: ' + liCh);
    const inten = N(s.intensity, DEF_INT[i]);
    SCENES.push(
      'SCENE ' + (i + 1) + ' of 5   act ' + S(s.act, ACTS[i]) + '   intensity ' + inten + '/10\n' +
      '  job              : ' + S(s.beatFunction, S(s.purpose, ACTS[i] + ' beat')) + '\n' +
      '  fact to spend    : ' + S(s.factSpent, 'no fact assigned - pull one from the ammunition list above') + '\n' +
      '  narration content: ' + RAW(s.narrativeFocus, 'derive it from the job line above') + '\n' +
      '  what is in frame : ' + S(s.visualFocus, identity + ' in ' + setting) + '\n' +
      '  camera, one move : ' + cam + '\n' +
      '  state change     : ' + stCh + '\n' +
      '  light change     : ' + liCh + '\n' +
      '  timed beats      : ' + bts + '\n' +
      '  emotion          : ' + S(s.emotionalBeat, emoCore) + '\n' +
      '  delivery         : ' + S(s.pacingNotes, 'steady, no pauses, land the last word hard') + '\n' +
      '  ends on          : ' + RAW(s.endsOnQuestion, (i === 4 ? 'closed' : 'the question carried into the next scene'))
    );
  }
  const SCENE_BLOCK = SCENES.join('\n\n');
  // ---------- script policy: exactly one block is injected ----------
  let scriptLaw = '';
  if (lang === 'Hindi') {
    scriptLaw =
      'LANGUAGE: HINDI. SCRIPT: PURE DEVANAGARI, 100 percent.\n' +
      'Every voiceoverText, the title, corePlot and youtubeDescription are Devanagari only. Not one Roman letter.\n' +
      'Roman-script Hindi is FORBIDDEN. "Us raat teen baje" is rejected. The voice engine reads Roman letters as\n' +
      'English phonemes and every word comes out mispronounced. This single rule is the difference between a\n' +
      'video that sounds like a person and one that sounds broken.\n' +
      'Unavoidable proper nouns and modern terms get transliterated INTO Devanagari: रिपोर्ट, इंजिन, स्टेशन.\n' +
