  const voText = (scene.voiceoverText || scene.dialogue || scene.narration || '').trim();
  return { sceneNumber: sceneNum, voiceoverText: voText, videoPrompt: vidPrompt, duration: scene.duration || 15 };
});
const staticData = $getWorkflowStaticData('global');
staticData.fruitLastLlmProvider = 'primary';
if (finalJson.title) {
  if (!Array.isArray(staticData.fruitLastTopics)) staticData.fruitLastTopics = [];
  staticData.fruitLastTopics.push(finalJson.title);
  if (staticData.fruitLastTopics.length > 5) staticData.fruitLastTopics.shift();
}
if (finalJson.mainCharacter) {
  if (!Array.isArray(staticData.fruitLastCharacters)) staticData.fruitLastCharacters = [];
  staticData.fruitLastCharacters.push(finalJson.mainCharacter);
  if (staticData.fruitLastCharacters.length > 5) staticData.fruitLastCharacters.shift();
}
return {
  json: {
    title: finalJson.title || 'Islamic Story',
    corePlot: finalJson.corePlot || finalJson.core_plot || '',
    category: finalJson.category || 'Education',
    youtubeDescription: finalJson.youtubeDescription || finalJson.youtube_description || '',
    tags: Array.isArray(finalJson.tags) ? finalJson.tags : [],
    mainCharacter: finalJson.mainCharacter || finalJson.main_character || '',
    scenes: finalJson.scenes
  }
};

// Rotate Backup LLM Key — safely handles failover
