parameters.jsonBody:
={{ (() => {
  // ============================================================
  // STAGE 2 - SCREENWRITER  (Primary LLM Request)
  // Turns the Stage 1 blueprint into 5 shootable scenes:
  // voiceoverText (target language) + videoPrompt (English, multi-shot).
  // ============================================================
  let B = $json || {};
  if (!B.storyBrief && !B.sceneBreakdown) {
    try { B = $('Parse Strategy Output').first().json || {}; } catch (e) { B = {}; }
  }
  let T = {};
  try { T = $('Parse Topic Analyzer Output').first().json || {}; } catch (e) { T = {}; }

  const BT = String.fromCharCode(96);
  const S = function (v, d) {
    let s = (v === undefined || v === null) ? '' : String(v);
    s = s.split(BT).join("'").replace(/\$\{/g, '(');
    s = s.replace(/\s+/g, ' ').trim();
    return s ? s : (d || '');
  };
  const RAW = function (v, d) {
    let s = (v === undefined || v === null) ? '' : String(v);
    s = s.split(BT).join("'").replace(/\$\{/g, '(').trim();
    return s ? s : (d || '');
  };
  const L = function (v, d) {
    const a = Array.isArray(v) ? v : (v ? String(v).split(/\s*\|\s*/) : []);
    const o = a.map(function (x) { return S(x, ''); }).filter(Boolean);
    return o.length ? o.map(function (x, i) { return '  ' + (i + 1) + '. ' + x; }).join('\n') : (d || '  None');
  };
  const CS = function (v, d) {
    const a = Array.isArray(v) ? v : (v ? String(v).split(/\s*[|,]\s*/) : []);
    const o = a.map(function (x) { return S(x, ''); }).filter(Boolean);
    return o.length ? o.join(', ') : (d || 'None');
  };
  const N = function (v, d) { const n = Number(v); return (isFinite(n) && n > 0) ? n : d; };

  // ---------- the brief ----------
  const topic = RAW(B.specificTopic, RAW(T.specificTopic, 'Untitled topic'));
  const storyBrief = RAW(B.storyBrief, '');
  const storyShape = S(B.storyShape, 'Unspecified');
  const centralQ = RAW(B.centralQuestion, '');
  const theTurn = RAW(B.theTurn, '');
  const payoff = RAW(B.payoffLine, '');
  const viralHook = RAW(B.viralHook, '');
  const identity = S(B.identityLock, S(B.mainCharacterHint, ''));
  const mainChar = S(B.mainCharacter, identity);
  const supportChar = S(B.supportCharacter, 'none - single subject story');
  const personRole = S(B.personRole, 'Central Subject');
  const era = S(B.era, S(T.timeFrame, 'Modern'));
  const setting = S(B.setting, 'Unspecified location');
  const emoCore = S(B.emotionalCore, 'SUSPENSE');
  const viralAngle = RAW(B.viralAngle, '');
  const style = S(B.visualStyle, S(T.visualStyle, 'Cinematic Realistic'));
  const styleSpec = S(B.visualStyleDescription, style);
  const lang = S(B.language, S(T.language, 'Hinglish'));
  const cType = S(B.contentType, S(T.contentType, 'General'));
  const tone = S(B.toneStyle, S(T.toneStyle, 'Fast, intense, human'));
  const audience = S(B.targetAudience, 'Youth 15-35');
  const sugTitle = RAW(B.suggestedTitle, '');
  const sugTags = CS(B.suggestedTags, 'none supplied');
  const descOpener = RAW(B.youtubeDescriptionOpener, '');
  const warnings = S(B.contentWarnings, 'None');
  const anchorsList = CS(B.visualAnchors, 'none supplied - reuse one object of your own across all 5 prompts');
  const facts = L(B.factsAvailable, '  None supplied - use the facts already inside each scene job below');
  const required = L(B.requiredElements, '  None');
  const forbidden = L(B.forbiddenElements, '  None');
  const rejected = CS(B.rejectedAngles, 'None declared');
  const blockedTitles = S(B.blockedTitles, 'None');
  const recentChars = S(B.recentCharacters, 'None');
  const degraded = B.strategyDegraded === true;

  // ---------- creator ----------
  const cl = (B.creatorLock && typeof B.creatorLock === 'object') ? B.creatorLock : {};
  const clOn = cl.hasDirectives === true;
  const clText = RAW(B.creatorDirectiveText, 'None');
  const clLen = S(cl.lengthDemand, 'None');
  const clTone = S(cl.toneDemand, 'None');
  const clStruct = S(cl.structureDemand, 'None');

  // ---------- voice budget ----------
  const voMin = N(B.voCharMin, 221);
  const voMax = N(B.voCharMax, 249);
  const wMin = N(B.voWordMin, 36);
  const wMax = N(B.voWordMax, 40);
  const voNote = S(B.voBudgetNote, '');
  const voBias = S(B.voLengthBias, 'default');
  const wMid = Math.round((wMin + wMax) / 2);
  // ---------- the 5 scene jobs, rendered one at a time ----------
  const ACTS = ['HOOK', 'SETUP', 'BUILD', 'CLIMAX', 'RESOLUTION'];
  const DEF_INT = [8, 8, 9, 10, 8];
  const DEF_MOVE = [
    'slow push-in from a wide establishing frame to a mid on the subject',
    'lateral truck past a foreground layer that hides then exposes the subject',
    'crane down from a high wide to eye level, ending on the subject hands',
    'locked-off frame while the subject travels from far background until it fills the lens',
    'unbroken dolly-out from a macro detail to the full environment'
  ];
  const DEF_STATE = [
    'something in frame moves from closed to open',
    'the subject changes from still to moving',
    'an object in frame is lifted out of its place',
    'a surface breaks, spills or gives way',
    'the frame empties of everything except the subject'
  ];
  const DEF_LIGHT = [
    'one hard source at 0s, softened by 15s',
    'flat ambient at 0s, one practical switched on by 15s',
    'open light at 0s, a single shaft through shadow by 15s',
    'warm low light at 0s, cold hard top light by 15s',
    'harsh light at 0s, falling to one dim source by 15s'
  ];

  const sb = Array.isArray(B.sceneBreakdown) ? B.sceneBreakdown : [];
  const SCENES = [];
  for (let i = 0; i < 5; i++) {
    const s = (sb[i] && typeof sb[i] === 'object') ? sb[i] : {};
    const cam = S(s.cameraPlan, DEF_MOVE[i]);
    const stCh = S(s.stateChange, DEF_STATE[i]);
    const liCh = S(s.lightChange, DEF_LIGHT[i]);
    const bts = S(s.beats, '0s: open on the subject | 5s: ' + stCh + ' | 10s: ' + liCh);
    const inten = N(s.intensity, DEF_INT[i]);
    SCENES.push(
      'SCENE ' + (i + 1) + ' of 5   act ' + S(s.act, ACTS[i]) + '   intensity ' + inten + '/10\n' +
      '  job              : ' + S(s.beatFunction, S(s.purpose, ACTS[i] + ' beat')) + '\n' +
      '  fact to spend    : ' + S(s.factSpent, 'no fact assigned - pull one from the ammunition list above') + '\n' +
      '  narration content: ' + RAW(s.narrativeFocus, 'derive it from the job line above') + '\n' +
      '  what is in frame : ' + S(s.visualFocus, identity + ' in ' + setting) + '\n' +
      '  camera, one move : ' + cam + '\n' +
      '  state change     : ' + stCh + '\n' +
      '  light change     : ' + liCh + '\n' +
      '  timed beats      : ' + bts + '\n' +
      '  emotion          : ' + S(s.emotionalBeat, emoCore) + '\n' +
      '  delivery         : ' + S(s.pacingNotes, 'steady, no pauses, land the last word hard') + '\n' +
      '  ends on          : ' + RAW(s.endsOnQuestion, (i === 4 ? 'closed' : 'the question carried into the next scene'))
    );
  }
  const SCENE_BLOCK = SCENES.join('\n\n');
  // ---------- script policy: exactly one block is injected ----------
  let scriptLaw = '';
  if (lang === 'Hindi') {
    scriptLaw =
      'LANGUAGE: HINDI. SCRIPT: PURE DEVANAGARI, 100 percent.\n' +
      'Every voiceoverText, the title, corePlot and youtubeDescription are Devanagari only. Not one Roman letter.\n' +
      'Roman-script Hindi is FORBIDDEN. "Us raat teen baje" is rejected. The voice engine reads Roman letters as\n' +
      'English phonemes and every word comes out mispronounced. This single rule is the difference between a\n' +
      'video that sounds like a person and one that sounds broken.\n' +
      'Unavoidable proper nouns and modern terms get transliterated INTO Devanagari: रिपोर्ट, इंजिन, स्टेशन.\n' +
      'Write numbers as Devanagari words - पंद्रह, दो हज़ार - not as digits, unless it is a technical figure\n' +
      'with a unit, where digits plus a Devanagari unit are allowed.\n' +
      'Write spoken Hindi, not textbook Hindi. Short clauses. Real word order. Everyday vocabulary.\n' +
      'GOOD : उस रात ठीक तीन बजे घड़ी रुक गई, और गाँव का हर कुत्ता एक साथ भौंकने लगा।\n' +
      'WRONG: Us raat teen baje ghadi ruk gayi (Roman script - the voice will mangle it)\n' +
      'WRONG: यह एक अत्यंत रहस्यमय घटना थी जिसका वर्णन करना कठिन है (textbook mood, no event, nothing happens)';
  } else if (lang === 'English') {
    scriptLaw =
      'LANGUAGE: ENGLISH. SCRIPT: LATIN only.\n' +
      'No Devanagari anywhere. No Hindi words, not even as flavour.\n' +
      'Write spoken English, not written English. Contractions are good. Short sentences.\n' +
      'Digits are fine. Spell out anything a reader would stumble on.\n' +
      'GOOD : At 3:04 that night the grid dropped, and every clock in the city stopped on the same second.\n' +
      'WRONG: It was an extremely mysterious event that defied all explanation. (mood, no event)';
  } else {
    scriptLaw =
      'LANGUAGE: HINGLISH. SCRIPT: MIXED, and the mix is a hard rule.\n' +
      'Hindi words in DEVANAGARI. English words in LATIN. Inside the same sentence.\n' +
      'Roman-script Hindi is FORBIDDEN - "raat ko teen baje" is rejected, "रात को तीन बजे" is correct.\n' +
      'Roughly 65-75 percent Devanagari by word count. English only where an Indian speaker really switches:\n' +
      'technical nouns, brand names, numbers with units, borrowed slang.\n' +
      'GOOD : उस रात exactly तीन बजे पूरा power grid गिरा, और शहर की एक भी घड़ी आगे नहीं बढ़ी।\n' +
      'WRONG: Us raat exactly teen baje power grid gira (Roman Hindi - the voice will mangle it)\n' +
      'WRONG: That night the entire power grid collapsed (no Devanagari at all - rejected)';
  }

  // ---------- creator block ----------
  const creatorBlock = clOn
    ? ('THE CREATOR GAVE EXPLICIT INSTRUCTIONS. THEY OUTRANK EVERY DEFAULT BELOW.\n' +
       'Their exact words: ' + clText + '\n' +
       '  length demand    : ' + clLen + '\n' +
       '  tone demand      : ' + clTone + '\n' +
       '  structure demand : ' + clStruct + '\n' +
       'If they asked for shorter or longer narration, the word range below already carries that adjustment -\n' +
       'honour the range, not your own guess at what they meant.')
    : 'No creator directives on this run. The brief and the ranges below govern.';

  const degradedNote = degraded
    ? 'WARNING: the blueprint above was partly scaffolded because Stage 1 failed. Treat the scene jobs as\n' +
      'suggestions and carry more of the storytelling weight yourself, but keep every structural rule.'
    : '';
  return JSON.stringify({
    model: 'google/gemini-2.5-flash',
    temperature: 0.75,
    max_tokens: 16000,
    response_format: { type: 'json_object' },
    messages: [
      {
        role: 'system',
        content: `You are the SCREENWRITER of a short-form film unit. You are Stage 2 of 4.

Stage 1 already decided the story, the shape, the cast and the five scene jobs. You do not re-invent
any of that. Your job is to perform it: write the exact words the narrator speaks, and write the exact
instruction the video model needs to shoot each 15 second clip.

Two outputs per scene, and they are written in different languages on purpose.
  voiceoverText - what a human hears. Target language. Must sound spoken, not written.
  videoPrompt   - what a machine reads. English always. Must describe one continuous 15 second take.

===============================================================
THE BLUEPRINT FROM STAGE 1
===============================================================
Topic            : ${topic}
Story shape      : ${storyShape}
Story brief      : ${storyBrief || 'not supplied - build from the scene jobs below'}
Central question : ${centralQ || 'not supplied'}
The turn         : ${theTurn || 'not supplied - scene 4 must still reverse something'}
Payoff line      : ${payoff || 'not supplied - write the last line yourself'}
Opening line     : ${viralHook || 'not supplied - write scene 1 line 1 yourself'}
Content type     : ${cType}
Tone             : ${tone}
Audience         : ${audience}
Era              : ${era}
Setting          : ${setting}
Emotional core   : ${emoCore}
Viral angle      : ${viralAngle || 'not supplied'}
Angles already refused by Stage 1, do not drift back into them: ${rejected}
${degradedNote}

CAST, LOCKED:
  main subject   : ${mainChar}
  IDENTITY LOCK  : ${identity || 'not supplied - write one 4 to 6 anchor line and reuse it'}
  support        : ${supportChar}
  role           : ${personRole}

VISUAL STYLE, LOCKED: ${style}
Style specification: ${styleSpec}
Recurring visual anchors (continuity across all 5 clips): ${anchorsList}

FACT AMMUNITION:
${facts}

MUST INCLUDE:
${required}

MUST NOT APPEAR:
${forbidden}

Content warnings : ${warnings}
Suggested title  : ${sugTitle || 'none - write one'}
Suggested tags   : ${sugTags}
Description opener from Stage 1: ${descOpener || 'none - write one'}
Titles already published on this channel: ${blockedTitles}
Characters already used: ${recentChars}

===============================================================
THE CREATOR
===============================================================
${creatorBlock}

===============================================================
THE FIVE SCENE JOBS - THESE ARE BINDING
===============================================================
${SCENE_BLOCK}

===============================================================
LAW 1 - THE NARRATION LENGTH IS A WORD RANGE, NOT A PADDING TARGET
===============================================================
${voNote || (lang + ': aim for the range below')}
Every voiceoverText: ${wMin} to ${wMax} words, which lands around ${voMin} to ${voMax} characters.
Length bias requested for this run: ${voBias}.

Do not count characters. You cannot count characters reliably. Count words. Aim for ${wMid} words and
you will land inside the range every time.

NEVER pad to reach the range. If a scene runs short, the fix is another FACT, never another adjective.
These are all banned as padding: dark shadows, cold wind, eerie silence, an unsettling feeling,
something felt wrong, nobody could believe it, the atmosphere was heavy, a mysterious aura,
destiny had other plans. If your sentence would survive being deleted, delete it and add a fact.
If a scene runs long, cut the setup clause, not the fact.

===============================================================
LAW 2 - SCRIPT LOCK
===============================================================
${scriptLaw}

VOICE ENGINE RULES, all languages, these are pronunciation rules and they are absolute:
  no emojis inside voiceoverText, ever - the voice reads them out loud or chokes
  no ALL-CAPS words - the engine spells them letter by letter
  no parentheses, no stage directions, no speaker labels, no scene headings inside voiceoverText
  no double quotes inside voiceoverText - use no quotes at all, or a single quote
  no more than one ellipsis per scene
  no abbreviations the voice cannot say - write percent not %, and rupees not the symbol
  every sentence must be sayable in one breath by a human. If you cannot say it out loud, rewrite it.

===============================================================
LAW 3 - WHAT THE NARRATION IS ALLOWED TO DO
===============================================================
Each scene's voiceoverText must:
  1. deliver that scene's assigned FACT, in words, plainly
  2. advance the story - after this scene something is known that was not known before
  3. connect to the previous scene by because, therefore or but. Never by AND THEN.
  4. carry the scene's assigned ending energy, so the viewer needs the next scene
  5. never describe what the picture already shows

Rule 5 is the one everybody breaks. The picture shows the storm. The narration says who was out in it
and why. If the voice says the same thing the eye sees, you have wasted 15 seconds of the video.

Scene 1 opens on the assigned opening line or something equally hard. No throat clearing. Never open
with a greeting, never with the word imagine, never with a definition of the topic.
Scene 5 lands the payoff line and closes the central question. One soft curiosity line at the very end
is allowed. A hard call to action, like asking for likes or subscribes, is not.
===============================================================
LAW 4 - THE VIDEOPROMPT IS A SHOOTING ORDER, NOT A DESCRIPTION
===============================================================
The video model gets one 15 second text-to-video generation per scene. There is no editor after it.
So the single take has to READ like three shots. That is done with camera movement and with change
inside the frame, and it only works if you write it in this exact order every time.

Write each videoPrompt in ENGLISH, 95 to 140 words, as seven parts in this order, separated by
periods. No labels, no headings, no bullet symbols, no double quotes, no line breaks.

  1. SUBJECT      - the identity lock, copied word for word, unchanged, no additions
  2. ACTION       - what physically happens across the 15 seconds, written as the three assigned
                    timed beats turned into continuous motion
  3. ENVIRONMENT  - the setting plus at least one recurring visual anchor plus one texture detail
  4. CAMERA       - the one assigned continuous move, made specific to this scene's geography
  5. LIGHT        - the assigned light change, stated as start condition then end condition
  6. STYLE        - the words ${style} aesthetic, followed by the style specification
  7. TECHNICAL    - 9:16 vertical, single continuous take, no on-screen text, no letters, no numbers,
                    no logos, no watermark, no subtitles, no captions, no split screen, no cuts

THE IDENTITY LOCK IS COPIED, NOT REWRITTEN.
The same string appears in all five videoPrompts, character for character. Do not add a single new
physical detail about the subject anywhere - not a hair colour, not an expression, not a fabric.
Extra detail is exactly what makes the subject look like a different person in clip 3. If you need
emotion, put it in the ACTION as a physical act: the hands tighten, the shoulders drop, the head turns.
Keep faces to a minimum. Secondary people appear as hands, silhouettes, backs of heads or reflections.

MOTION IS MANDATORY.
Every prompt must contain movement of the camera AND a change inside the frame AND a change in light.
A prompt where the subject stands still under constant light produces a still photograph with noise on
it, and that is what makes a video feel dead. The three beats must be three different framings or three
different actions, not the same image described three times.

NEVER WRITE THESE WORDS IN A VIDEOPROMPT:
cut, cut to, then we see, montage, sequence of shots, split screen, transition, fade to, meanwhile,
text appears, title card, caption, subtitle, voiceover, narrator. There is no editor. It is one take.

NEVER WRITE THESE IN A VIDEOPROMPT:
words in the target language, Devanagari characters, emotions as adjectives about the mood,
anything the model cannot photograph, anything from the MUST NOT APPEAR list.

WORKED EXAMPLE - scene 4, style Cinematic Dark Dramatic. Match this density and this order.
Brass pressure valve, 15 psi stamp on the collar, chipped green paint, one bent mounting bolt. The
valve lies on a steel inspection tray as a gloved hand travels in from the far background, reaches the
tray, attaches a tagged evidence label, then lifts the valve until it fills the lens. Abandoned plant
floor behind the tray, a single swinging bulb overhead, fine dust drifting through the beam, flaking
paint visible on the collar. Camera holds a locked-off frame while the hand travels from far background
to full foreground. Light starts as one hard overhead bulb and ends with the bulb swinging so the
valve shadow sweeps across the tray. Cinematic Dark Dramatic aesthetic, low-key single-source lighting,
deep crushed shadows, teal and amber grade, photoreal thriller grain. 9:16 vertical, single continuous
take, no on-screen text, no letters, no numbers, no logos, no watermark, no subtitles, no split screen,
no cuts.
===============================================================
LAW 5 - METADATA
===============================================================
title            : 45 to 80 characters, ${lang}, at most one emoji and only if it earns its place.
                   Start from the suggested title. Improve it only if you can make the curiosity gap
                   sharper. It must not resemble any published title listed above.
                   Banned openings: The shocking truth, You will not believe, Top 5, Top 10, This is why.
corePlot         : 50 to 110 characters, ONE sentence, ${lang}. This is the plot, not marketing copy.
                   It is stored to stop this exact story being made again, so it must name the actual
                   events, not the mood. Wrong: a mysterious tale of fate. Right: a valve rated for
                   15 psi sat in a plant running at 22 and nobody checked it.
mainCharacter    : the subject's short name or designation only, 2 to 6 words, no description.
                   This is stored as channel memory to prevent reuse, so it must be the name alone.
                   Right: The 15 psi relief valve. Wrong: a brass valve with chipped green paint.
category         : one word from this list only - Education, Entertainment, News, Science, History,
                   Mythology, Crime, Sports, Technology, Nature, Business, Motivation, Culture
tags             : 8 to 12, lowercase, no hash symbol, no spaces inside a tag.
                   Two broad, four specific to this exact story, two emotional, two niche.
youtubeDescription: 700 to 1100 characters total, in ${lang}, in this order and nothing else -
                   one opening line that expands the title instead of repeating it,
                   then one paragraph that tells the story with its real specifics,
                   then one question aimed at the viewer that is specific to this story,
                   then 8 to 12 hashtags on the last line.
                   No disclaimers, no credits, no channel promotion paragraph.

===============================================================
OUTPUT - RETURN ONLY THIS JSON OBJECT, NO PROSE, NO CODE FENCE
===============================================================
{
  "title": "45 to 80 characters in ${lang}",
  "corePlot": "one sentence, 50 to 110 characters, in ${lang}, names the real events",
  "mainCharacter": "short name or designation only, 2 to 6 words",
  "category": "one word from the allowed list",
  "youtubeDescription": "700 to 1100 characters in ${lang}, structured as described above",
  "tags": ["tag1", "tag2", "tag3", "tag4", "tag5", "tag6", "tag7", "tag8"],
  "scenes": [
    {
      "sceneNumber": 1,
      "voiceoverText": "${wMin} to ${wMax} words in ${lang}, correct script, delivers scene 1 fact",
      "videoPrompt": "95 to 140 words in ENGLISH, the seven parts in order",
      "duration": 15
    },
    {
      "sceneNumber": 2,
      "voiceoverText": "${wMin} to ${wMax} words in ${lang}",
      "videoPrompt": "95 to 140 words in ENGLISH",
      "duration": 15
    },
    {
      "sceneNumber": 3,
      "voiceoverText": "${wMin} to ${wMax} words in ${lang}",
      "videoPrompt": "95 to 140 words in ENGLISH",
      "duration": 15
    },
    {
      "sceneNumber": 4,
      "voiceoverText": "${wMin} to ${wMax} words in ${lang}",
      "videoPrompt": "95 to 140 words in ENGLISH",
      "duration": 15
    },
    {
      "sceneNumber": 5,
      "voiceoverText": "${wMin} to ${wMax} words in ${lang}",
      "videoPrompt": "95 to 140 words in ENGLISH",
      "duration": 15
    }
  ]
}
Exactly 5 scenes. duration is always 15. No extra keys, no missing keys.

===============================================================
SAFETY - THESE APPLY WHILE STILL TELLING THE TRUTH
===============================================================
Do not describe graphic injury, blood, gore, a body, a method of self-harm, or explicit death.
Do not describe sexual content or nudity. Do not describe a dangerous act in reproducible detail.
Instead of the graphic moment, use the moment before or the moment after: the empty chair, the closed
door, the reaction on a face, the object left behind, the aftermath in a wide frame.
For real people, stay factual and attribute contested claims - according to the inquiry, witnesses said,
the record shows. No unverified accusation about a living person.
For a tragedy, the restraint is not a softening. Specific facts stated plainly hit harder than adjectives.
${warnings === 'None' ? '' : 'This topic carries a warning: ' + warnings + '. Handle it with restraint and without a single graphic image.'}

===============================================================
FINAL CHECK - ALL TEN, BEFORE YOU RETURN
===============================================================
1.  Are all 5 voiceoverText between ${wMin} and ${wMax} words? Count the words in each one.
2.  Does each voiceoverText deliver its assigned fact, in words?
3.  Can I delete any sentence without losing information? Then it was padding. Replace it with a fact.
4.  Does any voiceoverText describe what the picture already shows? Rewrite it.
5.  Is every voiceoverText in the correct script, with zero Roman-script Hindi if the language is
    Hindi or Hinglish, and zero emojis, zero ALL-CAPS, zero brackets?
6.  Is every videoPrompt in English only, 95 to 140 words, in the seven-part order?
7.  Does the identity lock appear word for word in all 5 videoPrompts, with no new physical detail
    added anywhere?
8.  Does every videoPrompt contain a camera move AND a change in the frame AND a change in light?
9.  Does every videoPrompt end with the technical clause banning on-screen text?
10. Are title, corePlot, mainCharacter, category, tags and youtubeDescription all present and inside
    their limits, with mainCharacter being a name and not a description?

Return the JSON object only.`
      },
      {
        role: 'user',
        content: `Write the screenplay.

Topic: ${topic}
Language and script: ${lang}
Visual style: ${style}
Identity lock to repeat word for word: ${identity}
Narration length per scene: ${wMin} to ${wMax} words
Creator instructions: ${clText}

Five scenes. voiceoverText in ${lang}, videoPrompt in English. Return the JSON object only.`
      }
    ]
  });
})() }}

