// Rotate Backup LLM On Failure — safely rotates backup keys & stops when exhausted
const backupFallbackKeys = [
  "e8dddcdad5msh80e5a3d80b70d34p15eeffjsn5954cc89f72f",
  "c822c4293emsh61f15bb9eeabb99p14956cjsn1fa2f74ad9f1",
  "2b015b49e7msha9808f1d1ae6654p178d39jsn886507cf88a8",
  "54df5cbe66msh5a2f44867ada346p18df76jsn336df21434a7",
  "c056caf42emsh31e2a3a34483eb4p19cccfjsn41c571dc31bd"
];

let keys = backupFallbackKeys;
try {
  const master = $('Config: Backup LLM Master').first().json;
  if (master && master.keys && master.keys.length > 0) keys = master.keys;
} catch(e) {}

let staticData = $getWorkflowStaticData('global');
const totalKeys = keys.length;
const firstItem = $input.first() || { json: {} };

if (staticData.fruitBackupLlmAttempts === undefined) {
  staticData.fruitBackupLlmAttempts = 0;
}

staticData.fruitBackupLlmAttempts += 1;

if (staticData.fruitBackupLlmAttempts >= totalKeys) {
  console.log(`All ${totalKeys} backup LLM API keys exhausted. Stopping workflow.`);
  staticData.fruitBackupLlmIndex = 0;
  staticData.fruitBackupLlmAttempts = 0;
  staticData.fruitUseBackupLlm = false;

  throw new Error(`All backup LLM API keys (${totalKeys}) have been exhausted. Please add more API keys or try again later.`);
}

staticData.fruitBackupLlmIndex = (staticData.fruitBackupLlmIndex || 0) + 1;
console.log(`Backup LLM Attempt ${staticData.fruitBackupLlmAttempts}/${totalKeys}: Rotating to key index ${staticData.fruitBackupLlmIndex}`);

return [firstItem];

// Handle Backup LLM Success v5.0 — Clean 4-Key Schema | NO imagePrompt | NO visualPrompt
function extractContent(response) {
  if (!response) return '';
  const r = Array.isArray(response) ? response[0] : response;
  if (!r) return '';
  if (r.choices && r.choices[0]) return r.choices[0].message?.content || r.choices[0].text || '';
  if (r.data && r.data.choices && r.data.choices[0]) return r.data.choices[0].message?.content || '';
  if (r.output && Array.isArray(r.output) && r.output[0]) {
    const f = r.output[0];
    if (f.content && Array.isArray(f.content) && f.content[0] && f.content[0].text) return f.content[0].text;
    if (f.message && f.message.content) return f.message.content;
    if (f.text) return f.text;
    if (typeof f === 'string') return f;
  }
  if (r.output) return typeof r.output === 'string' ? r.output : JSON.stringify(r.output);
  return r.content || r.response || r.text || (typeof r === 'string' ? r : JSON.stringify(r));
}

function masterCleanAndParseJSON(raw) {
  if (!raw) return null;
  let cleaned = typeof raw === 'string' ? raw.trim() : JSON.stringify(raw);
  const firstCurly = cleaned.indexOf('{');
  const firstSquare = cleaned.indexOf('[');
  let firstIndex = -1;
  if (firstCurly !== -1 && firstSquare !== -1) firstIndex = Math.min(firstCurly, firstSquare);
  else if (firstCurly !== -1) firstIndex = firstCurly;
  else if (firstSquare !== -1) firstIndex = firstSquare;
  const lastCurly = cleaned.lastIndexOf('}');
  const lastSquare = cleaned.lastIndexOf(']');
  const lastIndex = Math.max(lastCurly, lastSquare);
  if (firstIndex !== -1 && lastIndex !== -1 && lastIndex > firstIndex) cleaned = cleaned.substring(firstIndex, lastIndex + 1);
  try { return JSON.parse(cleaned); } catch (e1) {}
  let repaired = cleaned.replace(/,\s*([\}\]])/g, '$1').replace(/[\u0000-\u001F\u007F-\u009F]/g, '');
  let inString = false, escape = false, sanitized = '';
  for (let i = 0; i < repaired.length; i++) {
    let ch = repaired[i];
    if (escape) { sanitized += ch; escape = false; continue; }
    if (ch === '\\') { sanitized += ch; escape = true; continue; }
    if (ch === '"') { inString = !inString; sanitized += ch; continue; }
    if (inString) {
      if (ch === '\n') { sanitized += '\\n'; continue; }
      if (ch === '\r') { sanitized += '\\r'; continue; }
    }
    sanitized += ch;
  }
  let stack = [], balanced = '';
  inString = false; escape = false;
  for (let i = 0; i < sanitized.length; i++) {
    let ch = sanitized[i];
    if (escape) { balanced += ch; escape = false; continue; }
    if (ch === '\\') { balanced += ch; escape = true; continue; }
    if (ch === '"') { inString = !inString; balanced += ch; continue; }
    if (!inString) {
      if (ch === '{' || ch === '[') stack.push(ch);
      else if (ch === '}') { if (stack.length > 0 && stack[stack.length-1] === '{') stack.pop(); }
      else if (ch === ']') { if (stack.length > 0 && stack[stack.length-1] === '[') stack.pop(); }
    }
    balanced += ch;
  }
  while (stack.length > 0) { let top = stack.pop(); if (top === '{') balanced += '}'; else if (top === '[') balanced += ']'; }
  balanced = balanced.replace(/,\s*([\}\]])/g, '$1');
  try { return JSON.parse(balanced); } catch (e2) {}
  throw new Error('Backup JSON Repair unable to parse');
}

const response = $input.first().json;
if (response.status === 'incomplete') throw new Error('LLM output incomplete');
let aiOutput = extractContent(response);
if (!aiOutput || aiOutput.trim() === '') throw new Error('Backup LLM returned empty response');
let finalJson;
try { finalJson = masterCleanAndParseJSON(aiOutput); } catch(e) { throw new Error('Backup LLM invalid JSON: ' + aiOutput.substring(0, 400)); }
if (!finalJson) throw new Error('Backup parsed JSON is null');
if (Array.isArray(finalJson)) finalJson = { scenes: finalJson };
if (finalJson.scenes && Array.isArray(finalJson.scenes)) {
  finalJson.scenes = finalJson.scenes.filter(s => (s.voiceoverText || s.narration || s.videoPrompt));
}
if (!finalJson.scenes || !Array.isArray(finalJson.scenes) || finalJson.scenes.length === 0) {
  throw new Error('Backup LLM response missing scenes');
}
// STRICT 4-KEY OUTPUT: NO imagePrompt, NO visualPrompt
finalJson.scenes = finalJson.scenes.map((scene, i) => {
  const sceneNum = scene.sceneNumber || scene.scene || (i + 1);
  const vidPrompt = (scene.videoPrompt || scene.video_prompt || '').trim();
  const voText = (scene.voiceoverText || scene.dialogue || scene.narration || '').trim();
  return { sceneNumber: sceneNum, voiceoverText: voText, videoPrompt: vidPrompt, duration: scene.duration || 15 };
});
const staticData = $getWorkflowStaticData('global');
staticData.fruitLastLlmProvider = 'backup';
if (finalJson.title) {
  if (!Array.isArray(staticData.fruitLastTopics)) staticData.fruitLastTopics = [];
  staticData.fruitLastTopics.push(finalJson.title);
  if (staticData.fruitLastTopics.length > 5) staticData.fruitLastTopics.shift();
}
return {
  json: {
    title: finalJson.title || 'Islamic Story',
    corePlot: finalJson.corePlot || finalJson.core_plot || '',
    category: finalJson.category || 'Education',
    youtubeDescription: finalJson.youtubeDescription || finalJson.youtube_description || '',
    tags: Array.isArray(finalJson.tags) ? finalJson.tags : [],
    mainCharacter: finalJson.mainCharacter || finalJson.main_character || '',
    scenes: finalJson.scenes
  }
};

const script = $input.first().json;
const scenes = script.scenes || [];

const staticData = $getWorkflowStaticData('global');
staticData.islamicFullScript = script;
staticData.islamicTotalScenes = scenes.length;

// Reset all per-scene counters (10 scenes)
for (let i = 1; i <= 10; i++) {
  staticData['isl_prim_key_idx_s' + i] = 0;
  staticData['isl_prim_attempts_s' + i] = 0;
  staticData['isl_backup_key_idx_s' + i] = 0;
  staticData['isl_backup_attempts_s' + i] = 0;
}

return scenes.map((scene, index) => ({
  json: {
    sceneIndex: index,
    sceneNumber: index + 1,
    totalScenes: scenes.length,
    voiceoverText: scene.voiceoverText || '',
    videoPrompt: scene.videoPrompt || '',
    duration: scene.duration || 15,
    title: script.title || '',
    corePlot: script.corePlot || '',
    category: script.category || 'Education',
    mainCharacter: (script.mainCharacter || '').toString().trim(),
    tags: script.tags || [],
    youtubeDescription: script.youtubeDescription || ''
  }
}));

// Config: Critic LLM Master (Primary)
let staticData = $getWorkflowStaticData('global');
const inputItem = $input.first();

let storyData = {};
if (inputItem && inputItem.json) {
  if (inputItem.json.retry) {
    storyData = staticData.fruitSavedScriptPrimary || {};
  } else {
    storyData = inputItem.json;
    staticData.fruitSavedScriptPrimary = storyData;
  }
} else {
  storyData = staticData.fruitSavedScriptPrimary || {};
}

const activeKeys = ($('Config: Primary LLM Master').first().json.keys) || [];

return {
  json: {
    keys: activeKeys,
    story: storyData,
    retry: (inputItem && inputItem.json && inputItem.json.retry) || false
  }
};

// Rotate API key for the Story Quality Critic LLM (Primary)
let staticData = $getWorkflowStaticData('global');
const config = $('Config: Critic LLM Master (Primary)').first().json;
const keys = config.keys || [];

if (staticData.fruitCriticKeyIndexPrimary === undefined) {
  staticData.fruitCriticKeyIndexPrimary = 0;
}

const key = keys[staticData.fruitCriticKeyIndexPrimary % keys.length];
staticData.fruitCriticKeyIndexPrimary += 1;

if (!config.retry) {
  staticData.fruitCriticAttemptsPrimary = 0;
}

return {
  json: {
    ...config.story,
    usedKey: key,
    __criticCall: true,
    retry: config.retry || false
  }
};

