// Check Critic Error (Primary)
const response = $input.first().json;
let staticData = $getWorkflowStaticData('global');
const keys = ($('Config: Critic LLM Master (Primary)').first().json.keys) || [];
const totalKeys = keys.length || 5;

const hasError = !!(
  response.error || 
  response.errorMessage || 
  response.errorDescription ||
  (response.data && (response.data.error || response.data.errorMessage)) ||
  (response.errorDetails && response.errorDetails.httpCode) ||
  response.code
);

if (hasError) {
  if (staticData.fruitCriticAttemptsPrimary === undefined) {
    staticData.fruitCriticAttemptsPrimary = 0;
  }
  staticData.fruitCriticAttemptsPrimary += 1;

  if (staticData.fruitCriticAttemptsPrimary <= totalKeys) {
    console.log(`[CRITIC ERROR] Key failed. Attempt ${staticData.fruitCriticAttemptsPrimary}/${totalKeys}. Rotating key and retrying...`);
    return {
      json: {
        status: "retry",
        retry: true,
        originalResponse: response
      }
    };
  } else {
    console.log(`[CRITIC ERROR] Max attempts (${totalKeys}) reached. Bypassing critic.`);
    staticData.fruitCriticAttemptsPrimary = 0;
    return {
      json: {
        status: "bypass",
        originalResponse: response
      }
    };
  }
}

staticData.fruitCriticAttemptsPrimary = 0;
return {
  json: {
    status: "success",
    ...response
  }
};

// Parse Critic Output v4.0 — Clean 4-Key Schema | NO imagePrompt | NO visualPrompt
function extractContent(response) {
  if (!response) return '';
  const r = Array.isArray(response) ? response[0] : response;
  if (!r) return '';
  if (r.choices && r.choices[0]) return r.choices[0].message?.content || r.choices[0].text || '';
  if (r.data && r.data.choices && r.data.choices[0]) return r.data.choices[0].message?.content || '';
  if (r.output && Array.isArray(r.output) && r.output[0]) {
    const f = r.output[0];
    if (f.content && Array.isArray(f.content) && f.content[0] && f.content[0].text) return f.content[0].text;
    if (f.message && f.message.content) return f.message.content;
    if (f.text) return f.text;
    if (typeof f === 'string') return f;
  }
  if (r.output) return typeof r.output === 'string' ? r.output : JSON.stringify(r.output);
  return r.content || r.response || r.text || (typeof r === 'string' ? r : JSON.stringify(r));
}

function masterCleanAndParseJSON(raw) {
  if (!raw) return null;
  let cleaned = typeof raw === 'string' ? raw.trim() : JSON.stringify(raw);
  const firstCurly = cleaned.indexOf('{');
  const firstSquare = cleaned.indexOf('[');
  let firstIndex = -1;
  if (firstCurly !== -1 && firstSquare !== -1) firstIndex = Math.min(firstCurly, firstSquare);
  else if (firstCurly !== -1) firstIndex = firstCurly;
  else if (firstSquare !== -1) firstIndex = firstSquare;
  const lastCurly = cleaned.lastIndexOf('}');
  const lastSquare = cleaned.lastIndexOf(']');
  const lastIndex = Math.max(lastCurly, lastSquare);
  if (firstIndex !== -1 && lastIndex !== -1 && lastIndex > firstIndex) cleaned = cleaned.substring(firstIndex, lastIndex + 1);
  try { return JSON.parse(cleaned); } catch (e1) {}
  let repaired = cleaned.replace(/,\s*([\}\]])/g, '$1').replace(/[\u0000-\u001F\u007F-\u009F]/g, '');
  let inString = false, escape = false, sanitized = '';
  for (let i = 0; i < repaired.length; i++) {
    let ch = repaired[i];
    if (escape) { sanitized += ch; escape = false; continue; }
    if (ch === '\\') { sanitized += ch; escape = true; continue; }
    if (ch === '"') { inString = !inString; sanitized += ch; continue; }
    if (inString) {
      if (ch === '\n') { sanitized += '\\n'; continue; }
      if (ch === '\r') { sanitized += '\\r'; continue; }
    }
    sanitized += ch;
  }
  let stack = [], balanced = '';
  inString = false; escape = false;
  for (let i = 0; i < sanitized.length; i++) {
    let ch = sanitized[i];
    if (escape) { balanced += ch; escape = false; continue; }
    if (ch === '\\') { balanced += ch; escape = true; continue; }
    if (ch === '"') { inString = !inString; balanced += ch; continue; }
    if (!inString) {
      if (ch === '{' || ch === '[') stack.push(ch);
      else if (ch === '}') { if (stack.length > 0 && stack[stack.length-1] === '{') stack.pop(); }
      else if (ch === ']') { if (stack.length > 0 && stack[stack.length-1] === '[') stack.pop(); }
    }
    balanced += ch;
  }
  while (stack.length > 0) { let top = stack.pop(); if (top === '{') balanced += '}'; else if (top === '[') balanced += ']'; }
  balanced = balanced.replace(/,\s*([\}\]])/g, '$1');
  try { return JSON.parse(balanced); } catch (e2) {}
  throw new Error('Critic JSON Repair unable to parse');
}

const response = $input.first().json;
let previousStory = {};
try { previousStory = $('Parse AI JSON').first().json; } catch (e) {
  try { previousStory = $('Handle Backup LLM Success').first().json; } catch (e2) { previousStory = {}; }
}
let aiOutput = extractContent(response);
if (!aiOutput || aiOutput.trim() === '') {
  console.log('Critic returned empty — using primary story.');
  return { json: { ...previousStory, criticVerdict: 'fallback', criticError: 'Empty critic response' } };
}
let finalJson;
try { finalJson = masterCleanAndParseJSON(aiOutput); } catch(e) {
  console.log('Critic JSON parse failed — using primary story.');
  return { json: { ...previousStory, criticVerdict: 'fallback', criticError: e.message } };
}
if (Array.isArray(finalJson)) finalJson = { scenes: finalJson };
if (!finalJson.scenes || !Array.isArray(finalJson.scenes) || finalJson.scenes.length === 0) {
  console.log('Critic missing scenes — using primary story.');
  return { json: { ...previousStory, criticVerdict: 'fallback', criticError: 'Missing scenes' } };
}
// STRICT 4-KEY OUTPUT: NO imagePrompt, NO visualPrompt
finalJson.scenes = finalJson.scenes.map((scene, i) => {
  const sceneNum = scene.sceneNumber || scene.scene || (i + 1);
  const vidPrompt = (scene.videoPrompt || scene.video_prompt || '').trim();
  const voText = (scene.voiceoverText || scene.dialogue || scene.narration || '').trim();
  return { sceneNumber: sceneNum, voiceoverText: voText, videoPrompt: vidPrompt, duration: scene.duration || 15 };
});
console.log('[CRITIC] Story approved and elevated.');
return {
  json: {
    title: finalJson.title || previousStory.title || 'Islamic Story',
    corePlot: finalJson.corePlot || finalJson.core_plot || previousStory.corePlot || '',
    category: finalJson.category || previousStory.category || 'Education',
    youtubeDescription: finalJson.youtubeDescription || finalJson.youtube_description || previousStory.youtubeDescription || '',
    tags: Array.isArray(finalJson.tags) ? finalJson.tags : (previousStory.tags || []),
    mainCharacter: finalJson.mainCharacter || finalJson.main_character || previousStory.mainCharacter || '',
    scenes: finalJson.scenes,
    criticVerdict: 'approved'
  }
};

// Critic Retry Counter (Primary)
const staticData = $getWorkflowStaticData('global');

if (staticData.fruitCriticRetriesPrimary === undefined) {
  staticData.fruitCriticRetriesPrimary = 0;
}

staticData.fruitCriticRetriesPrimary += 1;

if (staticData.fruitCriticRetriesPrimary > 2) {
  console.log('[CRITIC RETRY] Max retries (2) exceeded. Forcing approval.');
  staticData.fruitCriticRetriesPrimary = 0;

  const original = staticData.fruitSavedScriptPrimary;
  if (original) {
    return {
      json: {
        title: original.title || "",
        corePlot: original.corePlot || "",
        youtubeDescription: original.youtubeDescription || "",
        tags: Array.isArray(original.tags) ? original.tags : [],
        scenes: original.scenes,
        criticVerdict: "approved",
        retryExceeded: true
      }
    };
  }
}

console.log('[CRITIC RETRY] Retry ' + staticData.fruitCriticRetriesPrimary + '/2 - Regenerating...');
return {
  json: {
    status: "retry_regeneration",
    retryExceeded: false
  }
};

// Config: Critic LLM Master (Backup)
let staticData = $getWorkflowStaticData('global');
const inputItem = $input.first();

let storyData = {};
if (inputItem && inputItem.json) {
  if (inputItem.json.retry) {
    storyData = staticData.fruitSavedScriptBackup || {};
  } else {
    storyData = inputItem.json;
    staticData.fruitSavedScriptBackup = storyData;
  }
} else {
  storyData = staticData.fruitSavedScriptBackup || {};
}

const activeKeys = ($('Config: Backup LLM Master').first().json.keys) || [];

return {
  json: {
    keys: activeKeys,
    story: storyData,
    retry: (inputItem && inputItem.json && inputItem.json.retry) || false
  }
};

// Rotate API key for the Story Quality Critic LLM (Backup)
let staticData = $getWorkflowStaticData('global');
const config = $('Config: Critic LLM Master (Backup)').first().json;
const keys = config.keys || [];

if (staticData.fruitCriticKeyIndexBackup === undefined) {
  staticData.fruitCriticKeyIndexBackup = 0;
}

const key = keys[staticData.fruitCriticKeyIndexBackup % keys.length];
staticData.fruitCriticKeyIndexBackup += 1;

if (!config.retry) {
  staticData.fruitCriticAttemptsBackup = 0;
}

return {
  json: {
    ...config.story,
    usedKey: key,
    __criticCall: true,
    retry: config.retry || false
  }
};

parameters.jsonBody:
={{ (() => {
  // ============================================================
  // STAGE 3 - QUALITY DIRECTOR  (Story Quality Critic LLM Primary)
  // The audit is computed HERE, in code, because an LLM cannot count.
  // The model repairs only the defects this node names by number.
  // Everything not named is returned byte for byte.
  // ============================================================
  const D = $json || {};
  let B = {};
  try { B = $('Parse Strategy Output').first().json || {}; } catch (e) { B = {}; }
  let T = {};
  try { T = $('Parse Topic Analyzer Output').first().json || {}; } catch (e) { T = {}; }

  const BT = String.fromCharCode(96);
  const S = function (v, d) {
    let s = (v === undefined || v === null) ? '' : String(v);
    s = s.split(BT).join("'").replace(/\$\{/g, '(');
    s = s.replace(/\s+/g, ' ').trim();
    return s ? s : (d || '');
  };
  const M = function (v, d) {
    let s = (v === undefined || v === null) ? '' : String(v);
    s = s.split(BT).join("'").replace(/\$\{/g, '(');
    s = s.replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
    return s ? s : (d || '');
  };
  const CS = function (v, d) {
    const a = Array.isArray(v) ? v : (v ? String(v).split(/\s*[|,]\s*/) : []);
    const o = a.map(function (x) { return S(x, ''); }).filter(Boolean);
    return o.length ? o.join(', ') : (d || 'None');
  };
  const N = function (v, d) { const n = Number(v); return (isFinite(n) && n > 0) ? n : d; };

  // ---------- what Stage 1 locked ----------
  const lang = S(B.language, S(T.language, 'Hinglish'));
  const style = S(B.visualStyle, S(T.visualStyle, 'Cinematic Realistic'));
  const styleSpec = S(B.visualStyleDescription, style);
  const identity = S(B.identityLock, S(B.mainCharacterHint, ''));
  const storyShape = S(B.storyShape, 'Unspecified');
  const centralQ = S(B.centralQuestion, 'not supplied');
  const theTurn = S(B.theTurn, 'not supplied');
  const payoff = S(B.payoffLine, 'not supplied');
  const viralHook = S(B.viralHook, 'not supplied');
  const emoCore = S(B.emotionalCore, 'SUSPENSE');
  const setting = S(B.setting, 'unspecified');
  const warnings = S(B.contentWarnings, 'None');
  const forbidList = CS(B.forbiddenElements, 'None');
  const anchors = CS(B.visualAnchors, 'none declared');
  const blockedTitles = S(B.blockedTitles, 'None');
  const wMin = N(B.voWordMin, 36);
  const wMax = N(B.voWordMax, 40);
  const voMin = N(B.voCharMin, 221);
  const voMax = N(B.voCharMax, 249);
  const wMid = Math.round((wMin + wMax) / 2);
  const voBias = S(B.voLengthBias, 'default');
  const voNote = S(B.voBudgetNote, '');

  const cl = (B.creatorLock && typeof B.creatorLock === 'object') ? B.creatorLock : {};
  const clOn = cl.hasDirectives === true;
  const clText = S(B.creatorDirectiveText, 'None');
  const clLen = S(cl.lengthDemand, 'None');
  const clTone = S(cl.toneDemand, 'None');

  // ---------- the screenplay under audit ----------
  const title = S(D.title, '');
  const corePlot = S(D.corePlot, '');
  const category = S(D.category, '');
  const mainChar = S(D.mainCharacter, '');
  const desc = M(D.youtubeDescription, '');
  const tagsArr = (Array.isArray(D.tags) ? D.tags : String(D.tags || '').split(/\s*,\s*/))
    .map(function (x) { return S(x, ''); }).filter(Boolean);
  const scenesIn = Array.isArray(D.scenes) ? D.scenes : [];

  // ---------- detectors ----------
  const DEVA = new RegExp('[' + String.fromCharCode(2304) + '-' + String.fromCharCode(2431) + ']');
  const LATINW = /[A-Za-z]{3,}/;
  const SHOUT = /\b[A-Z]{5,}\b/;
  const words = function (s) {
    const a = String(s || '').trim().split(/\s+/);
    return (a.length === 1 && a[0] === '') ? [] : a;
  };
  const wc = function (s) { return words(s).length; };
  const emoji = function (s) {
    const t = String(s || '');
    for (let i = 0; i < t.length; i++) {
      const c = t.charCodeAt(i);
      if (c >= 0xD800 && c <= 0xDBFF) return true;
      if (c === 0xFE0F || c === 0x20E3) return true;
      if (c >= 0x2190 && c <= 0x21FF) return true;
      if (c >= 0x2600 && c <= 0x27BF) return true;
      if (c >= 0x2B00 && c <= 0x2BFF) return true;
    }
    return false;
  };
  const devaRatio = function (s) {
    const a = words(s);
    if (!a.length) return 0;
    let d = 0;
    for (let i = 0; i < a.length; i++) { if (DEVA.test(a[i])) d++; }
    return d / a.length;
  };
  const BANNED_EDIT = ['cut to', 'then we see', 'montage', 'sequence of shots', 'split screen',
    'transition to', 'fade to', 'meanwhile', 'title card', 'caption', 'subtitle', 'voiceover',
    'narrator', 'text appears', 'jump cut', 'quick cuts'];
  const PADDING = ['dark shadows', 'cold wind', 'cold breeze', 'eerie silence', 'unsettling feeling',
    'something felt wrong', 'nobody could believe', 'atmosphere was heavy', 'mysterious aura',
    'destiny had other plans', 'tension rose', 'silence fell', 'everything changed forever',
    'little did they know', 'what happened next will'];
  const CATS = ['Education', 'Entertainment', 'News', 'Science', 'History', 'Mythology', 'Crime',
    'Sports', 'Technology', 'Nature', 'Business', 'Motivation', 'Culture'];
  const BAD_TITLE_OPEN = ['the shocking truth', 'you will not believe', 'you wont believe',
    'top 5', 'top 10', 'this is why', 'shocking truth'];
  const BAD_OPENER = ['namaste', 'hello friends', 'hi friends', 'dosto', 'imagine ', 'kya aap',
    'welcome to', 'aaj hum'];
  const HARD_CTA = ['subscribe', 'like kar', 'share kar', 'comment kar', 'like and share',
    'hit the bell', 'follow for more'];
  const hit = function (hay, list) {
    const h = String(hay || '').toLowerCase();
    const found = [];
    for (let i = 0; i < list.length; i++) { if (h.indexOf(list[i]) !== -1) found.push(list[i]); }
    return found;
  };
  // the mandatory technical clause legitimately says "no split screen", "no subtitles", "no cuts".
  // strip every negated form before scanning for editing language, or the clause flags itself.
  const scrubNeg = function (v) {
    return String(v || '').toLowerCase().replace(
      /\bno\s+(on-screen\s+text|letters|numbers|logos|watermarks?|subtitles?|captions?|split[\s-]screens?|cuts?|text|montage|transitions?|voiceover|narrator|title\s+cards?)\b/g, ' ');
  };

  // ---------- run the audit ----------
  const defects = [];
  const flag = function (t) { defects.push(String(defects.length + 1) + '. ' + t); };

  if (scenesIn.length !== 5) {
    flag('SCENE COUNT: the screenplay has ' + scenesIn.length + ' scenes. It must have exactly 5. ' +
      'Write the missing scenes from the scene assignments listed above.');
  }
  if (!title) flag('TITLE: missing. Write one.');
  else {
    if (title.length < 45 || title.length > 80) {
      flag('TITLE LENGTH: it is ' + title.length + ' characters, the range is 45 to 80. Rewrite it to fit ' +
        'without losing the curiosity gap.');
    }
    const bt = hit(title, BAD_TITLE_OPEN);
    if (bt.length) flag('TITLE OPENING: it uses the banned formula "' + bt[0] + '". Replace the opening.');
    if (blockedTitles !== 'None' && blockedTitles.toLowerCase().indexOf(title.toLowerCase()) !== -1) {
      flag('TITLE DUPLICATE: this exact title is already published on the channel. Write a different one ' +
        'for the same story.');
    }
  }
  if (!corePlot) flag('COREPLOT: missing. Write one sentence naming the real events.');
  else if (corePlot.length < 50 || corePlot.length > 110) {
    flag('COREPLOT LENGTH: it is ' + corePlot.length + ' characters, the range is 50 to 110. It must name ' +
      'the actual events, not the mood.');
  }
  if (!mainChar) {
    flag('MAINCHARACTER: missing. Return the subject name only, 2 to 6 words. Stage 1 called it: ' +
      (identity || 'see the cast block above') + '. Give the name, not the description.');
  } else {
    if (wc(mainChar) > 6 || mainChar.indexOf(',') !== -1) {
      flag('MAINCHARACTER: "' + mainChar + '" is a description, not a name. Return the short designation ' +
        'only, 2 to 6 words, no commas, no physical detail. It is stored as channel memory.');
    }
  }
  if (CATS.indexOf(category) === -1) {
    flag('CATEGORY: "' + (category || 'empty') + '" is not allowed. Pick exactly one word from: ' +
      CATS.join(', '));
  }
  if (!desc) flag('DESCRIPTION: missing. Write it in the four-part order.');
  else {
    if (desc.length < 700 || desc.length > 1100) {
      flag('DESCRIPTION LENGTH: it is ' + desc.length + ' characters, the range is 700 to 1100. ' +
        (desc.length < 700 ? 'Add real story specifics, not filler.' : 'Cut the weakest paragraph.'));
    }
    if (desc.indexOf('#') === -1) flag('DESCRIPTION: it has no hashtag line. Add 8 to 12 hashtags on the last line.');
    if (hit(desc, ['disclaimer', 'copyright disclaimer', 'fair use']).length) {
      flag('DESCRIPTION: it contains a disclaimer paragraph. Remove it, the workflow appends legal text itself.');
    }
  }
  if (tagsArr.length < 8 || tagsArr.length > 12) {
    flag('TAGS COUNT: there are ' + tagsArr.length + ', the range is 8 to 12.');
  }
  const dirtyTags = tagsArr.filter(function (t) { return /[#]/.test(t) || /\s/.test(t) || /[A-Z]/.test(t); });
  if (dirtyTags.length) {
    flag('TAGS FORMAT: these are wrong - ' + dirtyTags.join(', ') +
      '. Every tag is lowercase, no hash symbol, no spaces inside a tag.');
  }

  // ---------- per scene ----------
  const sb = Array.isArray(B.sceneBreakdown) ? B.sceneBreakdown : [];
  const ACTS = ['HOOK', 'SETUP', 'BUILD', 'CLIMAX', 'RESOLUTION'];
  const ROWS = [];
  const PLAN = [];
  for (let i = 0; i < 5; i++) {
    const sc = (scenesIn[i] && typeof scenesIn[i] === 'object') ? scenesIn[i] : {};
    const bp = (sb[i] && typeof sb[i] === 'object') ? sb[i] : {};
    const n = i + 1;
    const vo = S(sc.voiceoverText, '');
    const vp = S(sc.videoPrompt, '');
    const voW = wc(vo);
    const vpW = wc(vp);
    const dur = Number(sc.duration);

    ROWS.push('SCENE ' + n + '\n' +
      '  voiceoverText  [' + voW + ' words, ' + vo.length + ' chars]: ' + (vo || 'MISSING') + '\n' +
      '  videoPrompt    [' + vpW + ' words]: ' + (vp || 'MISSING'));
    PLAN.push('SCENE ' + n + ' - act ' + S(bp.act, ACTS[i]) +
      ' - job: ' + S(bp.beatFunction, S(bp.purpose, ACTS[i] + ' beat')) +
      '\n    fact it owes  : ' + S(bp.factSpent, 'none assigned') +
      '\n    camera assigned: ' + S(bp.cameraPlan, 'one continuous move, any') +
      '\n    must change   : ' + S(bp.stateChange, 'something in frame must change') +
      '\n    light change  : ' + S(bp.lightChange, 'light must differ at 0s and 15s'));

    if (dur !== 15) flag('SCENE ' + n + ' DURATION: it is ' + (isFinite(dur) ? dur : 'missing') + '. It must be 15.');

    if (!vo) {
      flag('SCENE ' + n + ' NARRATION: missing. Write it, ' + wMin + ' to ' + wMax + ' words, delivering the fact above.');
    } else {
      if (voW < wMin) {
        flag('SCENE ' + n + ' NARRATION TOO SHORT: ' + voW + ' words, needs ' + wMin + ' to ' + wMax +
          '. Add ' + (wMin - voW) + ' more words of FACT. Do not add adjectives, do not add atmosphere.');
      } else if (voW > wMax) {
        flag('SCENE ' + n + ' NARRATION TOO LONG: ' + voW + ' words, needs ' + wMin + ' to ' + wMax +
          '. Remove ' + (voW - wMax) + ' words by deleting a setup clause. Keep every fact.');
      }
      if (lang === 'Hindi' && LATINW.test(vo)) {
        flag('SCENE ' + n + ' SCRIPT: the narration contains Roman letters and this is a Hindi run. ' +
          'Convert every word to Devanagari. The voice engine mispronounces Roman text.');
      }
      if (lang === 'English' && DEVA.test(vo)) {
        flag('SCENE ' + n + ' SCRIPT: the narration contains Devanagari and this is an English run. ' +
          'Rewrite it in English only.');
      }
      if (lang !== 'Hindi' && lang !== 'English') {
        const r = devaRatio(vo);
        if (r === 0) {
          flag('SCENE ' + n + ' SCRIPT: the narration has zero Devanagari on a Hinglish run. ' +
            'Rewrite so Hindi words are in Devanagari and only English words stay in Latin.');
        } else if (r < 0.5) {
          flag('SCENE ' + n + ' SCRIPT: only ' + Math.round(r * 100) + ' percent of the words are Devanagari. ' +
            'Hinglish needs roughly 65 to 75 percent. Any Hindi word still written in Roman letters must be ' +
            'converted to Devanagari.');
        }
      }
      if (emoji(vo)) flag('SCENE ' + n + ' NARRATION: contains an emoji. Delete it, the voice reads it aloud.');
      if (SHOUT.test(vo)) flag('SCENE ' + n + ' NARRATION: contains a shouted ALL-CAPS word. Write it normally, ' +
        'the voice engine spells capitals letter by letter.');
      if (vo.indexOf('"') !== -1) flag('SCENE ' + n + ' NARRATION: contains a double quote. Remove it.');
      if (/[()\[\]]/.test(vo)) flag('SCENE ' + n + ' NARRATION: contains brackets or a stage direction. ' +
        'Narration is spoken words only.');
      const dots = (vo.match(/\.\.\.|…/g) || []).length;
      if (dots > 1) flag('SCENE ' + n + ' NARRATION: has ' + dots + ' ellipses. One per scene at most.');
      const pad = hit(vo, PADDING);
      if (pad.length) flag('SCENE ' + n + ' PADDING: it contains "' + pad[0] + '". That is filler. ' +
        'Delete the phrase and replace it with a fact from the ammunition list.');
      if (n === 1) {
        const bo = hit(vo, BAD_OPENER);
        if (bo.length) flag('SCENE 1 OPENING: it opens with "' + bo[0] + '". Cut the throat clearing and open ' +
          'on the hardest fact or on the assigned opening line.');
      }
      if (n === 5) {
        const cta = hit(vo, HARD_CTA);
        if (cta.length) flag('SCENE 5 ENDING: it contains a hard call to action, "' + cta[0] +
          '". Replace it with one soft curiosity line.');
      }
    }
    if (!vp) {
      flag('SCENE ' + n + ' VIDEOPROMPT: missing. Write it in English, 95 to 140 words, in the seven-part order.');
    } else {
      if (vpW < 95) flag('SCENE ' + n + ' VIDEOPROMPT TOO SHORT: ' + vpW + ' words, needs 95 to 140. ' +
        'The missing part is almost always the ACTION across the 15 seconds or the light change.');
      else if (vpW > 140) flag('SCENE ' + n + ' VIDEOPROMPT TOO LONG: ' + vpW + ' words, needs 95 to 140. ' +
        'Cut adjectives about mood, never the identity lock and never the technical clause.');
      if (DEVA.test(vp)) flag('SCENE ' + n + ' VIDEOPROMPT: contains Devanagari. The video model reads English ' +
        'only. Translate those words into a physical English description.');
      if (identity && vp.toLowerCase().indexOf(identity.toLowerCase().slice(0, 40)) === -1) {
        flag('SCENE ' + n + ' IDENTITY LOCK MISSING: the prompt does not open with the locked subject line. ' +
          'Put this exact string first, word for word, and add no new physical detail: ' + identity);
      }
      if (vp.toLowerCase().indexOf((style + ' aesthetic').toLowerCase()) === -1) {
        flag('SCENE ' + n + ' STYLE MISSING: the prompt never says "' + style + ' aesthetic". Add it in part 6, ' +
          'followed by: ' + styleSpec);
      }
      if (vp.toLowerCase().indexOf('no on-screen text') === -1) {
        flag('SCENE ' + n + ' TECHNICAL CLAUSE MISSING: the prompt must end with 9:16 vertical, single continuous ' +
          'take, no on-screen text, no letters, no numbers, no logos, no watermark, no subtitles, no split screen, no cuts.');
      }
      const be = hit(scrubNeg(vp), BANNED_EDIT);
      if (be.length) flag('SCENE ' + n + ' VIDEOPROMPT: it contains editing language, "' + be[0] +
        '". There is no editor. Rewrite it as one continuous camera move.');
      if (!/camera/i.test(vp)) {
        flag('SCENE ' + n + ' NO CAMERA INSTRUCTION: part 4 is missing entirely, so the clip renders as a still ' +
          'image with noise on it. Add the assigned move: ' + S(bp.cameraPlan, 'one continuous move'));
      } else {
        const parts = vp.split('. ');
        let camSent = '';
        for (let k = 0; k < parts.length; k++) { if (/camera/i.test(parts[k])) camSent += parts[k] + ' '; }
        if (!/push|pull|dolly|truck|crane|orbit|arc|pan|tilt|zoom|handheld|locked|track|glide|drift|rise|descend|follow|circle|rotate|sweep|travel|move|close|wide/i.test(camSent)) {
          flag('SCENE ' + n + ' CAMERA DOES NOT MOVE: the camera is named but given no move. Replace that clause ' +
            'with the assigned move: ' + S(bp.cameraPlan, 'one continuous move'));
        }
      }
      if (!/light|lit|lamp|bulb|sun|shadow|glow|beam|dark|backlit|flare|silhouette/i.test(vp)) {
        flag('SCENE ' + n + ' NO LIGHT DESCRIBED: add the assigned change stated as start then end - ' +
          S(bp.lightChange, 'light must differ at 0s and 15s'));
      } else if (!/starts?\b|begins?\b|ends?\b|then\b|shifts?\b|switch|fall|by 15s|at 0s|until/i.test(vp)) {
        flag('SCENE ' + n + ' LIGHT NEVER CHANGES: the light is described once and holds for 15 seconds, which ' +
          'reads as a photograph. State it as start condition then end condition - ' +
          S(bp.lightChange, 'light must differ at 0s and 15s'));
      }
    }
  }
  const SCENE_TABLE = ROWS.join('\n\n');
  const PLAN_TABLE = PLAN.join('\n\n');
  const AUDIT = defects.length
    ? defects.join('\n')
    : 'AUDIT CLEAN. Every mechanical law already passes. Do not rewrite anything for its own sake.';
  const defectCount = defects.length;
  // ---------- script policy: exactly one block is injected ----------
  let scriptLaw = '';
  if (lang === 'Hindi') {
    scriptLaw = 'HINDI. PURE DEVANAGARI, 100 percent, in every voiceoverText and in the title, corePlot and ' +
      'description. Not one Roman letter. Roman-script Hindi is FORBIDDEN - "Us raat teen baje" is a defect, ' +
      'not a style choice, because the voice engine reads Roman letters as English phonemes. Proper nouns and ' +
      'modern terms are transliterated INTO Devanagari. Spoken Hindi, not textbook Hindi.';
  } else if (lang === 'English') {
    scriptLaw = 'ENGLISH. Latin script only, no Devanagari anywhere, no Hindi words as flavour. ' +
      'Spoken English, not written English. Contractions are good. Short sentences.';
  } else {
    scriptLaw = 'HINGLISH. Mixed script and the mix is a hard rule: Hindi words in DEVANAGARI, English words in ' +
      'LATIN, inside the same sentence, roughly 65 to 75 percent Devanagari by word count. Roman-script Hindi is ' +
      'FORBIDDEN - "raat ko teen baje" is a defect, "रात को तीन बजे" is correct. English only where an Indian ' +
      'speaker really switches: technical nouns, brand names, numbers with units, borrowed slang.';
  }

  const creatorBlock = clOn
    ? ('THE CREATOR GAVE EXPLICIT INSTRUCTIONS AND THEY OUTRANK YOUR TASTE.\n' +
       'Their exact words: ' + clText + '\n' +
       '  length demand : ' + clLen + '\n' +
       '  tone demand   : ' + clTone + '\n' +
       'Their length demand is already baked into the word range below. Honour the range.')
    : 'No creator directives on this run.';

  const verdictLine = defectCount === 0
    ? 'The audit found ZERO mechanical defects. Your job on this run is the discretionary pass only, ' +
      'and it must be surgical. Change a line only if it clearly breaks a law the code cannot see.'
    : 'The audit found ' + defectCount + ' defect(s). Fix exactly those, then run the discretionary pass. ' +
      'Anything the audit did not name stays byte for byte identical.';
  return JSON.stringify({
    model: 'google/gemini-2.5-flash',
    temperature: 0.3,
    max_tokens: 16000,
    response_format: { type: 'json_object' },
    messages: [
      {
        role: 'system',
        content: `You are the QUALITY DIRECTOR of a short-form film unit. You are Stage 3 of 4, the last
human-level judgement before this screenplay is turned into audio and video that cannot be edited again.

You are NOT a reviewer who leaves notes. You return the finished, corrected screenplay.
You are also NOT a rewriter. A machine has already audited this screenplay for every law it can measure
and listed the defects by number. You repair those, you apply one narrow judgement pass, and you leave
everything else exactly as it was written.

THE FIRST LAW IS DO NO HARM.
The previous stage wrote this. It is mostly good. Every line you touch without a reason listed below makes
the film worse and flattens a voice that a real person chose. If a line is not named in the audit and does
not break one of the four judgement rules, copy it out character for character.

${verdictLine}

===============================================================
WHAT STAGE 1 LOCKED - YOU MAY NOT CHANGE ANY OF IT
===============================================================
Language and script : ${lang}
Story shape         : ${storyShape}
Central question    : ${centralQ}
The turn            : ${theTurn}
Payoff line         : ${payoff}
Opening line        : ${viralHook}
Emotional core      : ${emoCore}
Setting             : ${setting}
Visual style        : ${style}
Style specification : ${styleSpec}
IDENTITY LOCK       : ${identity || 'not supplied - keep whatever subject line Stage 2 used, identically, in all 5 prompts'}
Recurring anchors   : ${anchors}
Must not appear     : ${forbidList}
Content warnings    : ${warnings}

${creatorBlock}

===============================================================
THE SCENE ASSIGNMENTS STAGE 1 ISSUED
===============================================================
Use these only to judge whether a scene did its job. Do not re-plan the film.

${PLAN_TABLE}

===============================================================
THE LAWS THE AUDIT ALREADY MEASURED
===============================================================
NARRATION LENGTH: ${wMin} to ${wMax} words per scene, which lands near ${voMin} to ${voMax} characters.
Aim for ${wMid}. Length bias for this run: ${voBias}. ${voNote}
Do not count characters, you cannot do it reliably. Count words.
When a scene is short the fix is ANOTHER FACT. Never an adjective, never atmosphere, never a feeling.
Padding is a defect, not a solution. These are banned outright: dark shadows, cold wind, eerie silence,
an unsettling feeling, something felt wrong, nobody could believe it, the atmosphere was heavy,
a mysterious aura, destiny had other plans, little did they know.
When a scene is long, delete a setup clause and keep every fact.

SCRIPT: ${scriptLaw}
Plus, all languages: no emojis, no shouted ALL-CAPS, no brackets or stage directions, no double quotes,
at most one ellipsis per scene, write percent not the symbol. Every sentence sayable in one breath.

VIDEOPROMPT: English only, 95 to 140 words, seven parts in this fixed order, separated by periods -
subject as the identity lock copied word for word, action across the 15 seconds, environment with an
anchor and a texture, one continuous camera move, light stated as start then end, the words
${style} aesthetic followed by the specification, then 9:16 vertical, single continuous take,
no on-screen text, no letters, no numbers, no logos, no watermark, no subtitles, no split screen, no cuts.
There is no editor after this. Words like cut, cut to, montage, transition and meanwhile are defects.
The identity lock is copied, never rewritten, and no new physical detail about the subject is added
anywhere - that is what makes the subject look like a different person in clip 3.
===============================================================
THE FOUR JUDGEMENT RULES - THE ONLY THINGS THE AUDIT CANNOT SEE
===============================================================
These are the only reasons you may change a line the audit did not name.

J1. NARRATION THAT DESCRIBES THE PICTURE.
    If the voice says what the eye is already seeing, 15 seconds of the video are wasted twice.
    The picture shows the storm. The narration says who was out in it and why.
    Fix: replace the described image with the fact behind it. Same word count.

J2. A SENTENCE THAT SURVIVES DELETION.
    Read each scene and delete any sentence. If nothing is lost, it was decoration.
    Fix: delete it and spend the words on a fact this scene owes.

J3. A SCENE THAT DOES NOT ADVANCE.
    After every scene the viewer must know something they did not know one scene earlier, and the scenes
    must connect by because, therefore or but - never by AND THEN.
    Fix: give the scene back the fact it owes from the assignment list. Do not reorder the film.

J4. A DEAD CLIP.
    If a videoPrompt would render a subject standing still under unchanging light, it produces a
    photograph with noise on it. The three moments inside the 15 seconds must be three different
    framings or three different actions, not one image described three times.
    Fix: restore the assigned state change and the assigned light change inside the existing prompt.

You may not change: the story, the order of scenes, the turn, the payoff, the identity lock, the visual
style, the language, or anything the creator asked for. You may not add a new character. You may not
invent a fact that is not in the screenplay or the assignments.

===============================================================
SAFETY - APPLIES WHILE STILL TELLING THE TRUTH
===============================================================
No graphic injury, blood, gore, a body, a method of self-harm, or explicit death. No sexual content.
No dangerous act in reproducible detail. Replace the graphic moment with the moment before or after:
the empty chair, the closed door, the object left behind, the aftermath in a wide frame.
For real people, stay factual and attribute contested claims - according to the inquiry, witnesses said,
the record shows. No unverified accusation about a living person.
Restraint is not softening. Specific facts stated plainly hit harder than adjectives.
${warnings === 'None' ? '' : 'This topic carries a warning: ' + warnings + '. Handle it with restraint and no graphic image.'}

===============================================================
THE MACHINE AUDIT - FIX EVERY NUMBERED ITEM
===============================================================
${AUDIT}

===============================================================
OUTPUT - RETURN ONLY THIS JSON OBJECT, NO PROSE, NO CODE FENCE
===============================================================
Write the fixesApplied list FIRST, before the screenplay, naming each audit number you repaired and each
judgement rule you applied. If you repaired nothing, return an empty array. Then write the screenplay.

{
  "fixesApplied": ["audit 3 - scene 2 narration was 6 words long, cut a setup clause", "J1 - scene 4 described the picture"],
  "title": "45 to 80 characters in ${lang}",
  "corePlot": "one sentence, 50 to 110 characters, in ${lang}, names the real events",
  "mainCharacter": "short name or designation only, 2 to 6 words, no description",
  "category": "one word from the allowed list",
  "youtubeDescription": "700 to 1100 characters in ${lang}, opener, story, question, hashtag line",
  "tags": ["tag1", "tag2", "tag3", "tag4", "tag5", "tag6", "tag7", "tag8"],
  "scenes": [
    { "sceneNumber": 1, "voiceoverText": "${wMin} to ${wMax} words in ${lang}", "videoPrompt": "95 to 140 words in ENGLISH", "duration": 15 },
    { "sceneNumber": 2, "voiceoverText": "${wMin} to ${wMax} words in ${lang}", "videoPrompt": "95 to 140 words in ENGLISH", "duration": 15 },
    { "sceneNumber": 3, "voiceoverText": "${wMin} to ${wMax} words in ${lang}", "videoPrompt": "95 to 140 words in ENGLISH", "duration": 15 },
    { "sceneNumber": 4, "voiceoverText": "${wMin} to ${wMax} words in ${lang}", "videoPrompt": "95 to 140 words in ENGLISH", "duration": 15 },
    { "sceneNumber": 5, "voiceoverText": "${wMin} to ${wMax} words in ${lang}", "videoPrompt": "95 to 140 words in ENGLISH", "duration": 15 }
  ]
}

All 5 scenes are always present, even the ones you did not touch - copy those out unchanged.
duration is always 15. Never return a verdict, a score, a rejection or a note field.
Never return an empty scenes array. If you cannot fix something, return the original line rather than
nothing, because an empty field ships a broken video.

Return the JSON object only.`
      },
      {
        role: 'user',
        content: `Here is the screenplay Stage 2 submitted. The word and character counts in brackets were
measured by the workflow, they are exact, trust them over your own counting.

TITLE [${title.length} chars]: ${title || 'MISSING'}
COREPLOT [${corePlot.length} chars]: ${corePlot || 'MISSING'}
MAINCHARACTER: ${mainChar || 'MISSING'}
CATEGORY: ${category || 'MISSING'}
TAGS [${tagsArr.length}]: ${tagsArr.length ? tagsArr.join(', ') : 'MISSING'}
DESCRIPTION [${desc.length} chars]:
${desc || 'MISSING'}

${SCENE_TABLE}

Repair the ${defectCount} audited defect(s), apply the four judgement rules, leave everything else
identical, and return the complete corrected screenplay as the JSON object only.`
      }
    ]
  });
})() }}

