={{ (() => {
  // ============================================================
  // STAGE 1 - SHOWRUNNER  (Strategy Engine LLM Brain)
  // Turns the Stage 0 spine into a shootable 5-scene blueprint.
  // ============================================================
  let T = $json || {};
  if (!T.specificTopic && !T.rawUserInput) {
    try { T = $('Parse Topic Analyzer Output').first().json || {}; } catch (e) { T = {}; }
  }

  const BT = String.fromCharCode(96);
  const S = function (v, d) {
    let s = (v === undefined || v === null) ? '' : String(v);
    s = s.split(BT).join("'").replace(/\$\{/g, '(');
    s = s.replace(/\s+/g, ' ').trim();
    return s ? s : (d || '');
  };
  const RAW = function (v, d) {
    let s = (v === undefined || v === null) ? '' : String(v);
    s = s.split(BT).join("'").replace(/\$\{/g, '(').trim();
    return s ? s : (d || '');
  };
  const L = function (v, d) {
    const a = Array.isArray(v) ? v : (v ? String(v).split(/\s*\|\s*/) : []);
    const o = a.map(function (x) { return S(x, ''); }).filter(Boolean);
    return o.length ? o.map(function (x, i) { return '  ' + (i + 1) + '. ' + x; }).join('\n') : (d || '  None');
  };
  const N = function (v, d) { const n = Number(v); return (isFinite(n) && n > 0) ? n : d; };

  // ---------- inbound spine from Stage 0 ----------
  const rawInput = RAW(T.rawUserInput, 'Not provided');
  const specificTopic = RAW(T.specificTopic, rawInput);
  const stage0Brief = RAW(T.storyBrief, '');
  const contentFamily = S(T.contentFamily, 'F12 Curiosity Facts And Lists');
  const contentType = S(T.contentType, 'Curiosity Facts And Lists');
  const genre = S(T.genre, contentType);
  const formatArchetype = S(T.formatArchetype, 'single-narrative');
  const visualStyle = S(T.visualStyle, 'Cinematic Realistic');
  const lang = S(T.language, 'Hinglish');
  const toneStyle = S(T.toneStyle, 'Fast, intense, human');
  const audience = S(T.targetAudience, 'Youth 15-35');
  const timeFrame = S(T.timeFrame, 'Unspecified');
  const centralQ = RAW(T.centralQuestion, '');
  const theTurn = RAW(T.theTurn, '');
  const payoff = RAW(T.payoffLine, '');
  const hookSeed = RAW(T.suggestedHook, '');
  const hookType = S(T.hookType, 'mid-crisis');
  const rejected = RAW(T.rejectedObviousAngle, 'None');
  const retention = S(T.retentionDriver, '');
  const weakAxis = S(T.weakestAxis, '');
  const entities = L(T.namedEntities, '  None named - you may cast freely');
  const facts = L(T.factsAvailable, '  NONE SUPPLIED - you must supply 6 yourself');
  const anchors = L(T.visualAnchors, '  NONE SUPPLIED - you must invent 4');
  const required = L(T.requiredElements, '  None');
  const forbidden = L(T.forbiddenElements, '  None');
  const warnings = S(T.contentWarnings, 'None');

  // ---------- creator lock ----------
  const cl = (T.creatorLock && typeof T.creatorLock === 'object') ? T.creatorLock : {};
  const clOn = cl.hasDirectives === true;
  const clText = RAW(T.creatorDirectiveText, 'None');
  const clStyle = S(cl.styleDemand, 'None');
  const clLang = S(cl.languageDemand, 'None');
  const clTone = S(cl.toneDemand, 'None');
  const clLen = S(cl.lengthDemand, 'None');
  const clStruct = S(cl.structureDemand, 'None');

  // ---------- voiceover budget (computed upstream, never re-derived here) ----------
  const voTarget = N(T.voCharTarget, 235);
  const voMin = N(T.voCharMin, 221);
  const voMax = N(T.voCharMax, 249);
  const wMin = N(T.voWordMin, 36);
  const wMax = N(T.voWordMax, 40);
  const voNote = S(T.voBudgetNote, '');
  const voBias = S(T.voLengthBias, 'default');

  // ---------- anti-repetition memory ----------
  const blockedTitles = S($json.blockedTitles, 'None');
  const blockedPlots = S($json.blockedPlots, 'None');
  const recentChars = S($json.recentCharacters, 'None');

  // ---------- 8 STORY SHAPES (rotated by seed so nothing is templated) ----------
  const SHAPES = [
    { n: 'Cold Open Anomaly', fit: 'mysteries, phenomena, unexplained events', b: [
      'Land inside the strangest visible second of the event. No setup, no context, no narrator throat-clearing.',
      'Rewind to the ordinary moment that produced it and name the one detail everybody walked past.',
      'Stack the evidence that kills the easy explanation.',
      'THE TURN - the real mechanism becomes visible on screen.',
      'Close the question, leave one door open. Do not summarise what we just watched.' ] },
    { n: 'Reverse Reveal', fit: 'famous outcomes, biographies, endings everyone thinks they know', b: [
      'State the ending everybody already believes, as if it were settled fact.',
      'Show the first crack in that version.',
      'Break it with the second and third contradiction.',
      'THE TURN - the true first cause, the thing nobody looks at.',
      'Replay the famous ending with the new cause in place. Same facts, different meaning.' ] },
    { n: 'Two Timelines Collide', fit: 'history reaching the present, cause and consequence', b: [
      'THEN - the seed moment, shown small and unimportant.',
      'NOW - the consequence, shown large, with no explanation offered yet.',
      'Back to THEN - what was set in motion, and by whose hand.',
      'THE TURN - the timelines touch. The same object, place or gesture appears in both.',
      'The one sentence that binds the two. Nothing more.' ] },
    { n: 'Countdown Pressure', fit: 'disasters, deadlines, survival, records, rescues', b: [
      'Start the clock out loud, with the stake attached to it.',
      'First unit gone - the first thing that fails.',
      'Halfway - the plan changes and the cost turns real.',
      'THE TURN - final unit, the decisive act, maximum intensity.',
      'After zero - what the clock actually cost.' ] },
    { n: 'One Object History', fit: 'artifacts, inventions, products, weapons, relics, documents', b: [
      'The object alone, extreme close, unremarkable until it is named.',
      'The hands that made it, and why they needed it to exist.',
      'The hands that used it for something else.',
      'THE TURN - the moment the object outlived its purpose.',
      'Where it sits today, and who is still paying for it.' ] },
    { n: 'Decision Fork', fit: 'biographies, business, sport, moral dilemmas', b: [
      'The person at the exact second of choosing, mid-breath.',
      'What both roads promised. Make both look correct.',
      'The road taken, and the first bill it presented.',
      'THE TURN - the cost that was invisible at the fork.',
      'The verdict. State it, do not preach it.' ] },
    { n: 'Evidence Stack', fit: 'true crime, science, investigations, contested claims', b: [
      'One physical trace, shown before it is explained.',
      'The theory it appears to prove.',
      'Two more traces that fit that theory a little too neatly.',
      'THE TURN - the trace that cannot fit. The theory breaks on screen.',
      'Name the explanation that survives, and the part of it still unproven.' ] },
    { n: 'Scale Ladder', fit: 'space, nature, biology, economics, anything about size', b: [
      'Start impossibly close on one detail that fills the whole frame.',
      'Pull out one step - the detail turns out to be part of something else.',
      'Pull out again - the pattern repeats at a size that should not be possible.',
      'THE TURN - the widest frame, which changes what shot one meant.',
      'Return to the opening detail. It cannot be looked at the same way now.' ] }
  ];

  // ---------- camera moves: each is ONE continuous move that works like an edit ----------
  const MOVES = [
    'slow push-in that travels THROUGH a foreground occluder (rain sheet, doorway, hanging cloth, crowd) so the subject only appears past the halfway mark',
    'crane down from a high wide to eye level, ending locked on the subject hands',
    'whip-pan launched off a moving object, settling hard on the reveal',
    'unbroken dolly-out from a macro detail to the full environment, the scale landing on the last beat',
    '180-degree orbit around a motionless subject so the background is completely different by the end',
    'rack focus from a sharp foreground object to the subject behind it, then a short push-in',
    'top-down descent that straightens into a level eye-line as it lands',
    'handheld follow from behind the shoulder, taking one corner into the reveal',
    'locked-off frame while the subject travels from far to near until it fills the lens',
    'tilt up from marks on the ground (tracks, debris, spilled contents) to whatever made them',
    'slow lateral truck past three foreground layers that each hide and then expose the subject',
    'push-in ending on an extreme close of one eye, one hand or one dial'
  ];

  const TITLE_SHAPES = [
    'the withheld noun - name the effect, hide the cause',
    'the number that has no business being that number',
    'the two-word contradiction',
    'the timestamp - a specific hour, day or year that reframes the whole topic',
    'direct address - a claim aimed at the viewer in second person',
    'the quote fragment - a short line somebody actually said'
  ];

  // ---------- 16 visual style specs, only the assigned one is injected ----------
  const SPECS = {
    'Pixar 3D Animated': 'stylized 3D animation, expressive cartoon faces with readable micro-emotion, soft glossy skin, saturated high-contrast palette, three-point studio lighting with rim light, appealing exaggerated proportions, depth-rich sets, crisp surface texture',
    'Anime Cinematic': 'cel-shaded 2D anime, hand-painted background plates, hard-edged shadow shapes, selective bloom and speed lines, dramatic single key light, sakuga-grade motion, film color grade',
    'Cinematic Dark Dramatic': 'low-key single-source lighting, deep crushed shadows, teal and amber grade, practical fog, subtle handheld micro-shake, extreme contrast ratio, photoreal thriller grain',
    'Realistic Documentary': 'observational photojournalism, motivated available light, organic handheld drift, real unstaged locations, fine film grain, restrained neutral grade, zero stylization',
    'Cinematic Sci-Fi Documentary': 'IMAX space-documentary scale, volumetric god rays through drifting dust, layered nebula depth, believable near-future hardware, cyan-orange grade, vast negative space',
    'Cinematic Realistic CGI': 'photoreal CGI at mythic scale, low hero angles, golden-hour warm grade, volumetric particulate, hyper-detailed materials, film motion blur',
    'Cinematic Realistic': 'large-sensor cinema look, shallow depth of field with creamy bokeh, motivated practical light, unified feature-film grade, smooth dolly movement, 4K photoreal detail',
    'Archival Newsreel': '16mm archival stock, heavy grain, gate weave, dust and emulsion scratches, slightly blown highlights, period-correct monochrome or sepia, tripod-locked framing',
    'Film Noir': 'high-contrast monochrome, venetian-blind shadow bars, hard side key, smoke haze, wet reflective streets, low canted angles, absolute blacks',
    'Retro VHS Found Footage': 'VHS tape artifacts, chroma bleed, tracking tear, burned-in timecode, low-lux camcorder noise, hunting autofocus, urgent handheld',
    'Comic Book Graphic Novel': 'inked line art with weighted outlines, halftone dot shading, bold flat colour fills, forced dramatic perspective, hard rim ink, poster-grade composition',
    '2D Motion Graphic Explainer': 'flat vector shapes, bold geometric layout, three-colour palette discipline, clean sans-serif labels, snappy easing, generous negative space',
    'Whiteboard Sketch Explainer': 'hand-drawn marker on white, visible stroke ends, one accent colour, drawing-hand energy, simple iconography, no shading',
    'Claymation Stop Motion': 'hand-moulded clay with visible fingerprints, slight frame-to-frame jitter, practical miniature set, warm tungsten light, shallow macro focus',
    'Hyperreal Macro': 'extreme macro, razor-thin focal plane, microscopic surface texture, ring-light speculars, floating dust motes, scientific clarity',
    'Cyberpunk Neon': 'rain-slick neon street, magenta and cyan practicals, volumetric haze, holographic signage, wet reflections, anamorphic flare, dense vertical city'
  };
  const styleSpec = SPECS[visualStyle] || SPECS['Cinematic Realistic'];

  // ---------- seeded selection ----------
  const seed = N(T.noveltySeed, 0) || Math.floor(Math.random() * 1000000);
  const shape = SHAPES[seed % SHAPES.length];

  const mv = [];
  for (let i = 0; i < 5; i++) {
    let idx = (seed + i * 5 + Math.floor(seed / 13)) % MOVES.length;
    let guard = 0;
    while (mv.indexOf(MOVES[idx]) !== -1 && guard < MOVES.length) { idx = (idx + 1) % MOVES.length; guard++; }
    mv.push(MOVES[idx]);
  }
  let tA = TITLE_SHAPES[seed % TITLE_SHAPES.length];
  let tB = TITLE_SHAPES[(Math.floor(seed / 11) + 3) % TITLE_SHAPES.length];
  if (tB === tA) tB = TITLE_SHAPES[(TITLE_SHAPES.indexOf(tA) + 2) % TITLE_SHAPES.length];

  const SHAPE_BLOCK = shape.b.map(function (b, i) {
    return 'SCENE ' + (i + 1) + '\n   job    : ' + b + '\n   camera : ' + mv[i];
  }).join('\n');

  // ---------- script policy: exactly one block is injected ----------
  let scriptPolicy = '';
  if (lang === 'Hindi') {
    scriptPolicy =
      'LANGUAGE: HINDI. SCRIPT: PURE DEVANAGARI, 100 percent.\n' +
      'Every narration-facing string you write is Devanagari only. Not one Roman letter.\n' +
      'Roman-script Hindi is FORBIDDEN. It makes the voice engine mispronounce every word.\n' +
      'Unavoidable proper nouns and modern terms get transliterated INTO Devanagari.\n' +
      'Write spoken Hindi, not textbook Hindi. Short clauses. Real word order.\n' +
      'GOOD : उस रात ठीक तीन बजे घड़ी रुक गई, और गाँव का हर कुत्ता एक साथ भौंकने लगा।\n' +
      'WRONG: Us raat teen baje ghadi ruk gayi (Roman script - rejected)\n' +
