  } else if (lang === 'English') {
    scriptPolicy =
      'LANGUAGE: ENGLISH. SCRIPT: LATIN only.\n' +
      'No Devanagari anywhere. No Hindi words, not even as flavour.\n' +
      'Write spoken English, not written English. Contractions allowed. Short sentences.\n' +
