function extractContent(response) {
  if (!response) return '';
  const r = Array.isArray(response) ? response[0] : response;
  if (!r) return '';
  if (r.choices && r.choices[0]) return r.choices[0].message?.content || r.choices[0].text || '';
  if (r.data && r.data.choices && r.data.choices[0]) return r.data.choices[0].message?.content || '';
  if (r.output && Array.isArray(r.output) && r.output[0]) {
    const f = r.output[0];
    if (f.content && Array.isArray(f.content) && f.content[0] && f.content[0].text) return f.content[0].text;
    if (f.message && f.message.content) return f.message.content;
    if (f.text) return f.text;
    if (typeof f === 'string') return f;
  }
  if (r.output) return typeof r.output === 'string' ? r.output : JSON.stringify(r.output);
  return r.content || r.response || r.text || (typeof r === 'string' ? r : JSON.stringify(r));
}

function extractJson(text) {
  if (!text) return null;
  let s = String(text).trim();
  s = s.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const first = s.indexOf('{');
  const last = s.lastIndexOf('}');
  if (first !== -1 && last > first) {
    const cand = s.slice(first, last + 1);
    try { return JSON.parse(cand); } catch (e2) {}
    try { return JSON.parse(cand.replace(/,\s*([\]}])/g, '$1')); } catch (e3) {}
  }
  return null;
}
// ---------- value hygiene: nothing undefined ever reaches Stage 2 ----------
function str(v) {
  if (v === null || v === undefined) return '';
  const s = String(v).trim();
  const bad = ['null', 'undefined', 'n/a', 'na', 'tbd', 'unknown', 'none', ''];
  return bad.indexOf(s.toLowerCase()) !== -1 ? '' : s;
}
function keep(v) {
  if (v === null || v === undefined) return '';
  const s = String(v).trim();
  const bad = ['null', 'undefined', 'n/a', 'tbd', ''];
  return bad.indexOf(s.toLowerCase()) !== -1 ? '' : s;
}
function oneLine(v) { return keep(v).replace(/\s+/g, ' '); }
function arr(v) {
  if (Array.isArray(v)) {
    return v.map(function (x) { return typeof x === 'string' ? x.trim() : String(x); })
            .filter(function (x) { return x && x.toLowerCase() !== 'none' && x.toLowerCase() !== 'n/a'; });
  }
  if (typeof v === 'string' && str(v)) {
    return v.split(/\s*[|;,]\s*/).map(function (x) { return x.trim(); }).filter(Boolean);
  }
  return [];
}
function num(v, d, lo, hi) {
  const n = Number(v);
  if (!isFinite(n)) return d;
  return Math.max(lo, Math.min(hi, Math.round(n)));
}
function obj(v) { return (v && typeof v === 'object' && !Array.isArray(v)) ? v : {}; }
function clip(v, words) {
  const w = oneLine(v).split(/\s+/).filter(Boolean);
  return w.slice(0, words).join(' ');
}

const DEVA_LO = String.fromCharCode(2304);
const DEVA_HI = String.fromCharCode(2431);
const DEVA_RE = new RegExp('[' + DEVA_LO + '-' + DEVA_HI + ']');
function hasDeva(s) { return DEVA_RE.test(String(s || '')); }
function hasLatinWord(s) { return /[A-Za-z]{4,}/.test(String(s || '')); }
function norm(s) {
  return String(s || '').toLowerCase()
    .replace(new RegExp('[^a-z0-9' + DEVA_LO + '-' + DEVA_HI + ' ]+', 'g'), ' ')
    .replace(/\s+/g, ' ').trim();
}

const warnings = [];
function warn(m) { if (warnings.indexOf(m) === -1) warnings.push(m); }
