const DEF_MOVE = [
  'slow push-in from a wide establishing frame to a mid on the subject',
  'lateral truck past a foreground layer that hides then exposes the subject',
  'crane down from a high wide to eye level, ending on the subject hands',
  'locked-off frame while the subject travels from far background until it fills the lens',
  'unbroken dolly-out from a macro detail to the full environment'
];
const DEF_STATE = [
  'something in frame moves from closed to open',
  'the subject changes from still to moving',
  'an object in frame is lifted out of its place',
  'a surface breaks, spills or gives way',
  'the frame empties of everything except the subject'
];
const DEF_LIGHT = [
  'one hard source at 0s, softened and diffused by 15s',
  'flat ambient at 0s, one practical switched on by 15s',
  'open bright light at 0s, a single shaft through shadow by 15s',
  'warm low light at 0s, cold hard top light by 15s',
  'harsh light at 0s, falling to one dim source by 15s'
];

// ---------- upstream context ----------
let topicBrief = {};
try { topicBrief = $('Parse Topic Analyzer Output').first().json || {}; } catch (e) {}
if (!topicBrief.specificTopic && !topicBrief.rawUserInput) {
  try {
    const sd0 = $getWorkflowStaticData('global');
    if (sd0 && sd0.viralGenesisTopicBrief) topicBrief = sd0.viralGenesisTopicBrief;
  } catch (e2) {}
}

const rawTopic = keep(topicBrief.specificTopic) || keep(topicBrief.rawUserInput) || 'Mysterious Phenomenon';
const upStyle = keep(topicBrief.visualStyle) || 'Cinematic Realistic';
const upLang = keep(topicBrief.language) || 'Hinglish';
const upType = keep(topicBrief.contentType) || 'General';
// ---------- read the LLM response ----------
let content = '';
try { content = extractContent($input.first().json); } catch (e) { content = ''; }

let brief = extractJson(content);
let degraded = false;

if (!brief || typeof brief !== 'object' || Array.isArray(brief) ||
    (!brief.storyBrief && !brief.sceneBreakdown && !brief.suggestedTitle)) {
  degraded = true;
  console.log('[Parse Strategy Output v7] Strategy LLM returned nothing usable - degraded mode for: ' + rawTopic);
  warn('Strategy LLM returned no usable JSON - the blueprint was scaffolded from the Stage 0 brief. Output quality will be low. Re-run.');
  brief = {};
}

const lang = keep(brief.language) || upLang;
const style = keep(brief.visualStyle) || upStyle;
const cType = keep(brief.contentType) || upType;

// ---------- spine ----------
const stage0Brief = oneLine(topicBrief.storyBrief);
const storyBrief = keep(brief.storyBrief) || stage0Brief || ('The untold story of ' + rawTopic + '.');
const centralQuestion = oneLine(brief.centralQuestion) || oneLine(topicBrief.centralQuestion);
const theTurn = oneLine(brief.theTurn) || oneLine(topicBrief.theTurn);
const payoffLine = oneLine(brief.payoffLine) || oneLine(topicBrief.payoffLine);
const spineNote = oneLine(brief.spineNote);
const storyShape = oneLine(brief.storyShape) || 'Unspecified';
const viralHook = oneLine(brief.viralHook) || oneLine(topicBrief.suggestedHook) || clip(storyBrief, 16);

if (!theTurn) warn('theTurn is empty - Stage 2 has no reversal to build scene 4 around');
if (!centralQuestion) warn('centralQuestion is empty - the video may not answer anything');
if (!payoffLine) warn('payoffLine is empty - scene 5 has no closing line to land');
// ---------- identity lock: short, 4-6 anchors, repeated byte for byte by Stage 2 ----------
let identityLock = oneLine(brief.identityLock) || oneLine(brief.mainCharacterHint) ||
                   oneLine(brief.mainCharacter) || rawTopic;
const anchorParts = identityLock.split(',').map(function (x) { return x.trim(); }).filter(Boolean);
if (anchorParts.length > 6) {
  identityLock = anchorParts.slice(0, 6).join(', ');
  warn('identityLock had ' + anchorParts.length + ' anchors - trimmed to 6 so the face survives all 5 clips');
}
if (identityLock.length > 220) {
  const cut = identityLock.lastIndexOf(',', 220);
  identityLock = identityLock.slice(0, cut > 60 ? cut : 220).trim();
  warn('identityLock was longer than 220 characters - shortened. Long locks drift between clips.');
}
if (hasDeva(identityLock)) warn('identityLock contains Devanagari - it is injected into English-only image prompts');

const mainCharacter = oneLine(brief.mainCharacter) || identityLock || rawTopic;
const supportCharacter = oneLine(brief.supportCharacter) || 'none - single subject story';
const personRole = oneLine(brief.personRole) || 'Central Subject';
const era = oneLine(brief.era) || keep(topicBrief.timeFrame) || 'Modern';
const setting = oneLine(brief.setting) || 'Unspecified location';
const emotionalCore = oneLine(brief.emotionalCore) || 'SUSPENSE';
const viralAngle = oneLine(brief.viralAngle) || ('The part of ' + rawTopic + ' nobody covers');
const visualStyleDescription = oneLine(brief.visualStyleDescription) ||
  oneLine(topicBrief.visualStyleDescription) || style;
const rejectedAngles = arr(brief.rejectedAngles);
const creatorHonored = oneLine(brief.creatorHonored) || 'None';
const unsupportedNote = oneLine(brief.unsupportedNote) || 'None';
const toneStyle = oneLine(brief.toneStyle) || keep(topicBrief.toneStyle) || 'Fast, intense, human';
const targetRetention = keep(brief.targetRetention) || '80';

let visualAnchors = arr(brief.visualAnchors);
if (visualAnchors.length < 3) {
  visualAnchors = visualAnchors.concat(arr(topicBrief.visualAnchors));
  visualAnchors = visualAnchors.filter(function (v, i, a) { return a.indexOf(v) === i; });
}
if (visualAnchors.length < 3) warn('fewer than 3 visualAnchors - continuity across the 5 clips will be weak');
visualAnchors = visualAnchors.slice(0, 6);
// ---------- the blueprint: exactly 5 shootable scenes, no exceptions ----------
const rawScenes = Array.isArray(brief.sceneBreakdown) ? brief.sceneBreakdown
                : (Array.isArray(brief.scenes) ? brief.scenes : []);
if (!rawScenes.length) {
  warn('sceneBreakdown missing entirely - all 5 scenes were scaffolded. Stage 2 has no real blueprint this run.');
} else if (rawScenes.length !== 5) {
  warn('Strategy returned ' + rawScenes.length + ' scenes - normalised to exactly 5');
}

const anchorLine = visualAnchors.length ? visualAnchors.join(', ') : rawTopic;
const scenes = [];
const patched = [];

for (let i = 0; i < 5; i++) {
  const s = obj(rawScenes[i]);
  const miss = [];

  const beatFunction = oneLine(s.beatFunction) || oneLine(s.purpose) || (ACTS[i] + ' beat');
  const purpose = oneLine(s.purpose) || beatFunction;
  const factSpent = oneLine(s.factSpent) || oneLine(s.fact) || '';
  if (!factSpent) miss.push('factSpent');

  let narrativeFocus = oneLine(s.narrativeFocus) || oneLine(s.voiceoverGuide) || oneLine(s.narration);
  if (!narrativeFocus) { narrativeFocus = beatFunction + ' - ' + clip(storyBrief, 22); miss.push('narrativeFocus'); }

  let visualFocus = oneLine(s.visualFocus) || oneLine(s.visual) || oneLine(s.visualDescription);
  if (!visualFocus) {
    visualFocus = identityLock + ' in ' + setting + ', ' + anchorLine + ' visible in frame, ' + visualStyleDescription;
    miss.push('visualFocus');
  }

  let cameraPlan = oneLine(s.cameraPlan) || oneLine(s.camera) || oneLine(s.cameraMove);
  if (!cameraPlan) { cameraPlan = DEF_MOVE[i]; miss.push('cameraPlan'); }

  let stateChange = oneLine(s.stateChange) || oneLine(s.change);
  if (!stateChange) { stateChange = DEF_STATE[i]; miss.push('stateChange'); }

  let lightChange = oneLine(s.lightChange) || oneLine(s.lighting);
  if (!lightChange) { lightChange = DEF_LIGHT[i]; miss.push('lightChange'); }

  let beats = oneLine(s.beats) || oneLine(s.beatSheet);
  if (!beats || beats.indexOf('0s') === -1) {
    beats = '0s: ' + clip(visualFocus, 12) + ' | 5s: ' + clip(stateChange, 12) + ' | 10s: ' + clip(lightChange, 12);
    miss.push('beats');
  }

  let intensity = num(s.intensity, DEF_INTENSITY[i], 1, 10);
  if (i === 3 && intensity < 10) { intensity = 10; miss.push('intensity(climax raised to 10)'); }
  if (i === 1 && intensity < 8) { intensity = 8; miss.push('intensity(scene 2 raised to 8)'); }
  if (intensity < 7) { intensity = 7; miss.push('intensity(raised to floor 7)'); }

  const endsOnQuestion = oneLine(s.endsOnQuestion) ||
    (i === 4 ? 'closed' : 'what happens next');

  if (hasDeva(visualFocus) || hasDeva(cameraPlan) || hasDeva(beats)) {
    warn('scene ' + (i + 1) + ' has Devanagari in a visual field - the image model only reads English');
  }
  if (miss.length) patched.push('scene ' + (i + 1) + ': ' + miss.join(', '));

  scenes.push({
    sceneNumber: i + 1,
    act: ACTS[i],
    beatFunction: beatFunction,
    purpose: purpose,
    factSpent: factSpent,
    narrativeFocus: narrativeFocus,
    visualFocus: visualFocus,
    cameraPlan: cameraPlan,
    stateChange: stateChange,
    lightChange: lightChange,
    beats: beats,
    emotionalBeat: oneLine(s.emotionalBeat) || emotionalCore,
    intensity: intensity,
    endsOnQuestion: endsOnQuestion,
    pacingNotes: oneLine(s.pacingNotes) || 'steady, no pauses, land the last word hard'
  });
}
if (patched.length) warn('scaffolded missing scene fields -> ' + patched.join(' ; '));
// ---------- anti-repetition memory ----------
let sheetsItems = [];
try { sheetsItems = $('Read Past Topics').all(); } catch (e) {
  try { sheetsItems = $('Rotate Strategy LLM Key').all(); } catch (e2) {}
}
const recentTitles = sheetsItems.map(function (i) { return keep(i.json.Video_Title) || keep(i.json.title); })
  .filter(Boolean).slice(-150);
const recentPlots = sheetsItems.map(function (i) { return keep(i.json.Core_Plot) || keep(i.json.corePlot); })
  .filter(Boolean).slice(-150);
const recentCharacters = [...new Set(sheetsItems.map(function (i) {
  return keep(i.json.Main_Character) || keep(i.json.mainCharacter);
}).filter(function (c) { return c && c !== 'Uploaded'; }))].slice(-30);

// ---------- title ----------
let suggestedTitle = oneLine(brief.suggestedTitle) || (rawTopic + ' 😱 #Shorts');
if (suggestedTitle.length < 40) warn('suggestedTitle is only ' + suggestedTitle.length + ' characters - thin for the thumbnail');
if (suggestedTitle.length > 90) warn('suggestedTitle is ' + suggestedTitle.length + ' characters - YouTube will truncate it');
const BANNED_OPEN = ['the shocking truth', 'you will not believe', 'you won t believe', 'top 5', 'top 10', 'this is why'];
const titleNorm = norm(suggestedTitle);
for (let b = 0; b < BANNED_OPEN.length; b++) {
  if (titleNorm.indexOf(BANNED_OPEN[b]) === 0) warn('suggestedTitle opens with a banned pattern: "' + BANNED_OPEN[b] + '"');
}
const tTok = titleNorm.split(' ').filter(function (t) { return t.length > 3; });
for (let b = 0; b < recentTitles.length; b++) {
  const oTok = norm(recentTitles[b]).split(' ').filter(function (t) { return t.length > 3; });
  if (!tTok.length || !oTok.length) continue;
  let hit = 0;
  for (let k = 0; k < tTok.length; k++) if (oTok.indexOf(tTok[k]) !== -1) hit++;
  if (hit / tTok.length >= 0.7) {
    warn('suggestedTitle overlaps a published title ("' + recentTitles[b] + '") - duplicate risk');
    break;
  }
}

// ---------- tags ----------
let tags = arr(brief.suggestedTags).map(function (t) {
  return String(t).toLowerCase().replace(/^#+/, '').replace(/\s+/g, '').trim();
}).filter(Boolean);
tags = [...new Set(tags)];
if (tags.length < 8) {
  const seedTags = norm(rawTopic).split(' ').filter(function (w) { return w.length > 3; })
    .slice(0, 4).concat(['shorts', 'viral', 'trending', 'documentary', 'story']);
  for (let t = 0; t < seedTags.length && tags.length < 8; t++) {
    if (tags.indexOf(seedTags[t]) === -1) tags.push(seedTags[t]);
  }
  warn('fewer than 8 tags returned - padded from the topic');
}
tags = tags.slice(0, 12);

// ---------- description opener: v6 read a key the old prompt never wrote ----------
const youtubeDescriptionOpener = oneLine(brief.youtubeDescriptionOpener) ||
  oneLine(brief.youtubeDescriptionHook) || oneLine(brief.descriptionOpener) ||
  clip(storyBrief, 24);
// ---------- script audit: this is what makes the voice engine stumble ----------
const narrationBlob = [storyBrief, viralHook, suggestedTitle, payoffLine, youtubeDescriptionOpener]
  .concat(scenes.map(function (s) { return s.narrativeFocus; })).join(' ');

if (lang === 'Hindi') {
  if (!hasDeva(narrationBlob)) warn('Hindi run has no Devanagari in the narration at all - script policy was ignored');
  else if (hasLatinWord(narrationBlob)) warn('Hindi run contains Roman-script words in narration - the voice will mispronounce them');
} else if (lang === 'Hinglish') {
  if (!hasDeva(narrationBlob)) warn('Hinglish run has no Devanagari - it came back as Roman Hindi, which is what breaks pronunciation');
} else if (lang === 'English') {
  if (hasDeva(narrationBlob)) warn('English run contains Devanagari in the narration');
}

// ---------- voice budget carried forward so Stage 2 never guesses ----------
const VO_BASE = { English: 275, Hinglish: 235, Hindi: 175 };
const VO_CPW = { English: 5.9, Hinglish: 6.2, Hindi: 6.5 };
const cpw = VO_CPW[lang] || 6.2;
const voCharTarget = num(topicBrief.voCharTarget, 0, 0, 2000) || (VO_BASE[lang] || 235);
const voCharMin = num(topicBrief.voCharMin, 0, 0, 2000) || Math.round(voCharTarget * 0.94);
const voCharMax = num(topicBrief.voCharMax, 0, 0, 2000) || Math.round(voCharTarget * 1.06);
const voWordMin = num(topicBrief.voWordMin, 0, 0, 400) || Math.round(voCharMin / cpw);
const voWordMax = num(topicBrief.voWordMax, 0, 0, 400) || Math.round(voCharMax / cpw);
const voBudgetNote = keep(topicBrief.voBudgetNote) ||
  (lang + ': aim ' + voCharTarget + ' characters per 15 second scene (' + voWordMin + '-' + voWordMax + ' words)');
const voLengthBias = keep(topicBrief.voLengthBias) || 'default';

// ---------- creator lock travels the whole pipeline ----------
const cl = obj(topicBrief.creatorLock);
const creatorLock = {
  hasDirectives: cl.hasDirectives === true,
  verbatimQuotes: arr(cl.verbatimQuotes),
  styleDemand: keep(cl.styleDemand) || 'None',
  languageDemand: keep(cl.languageDemand) || 'None',
  toneDemand: keep(cl.toneDemand) || 'None',
  lengthDemand: keep(cl.lengthDemand) || 'None',
  structureDemand: keep(cl.structureDemand) || 'None',
  mustInclude: arr(cl.mustInclude),
  mustAvoid: arr(cl.mustAvoid),
  unsupportedAsks: arr(cl.unsupportedAsks)
};
const creatorDirectiveText = keep(topicBrief.creatorDirectiveText) || 'None';
if (creatorLock.hasDirectives && creatorHonored === 'None') {
  warn('the creator gave directives but Strategy left creatorHonored empty - check the brief actually obeys them');
}
// ---------- v6 compatibility string, byte-for-byte shape ----------
const allowedCategories =
  'STORY BRIEF: ' + storyBrief +
  ' | CHARACTER: ' + mainCharacter +
  ' | ERA: ' + era +
  ' | SETTING: ' + setting +
  ' | EMOTIONAL CORE: ' + emotionalCore +
  ' | VIRAL ANGLE: ' + viralAngle +
  ' | HOOK: ' + viralHook;

const descriptionDisclaimers = '\n\n📌 Disclaimer: This video is brought to life using AI-generated visuals based on original storytelling. Each scene is crafted for this video only.\n\n📌 Copyright Disclaimer Under Section 107 of the Copyright Act 1976: Allowance is made for "fair use" for purposes such as criticism, comment, news reporting, teaching, scholarship, and research.';

const result = {
  // ---- keys v6 already emitted (unchanged contract) ----
  storyBrief: storyBrief,
  mainCharacterHint: identityLock,
  mainCharacter: mainCharacter,
  era: era,
  setting: setting,
  emotionalCore: emotionalCore,
  viralAngle: viralAngle,
  suggestedTitle: suggestedTitle,
  suggestedTags: tags,
  viralHook: viralHook,
  youtubeDescriptionOpener: youtubeDescriptionOpener,
  allowedCategories: allowedCategories,
  visualStyle: style,
  language: lang,
  contentType: cType,
  specificTopic: rawTopic,
  blockedTitles: recentTitles.join(' | ') || 'None',
  blockedPlots: recentPlots.join(' | ') || 'None',
  recentCharacters: recentCharacters.join(', ') || 'None',
  descriptionDisclaimers: descriptionDisclaimers,

  // ---- v7: the five fields Stage 2 reads and v6 threw away ----
  sceneBreakdown: scenes,
  supportCharacter: supportCharacter,
  personRole: personRole,
  visualStyleDescription: visualStyleDescription,
  contentWarnings: keep(brief.contentWarnings) || keep(topicBrief.contentWarnings) || 'None',

  // ---- v7: the spine, so Stage 2 writes a story instead of a description ----
  storyShape: storyShape,
  identityLock: identityLock,
  spineNote: spineNote || 'None',
  centralQuestion: centralQuestion || 'None',
  theTurn: theTurn || 'None',
  payoffLine: payoffLine || 'None',
  visualAnchors: visualAnchors,
  rejectedAngles: rejectedAngles,
  creatorHonored: creatorHonored,
  unsupportedNote: unsupportedNote,
  toneStyle: toneStyle,
  targetRetention: targetRetention,

  // ---- v7: budget + creator + upstream context ----
  voCharTarget: voCharTarget,
  voCharMin: voCharMin,
  voCharMax: voCharMax,
  voWordMin: voWordMin,
  voWordMax: voWordMax,
  voBudgetNote: voBudgetNote,
  voLengthBias: voLengthBias,
  creatorLock: creatorLock,
  creatorDirectiveText: creatorDirectiveText,
  requiredElements: arr(topicBrief.requiredElements),
  forbiddenElements: arr(topicBrief.forbiddenElements),
  factsAvailable: arr(topicBrief.factsAvailable),
  namedEntities: arr(topicBrief.namedEntities),
  contentFamily: keep(topicBrief.contentFamily) || cType,
  genre: keep(topicBrief.genre) || cType,
  formatArchetype: keep(topicBrief.formatArchetype) || 'single-narrative',
  timeFrame: keep(topicBrief.timeFrame) || era,
  targetAudience: keep(topicBrief.targetAudience) || 'Youth 15-35',
  hookType: keep(topicBrief.hookType) || 'mid-crisis',
  rawUserInput: keep(topicBrief.rawUserInput) || rawTopic,
  noveltySeed: num(topicBrief.noveltySeed, Math.floor(Math.random() * 1000000), 0, 999999999),

  // ---- delivery context, passed through untouched ----
  voiceId: keep(topicBrief.voiceId) || 'adam',
  threadId: keep(topicBrief.threadId),
  sessionId: keep(topicBrief.sessionId),
  callbackUrl: keep(topicBrief.callbackUrl),
  autoUploadToYouTube: topicBrief.autoUploadToYouTube === true,

  // ---- diagnostics ----
  sceneCount: scenes.length,
  strategyDegraded: degraded,
  strategyWarnings: warnings
};

let staticData = $getWorkflowStaticData('global');
if (!degraded) staticData.lastSuccessfulStrategyBrief = result;
staticData.viralGenesisStrategyBrief = result;

if (warnings.length) console.log('[Parse Strategy Output v7] ' + warnings.length + ' warning(s): ' + warnings.join(' || '));
console.log('[Parse Strategy Output v7] shape=' + storyShape + ' scenes=' + scenes.length +
  ' lang=' + lang + ' style=' + style + ' budget=' + voCharMin + '-' + voCharMax + ' chars');

return [{ json: result }];

// Rotate Strategy LLM On Failure (Primary) — iterates through ALL primary keys
let staticData = $getWorkflowStaticData('global');
const keys = $('Config: Primary LLM Master').first().json.keys;
const totalKeys = keys.length;

if (staticData.strategyPrimaryAttempts === undefined) {
  staticData.strategyPrimaryAttempts = 0;
}
staticData.strategyPrimaryAttempts += 1;

if (staticData.strategyPrimaryAttempts > totalKeys) {
  console.log(`[STRATEGY PRIMARY EXHAUSTED] All ${totalKeys} primary keys failed. Switching to Backup Strategy LLM (GPT-5.1).`);
  staticData.strategyPrimaryAttempts = 0;
  return [{ json: { failoverToBackup: true, attemptsExhausted: true } }];
}

console.log(`[STRATEGY PRIMARY ERROR] Attempt ${staticData.strategyPrimaryAttempts}/${totalKeys}: Rotating to key index ${staticData.strategyLlmIndex}`);
return [{ json: { failoverToBackup: false, attemptsExhausted: false } }];

// ==========================================================
// CONFIG: STRATEGY BACKUP LLM PROVIDER API KEYS (GPT-5.1)
// ==========================================================

const backupLlmApiKeys = [
  "e8dddcdad5msh80e5a3d80b70d34p15eeffjsn5954cc89f72f",
  "750376d519msh570235a4fc31a85p192539jsn5e3ff7bf57c4",
  "c822c4293emsh61f15bb9eeabb99p14956cjsn1fa2f74ad9f1",
  "2b015b49e7msha9808f1d1ae6654p178d39jsn886507cf88a8",
  "54df5cbe66msh5a2f44867ada346p18df76jsn336df21434a7",
  "c056caf42emsh31e2a3a34483eb4p19cccfjsn41c571dc31bd",
  "ab6f5348c2msh8281a24f8b505c4p1f6c25jsna9ee25a649d0",
  "848eb4ffddmsh58f9567b7db884cp1d1c54jsn60b88f0e3779",
  "f41ee35008msh5b19caf9c84272ap11798djsn512a89d21ed0",
  "a3d237de1fmsh49cacb3b6135a4ap103ea3jsn569e0a83226c",
  "fcbd945aadmsh112cce0a275d0eap124955jsn3220d403adce",
  "c98d722d02msh30b1e3592e3e4aep151dc4jsnc4c068595520",
  "f5fcd4e2bdmshf7ebd4d55b32d16p1e0e9ajsnf8bf202ecbe0",
  "774158e8acmshaebdbbc9b6793abp163ed5jsn993ea29b5def",
  "a9966d64d7msh9f6fff09f298c25p143e62jsn038b8f1f2ea2",
  "b8b3e05c00msh7b3aa11da7ee786p16a604jsn56f8bac7c5c0"
];

const inputData = $input.first().json;
return {
  json: {
    ...inputData,
    keys: backupLlmApiKeys
  }
};

// Rotate Backup Strategy LLM Key — reads keys from Config: Strategy Backup LLM Master
const configNode = $('Config: Strategy Backup LLM Master').first().json || {};
const firstConfig = $('Config: Primary LLM Master').first().json || {};
const keys = configNode.keys || [];
const topicBrief = $('Parse Topic Analyzer Output').first().json || {};
let staticData = $getWorkflowStaticData('global');

if (staticData.backupStrategyLlmIndex === undefined) {
  staticData.backupStrategyLlmIndex = 0;
}

const key = keys[staticData.backupStrategyLlmIndex % keys.length];

return [{
  json: {
    ...topicBrief,
    strategyApiKey: key,
    blockedTitles: firstConfig.blockedTitles || 'None',
    blockedPlots: firstConfig.blockedPlots || 'None',
    recentCharacters: firstConfig.recentCharacters || 'None'
  }
}];

parameters.jsonBody:
={{ (() => {
  // ============================================================
  // STAGE 1 - SHOWRUNNER  (Strategy Engine LLM Brain)
  // Turns the Stage 0 spine into a shootable 5-scene blueprint.
  // ============================================================
  let T = $json || {};
  if (!T.specificTopic && !T.rawUserInput) {
    try { T = $('Parse Topic Analyzer Output').first().json || {}; } catch (e) { T = {}; }
  }

  const BT = String.fromCharCode(96);
  const S = function (v, d) {
    let s = (v === undefined || v === null) ? '' : String(v);
    s = s.split(BT).join("'").replace(/\$\{/g, '(');
    s = s.replace(/\s+/g, ' ').trim();
    return s ? s : (d || '');
  };
  const RAW = function (v, d) {
    let s = (v === undefined || v === null) ? '' : String(v);
    s = s.split(BT).join("'").replace(/\$\{/g, '(').trim();
    return s ? s : (d || '');
  };
  const L = function (v, d) {
    const a = Array.isArray(v) ? v : (v ? String(v).split(/\s*\|\s*/) : []);
    const o = a.map(function (x) { return S(x, ''); }).filter(Boolean);
    return o.length ? o.map(function (x, i) { return '  ' + (i + 1) + '. ' + x; }).join('\n') : (d || '  None');
  };
  const N = function (v, d) { const n = Number(v); return (isFinite(n) && n > 0) ? n : d; };

  // ---------- inbound spine from Stage 0 ----------
  const rawInput = RAW(T.rawUserInput, 'Not provided');
  const specificTopic = RAW(T.specificTopic, rawInput);
  const stage0Brief = RAW(T.storyBrief, '');
  const contentFamily = S(T.contentFamily, 'F12 Curiosity Facts And Lists');
  const contentType = S(T.contentType, 'Curiosity Facts And Lists');
  const genre = S(T.genre, contentType);
  const formatArchetype = S(T.formatArchetype, 'single-narrative');
  const visualStyle = S(T.visualStyle, 'Cinematic Realistic');
  const lang = S(T.language, 'Hinglish');
  const toneStyle = S(T.toneStyle, 'Fast, intense, human');
  const audience = S(T.targetAudience, 'Youth 15-35');
  const timeFrame = S(T.timeFrame, 'Unspecified');
  const centralQ = RAW(T.centralQuestion, '');
  const theTurn = RAW(T.theTurn, '');
  const payoff = RAW(T.payoffLine, '');
  const hookSeed = RAW(T.suggestedHook, '');
  const hookType = S(T.hookType, 'mid-crisis');
  const rejected = RAW(T.rejectedObviousAngle, 'None');
  const retention = S(T.retentionDriver, '');
  const weakAxis = S(T.weakestAxis, '');
  const entities = L(T.namedEntities, '  None named - you may cast freely');
  const facts = L(T.factsAvailable, '  NONE SUPPLIED - you must supply 6 yourself');
  const anchors = L(T.visualAnchors, '  NONE SUPPLIED - you must invent 4');
