// ---------- VOICEOVER CHARACTER BUDGET (single source of truth) ----------
// One character count cannot serve three scripts. Devanagari overflows a 15s
// slot at the same count where English finishes 5s early, so each script gets
// its own target. These three numbers are calibrated at VO_REFERENCE_SPEED and
// are rescaled automatically if the render runs at a different voice speed.
// Tune ONLY these numbers after a real render measurement.
const VO_REFERENCE_SPEED = 1.10;
const VO_BASE_CHARS = { English: 275, Hinglish: 235, Hindi: 175 };
const VO_CHARS_PER_WORD = { English: 5.9, Hinglish: 6.2, Hindi: 6.5 };
const VO_BIAS = { much_shorter: 0.78, shorter: 0.89, default: 1, longer: 1.11, much_longer: 1.22 };
const VO_BIAS_KEYS = ['much_shorter', 'shorter', 'default', 'longer', 'much_longer'];
// Must match whatever Submit Job actually sends to ElevenLabs.
const VO_RENDER_SPEED_DEFAULT = 1.10;
const VO_SPEED_FLOOR = 0.80;
const VO_SPEED_CEIL = 1.60;

function canonStyle(raw, fallback) {
  const v = String(raw || '').trim();
  if (!v) return fallback;
  for (let i = 0; i < CANON_STYLES.length; i++) {
    if (CANON_STYLES[i].toLowerCase() === v.toLowerCase()) return CANON_STYLES[i];
  }
  const lv = v.toLowerCase();
  for (let i = 0; i < STYLE_HINTS.length; i++) {
    if (lv.indexOf(STYLE_HINTS[i][0]) !== -1) return STYLE_HINTS[i][1];
  }
  return fallback;
}

function canonLang(raw, fallback) {
  const v = String(raw || '').trim().toLowerCase();
  if (v.indexOf('hinglish') !== -1) return 'Hinglish';
  if (v.indexOf('hindi') !== -1) return 'Hindi';
  if (v.indexOf('english') !== -1) return 'English';
  return fallback;
}

function arr(v) {
  if (Array.isArray(v)) {
    return v.map(function (x) { return typeof x === 'string' ? x.trim() : String(x); })
            .filter(function (x) { return x && x.toLowerCase() !== 'none' && x.toLowerCase() !== 'n/a'; });
  }
  if (typeof v === 'string' && v.trim() && v.trim().toLowerCase() !== 'none') {
    return v.split(/[,;|]/).map(function (x) { return x.trim(); }).filter(Boolean);
  }
  return [];
}

function str(v) {
  if (v === null || v === undefined) return '';
  const s = String(v).trim();
  const bad = ['null', 'undefined', 'n/a', 'na', 'tbd', 'unknown', ''];
  return bad.indexOf(s.toLowerCase()) !== -1 ? '' : s;
}

function score(v, def) {
  const n = Number(v);
  if (!isFinite(n)) return def;
  return Math.max(1, Math.min(10, Math.round(n)));
}

function obj(v) {
  return (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
}

function demand(v) {
  const s = str(v);
  if (!s) return 'None';
  return s.toLowerCase() === 'none' ? 'None' : s;
}

const DEVA_RE = new RegExp('[' + String.fromCharCode(2304) + '-' + String.fromCharCode(2431) + ']');
function hasDeva(s) { return DEVA_RE.test(String(s || '')); }
function hasLatinWord(s) { return /[A-Za-z]{4,}/.test(String(s || '')); }

// ---------- website payload (source of truth for creator settings) ----------
let site = {};
try { site = $('Filter: My Chat Only').first().json || {}; } catch (e) {}

let cfg = {};
try { cfg = $('Config: Topic Analyzer LLM Master').first().json || {}; } catch (e) {}

const rawInput = str(cfg.rawUserInput) || str(site.rawUserInput);
const siteStyle = canonStyle(site.visualStyle, 'Cinematic Realistic');
const siteLang = canonLang(site.language, 'Hinglish');

// ---------- parse ----------
let content = '';
try { content = extractContent($input.first().json); } catch (e) { content = ''; }

let brief = extractJson(content);
let analyzerFailed = false;
let failReason = '';

if (!brief || typeof brief !== 'object' || Array.isArray(brief)) {
  analyzerFailed = true;
  failReason = 'Topic Analyzer returned no parsable JSON - fell back to raw user input';
  brief = {};
}

// ---------- normalise ----------
const out = {};

out.rawUserInput = str(brief.rawUserInput) || rawInput;
out.contentFamily = str(brief.contentFamily) || 'F12 Curiosity Facts And Lists';
out.contentType = str(brief.contentType) || 'Curiosity Facts And Lists';
out.genre = str(brief.genre) || out.contentType;
out.formatArchetype = str(brief.formatArchetype) || 'single-narrative';
out.specificTopic = str(brief.specificTopic) || rawInput;
out.storyBrief = str(brief.storyBrief) || out.specificTopic || rawInput;
out.namedEntities = arr(brief.namedEntities);
out.timeFrame = str(brief.timeFrame) || 'Unspecified';

out.visualStyle = canonStyle(brief.visualStyle, siteStyle);
out.styleSource = str(brief.styleSource) || 'family_default';
out.styleReason = str(brief.styleReason) || 'Default applied by parser';

out.language = canonLang(brief.language, siteLang);
out.languageSource = str(brief.languageSource) || 'website_setting';

out.toneStyle = str(brief.toneStyle) || 'Engaging and cinematic';
out.targetAudience = str(brief.targetAudience) || 'Youth 15-35';
out.suggestedHook = str(brief.suggestedHook) || '';
out.retentionDriver = str(brief.retentionDriver) || 'Curiosity gap opened in scene 1 and closed in scene 5';

// ---------- v3: creator lock (the creator outranks every pipeline default) ----------
const cl = obj(brief.creatorLock);
out.creatorLock = {
  hasDirectives: cl.hasDirectives === true,
  verbatimQuotes: arr(cl.verbatimQuotes),
  styleDemand: demand(cl.styleDemand),
  languageDemand: demand(cl.languageDemand),
  toneDemand: demand(cl.toneDemand),
  lengthDemand: demand(cl.lengthDemand),
  structureDemand: demand(cl.structureDemand),
  mustInclude: arr(cl.mustInclude),
  mustAvoid: arr(cl.mustAvoid),
  unsupportedAsks: arr(cl.unsupportedAsks)
};
if (!out.creatorLock.hasDirectives) {
  out.creatorLock.hasDirectives = out.creatorLock.verbatimQuotes.length > 0 ||
    out.creatorLock.styleDemand !== 'None' || out.creatorLock.languageDemand !== 'None' ||
    out.creatorLock.toneDemand !== 'None' || out.creatorLock.lengthDemand !== 'None' ||
    out.creatorLock.structureDemand !== 'None' || out.creatorLock.mustInclude.length > 0 ||
    out.creatorLock.mustAvoid.length > 0;
}
out.creatorDirectiveText = out.creatorLock.verbatimQuotes.length
  ? out.creatorLock.verbatimQuotes.map(function (q) { return '"' + q + '"'; }).join(' | ')
  : 'None';

// ---------- v3: story spine ----------
out.centralQuestion = str(brief.centralQuestion) || '';
out.theTurn = str(brief.theTurn) || '';
out.payoffLine = str(brief.payoffLine) || '';
out.rejectedObviousAngle = str(brief.rejectedObviousAngle) || 'None';
out.factsAvailable = arr(brief.factsAvailable);
out.visualAnchors = arr(brief.visualAnchors);
out.hookType = str(brief.hookType) || 'mid-crisis';
out.weakestAxis = str(brief.weakestAxis) || '';

// ---------- v3: voiceover character budget, per script ----------
let bias = str(brief.voLengthBias).toLowerCase().replace(/[\s-]+/g, '_');
if (VO_BIAS_KEYS.indexOf(bias) === -1) {
  const rawBias = bias + ' ' + str(cl.lengthDemand).toLowerCase();
  if (/much_short|very_short|super_short|2_line/.test(rawBias)) bias = 'much_shorter';
  else if (/short|brief|quick|crisp|less/.test(rawBias)) bias = 'shorter';
  else if (/much_long|very_long|max/.test(rawBias)) bias = 'much_longer';
  else if (/long|detail|more|elaborate/.test(rawBias)) bias = 'longer';
  else bias = 'default';
}
out.voLengthBias = bias;
let vSpeed = Number(site.voiceSpeed || site.speed || cfg.voiceSpeed || cfg.speed || 0);
if (!isFinite(vSpeed) || vSpeed <= 0) vSpeed = VO_RENDER_SPEED_DEFAULT;
vSpeed = Math.max(VO_SPEED_FLOOR, Math.min(VO_SPEED_CEIL, vSpeed));
const speedFactor = vSpeed / VO_REFERENCE_SPEED;
const baseChars = VO_BASE_CHARS[out.language] || VO_BASE_CHARS.Hinglish;
const cpw = VO_CHARS_PER_WORD[out.language] || 6.2;
out.voCharTarget = Math.round(baseChars * VO_BIAS[bias] * speedFactor);
out.voCharMin = Math.round(out.voCharTarget * 0.94);
out.voCharMax = Math.round(out.voCharTarget * 1.06);
out.voWordMin = Math.round(out.voCharMin / cpw);
out.voWordMax = Math.round(out.voCharMax / cpw);
out.voReferenceSpeed = VO_REFERENCE_SPEED;
out.voSpeedUsed = Math.round(vSpeed * 100) / 100;
out.voBudgetNote = out.language + ' at voice speed ' + out.voSpeedUsed + ': aim ' +
  out.voCharTarget + ' characters per 15 second scene (' + out.voWordMin + '-' + out.voWordMax + ' words), bias ' + bias;

const vs = (brief.viralScores && typeof brief.viralScores === 'object') ? brief.viralScores : {};
out.viralScores = {
  hookStrength: score(vs.hookStrength, 7),
  emotionalCharge: score(vs.emotionalCharge, 7),
  noveltyScore: score(vs.noveltyScore, 7),
  visualPotential: score(vs.visualPotential, 7),
  shareability: score(vs.shareability, 7),
  completionLikelihood: score(vs.completionLikelihood, 7)
};

const avg = (out.viralScores.hookStrength + out.viralScores.emotionalCharge +
             out.viralScores.noveltyScore + out.viralScores.visualPotential +
             out.viralScores.shareability + out.viralScores.completionLikelihood) / 6;
out.viralScoreAverage = Math.round(avg * 10) / 10;

const declared = str(brief.viralPotential).toUpperCase();
if (declared === 'HIGH' || declared === 'MEDIUM' || declared === 'LOW') {
  out.viralPotential = declared;
} else {
  out.viralPotential = avg >= 8 ? 'HIGH' : (avg >= 6 ? 'MEDIUM' : 'LOW');
}

out.requiredElements = arr(brief.requiredElements);
out.forbiddenElements = arr(brief.forbiddenElements);
out.contentWarnings = str(brief.contentWarnings) || 'None';
out.hasFullStoryBrief = brief.hasFullStoryBrief === true;

// creator directives that Stage 0 forgot to mirror are mirrored here, never lost
for (let i = 0; i < out.creatorLock.mustInclude.length; i++) {
  const m = out.creatorLock.mustInclude[i];
  if (out.requiredElements.indexOf(m) === -1) out.requiredElements.push(m);
}
for (let i = 0; i < out.creatorLock.mustAvoid.length; i++) {
  const m = out.creatorLock.mustAvoid[i];
  if (out.forbiddenElements.indexOf(m) === -1) out.forbiddenElements.push(m);
}

// creator context carried forward for every downstream stage
out.websiteVisualStyle = siteStyle;
out.websiteLanguage = siteLang;
out.voiceId = str(site.voiceId) || 'adam';
out.threadId = str(site.threadId);
out.sessionId = str(site.sessionId);
out.callbackUrl = str(site.callbackUrl);
out.autoUploadToYouTube = site.autoUploadToYouTube === true;
out.noveltySeed = Math.floor(Math.random() * 1000000);

out.analyzerFailed = analyzerFailed;
out.failReason = failReason;

// diagnostics: did the model break a hard contract?
const warnings = [];
if (CANON_STYLES.indexOf(str(brief.visualStyle)) === -1) {
  warnings.push('visualStyle was not canonical ("' + str(brief.visualStyle) + '") - coerced to ' + out.visualStyle);
}
if (['English', 'Hindi', 'Hinglish'].indexOf(str(brief.language)) === -1) {
  warnings.push('language was not in enum ("' + str(brief.language) + '") - coerced to ' + out.language);
}
const wordCount = out.specificTopic.split(/\s+/).filter(Boolean).length;
if (wordCount < 6) {
  warnings.push('specificTopic is too broad (' + wordCount + ' words) - Stage 1 must narrow it');
}
if (!out.suggestedHook) {
  warnings.push('suggestedHook missing - Stage 1 must write it from scratch');
}
// v3 story-spine diagnostics
if (!out.theTurn) warnings.push('theTurn missing - Stage 1 must invent the turn or the video will only describe');
if (!out.centralQuestion) warnings.push('centralQuestion missing - Stage 1 must define what the video answers');
if (out.factsAvailable.length < 5) {
  warnings.push('only ' + out.factsAvailable.length + ' concrete facts supplied - Stage 1 must add more or scenes will pad with adjectives');
}
if (out.visualAnchors.length < 3) {
  warnings.push('fewer than 3 visualAnchors - continuity across the 5 clips will be weak');
}
if (Math.abs(out.voSpeedUsed - VO_REFERENCE_SPEED) > 0.05) {
  warnings.push('voice speed is ' + out.voSpeedUsed + ' but the budget is calibrated at ' + VO_REFERENCE_SPEED +
    ' - character target rescaled to ' + out.voCharTarget + '. Confirm Submit Job sends the same speed.');
}
// v3 script audit: this is what makes the voice engine stumble
if (out.language === 'Hindi') {
  if (hasLatinWord(out.storyBrief)) warnings.push('Hindi storyBrief contains Roman words - pure Devanagari was required');
  if (!hasDeva(out.storyBrief)) warnings.push('Hindi storyBrief has no Devanagari at all - script policy was ignored');
  if (out.suggestedHook && !hasDeva(out.suggestedHook)) warnings.push('Hindi suggestedHook is not in Devanagari');
}
if (out.language === 'Hinglish') {
  if (!hasDeva(out.storyBrief)) warnings.push('Hinglish storyBrief has no Devanagari - mixed script was required');
}
if (out.language === 'English' && hasDeva(out.storyBrief)) {
  warnings.push('English storyBrief contains Devanagari');
}
out.parserWarnings = warnings;

// ---------- persist ----------
let staticData = $getWorkflowStaticData('global');
staticData.viralGenesisTopicBrief = out;
staticData.viralGenesisRawInput = out.rawUserInput;
staticData.viralGenesisChatId = str(cfg.chatId);
staticData.websiteVisualStyle = siteStyle;
staticData.websiteLanguage = siteLang;
staticData.websiteVoiceId = out.voiceId;

return [{ json: out }];

// Parse Duplicate Check v2 — graded risk: none | similar | exact
const rows  = $input.all().map(r => r.json || {});
const brief = $('Parse Topic Analyzer Output').first().json || {};

const newTopic = String(brief.specificTopic || '').trim();
const newInput = String(brief.rawUserInput || '').trim();
const newChar  = String(brief.mainCharacterHint || brief.mainCharacter || '').trim();

const STOP = new Set(['the','and','for','with','that','this','from','into','about','story','stories','video','shorts','short','make','create','tell','please','hindi','english','hinglish','viral','kahani','kahaani','banao','bana','mein','aur','wala','wali']);

function toks(s) {
  return String(s || '').toLowerCase()
    .replace(/[^a-z0-9\u0900-\u097F ]/g, ' ')
    .split(/\s+/).filter(w => w.length > 3 && !STOP.has(w));
}
function jaccard(a, b) {
  const A = new Set(toks(a)), B = new Set(toks(b));
  if (!A.size || !B.size) return 0;
  let inter = 0; for (const w of A) if (B.has(w)) inter++;
  return inter / (A.size + B.size - inter);
}
const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9\u0900-\u097F]/g, '');
const pick = (row, ...names) => {
  for (const n of names) if (row[n] && String(row[n]).trim()) return String(row[n]).trim();
  return '';
};

const recent = rows.slice(-60);
let topScore = 0, matchedTitle = '', matchedRow = null, exact = false;

for (const row of recent) {
  const oldTitle = pick(row, 'Story Title', 'Title');
  const oldTopic = pick(row, 'Detected Topic');
  const oldPlot  = pick(row, 'Story Brief');
  const oldChar  = pick(row, 'Main Character');

  const topicSim = Math.max(jaccard(newTopic, oldTopic), jaccard(newInput, oldTopic));
  const titleSim = Math.max(jaccard(newTopic, oldTitle), jaccard(newInput, oldTitle));
  const plotSim  = jaccard(newTopic + ' ' + newInput, oldPlot);
  const charHit  = !!(newChar && oldChar && norm(newChar) === norm(oldChar));

  const score = Math.max(topicSim, titleSim, plotSim * 0.9) + (charHit ? 0.15 : 0);

  const isExact =
    (newTopic && oldTopic && norm(newTopic) === norm(oldTopic)) ||
    titleSim >= 0.85 ||
    (charHit && plotSim >= 0.65);

  if (score > topScore) { topScore = score; matchedTitle = oldTitle || oldTopic; matchedRow = row; }
  if (isExact) { exact = true; matchedTitle = oldTitle || oldTopic; matchedRow = row; break; }
}

let repetitionLevel = 'none';
if (exact) repetitionLevel = 'exact';
else if (topScore >= 0.55) repetitionLevel = 'similar';

return [{
  json: {
    isDuplicate: repetitionLevel === 'exact',
    repetitionLevel,
    topScore: Math.round(topScore * 100) / 100,
    matchedTitle,
    matchedStoryBrief: matchedRow ? (matchedRow['Story Brief'] || '') : '',
    matchedCharacter:  matchedRow ? (matchedRow['Main Character'] || '') : '',
    newTopic,
    topicBrief: brief,
    memoryRowsScanned: recent.length
  }
}];

