// Restore all 5 validated scenes and store user custom settings in staticData
const staticData = $getWorkflowStaticData('global');
const p = $('Filter: My Chat Only').first().json;

let waitItem = {};
try {
  const rawWait = $('Wait for Scenes Approval').first().json || {};
  waitItem = rawWait.body || rawWait.query || rawWait || {};
} catch(e) {
  waitItem = {};
}

// Preserve user selected custom audiovisual settings across the workflow (fallback voiceSpeed: 1.30, volume: 0.08)
const rawSpeed = waitItem.voiceSpeed !== undefined ? waitItem.voiceSpeed : (p.voiceSpeed !== undefined ? p.voiceSpeed : 1.30);
const parsedSpeed = Number(rawSpeed);
const safeSpeed = isFinite(parsedSpeed) && parsedSpeed > 0 ? Math.max(0.5, Math.min(4, parsedSpeed)) : 1.30;

const rawVol = waitItem.musicVolume !== undefined ? waitItem.musicVolume : (p.musicVolume !== undefined ? p.musicVolume : 0.08);
const parsedVol = Number(rawVol);
const safeVol = isFinite(parsedVol) ? Math.max(0, Math.min(0.4, parsedVol)) : 0.08;

const musicTrackUrl = waitItem.musicTrackUrl !== undefined ? String(waitItem.musicTrackUrl) : (p.musicTrackUrl !== undefined ? String(p.musicTrackUrl) : '');

staticData.userSelectedCustomSettings = {
  voiceId: waitItem.voiceId || p.voiceId || 'adam',
  elevenLabsVoiceId: waitItem.elevenLabsVoiceId || p.elevenLabsVoiceId || '',
  voiceSpeed: safeSpeed,
  musicId: waitItem.musicId || p.musicId || 'mystery2',
  musicTrackUrl: musicTrackUrl,
  musicVolume: safeVol,
  subtitleSettings: waitItem.subtitleSettings || p.subtitleSettings || null
};

if (staticData.savedScenesForProduction && Array.isArray(staticData.savedScenesForProduction) && staticData.savedScenesForProduction.length === 5) {
  return staticData.savedScenesForProduction.map((scene, idx) => ({
    json: {
      ...scene,
      sceneNumber: idx + 1,
      sceneIndex: idx,
      totalScenes: 5,
      threadId: p.threadId,
      sessionId: p.sessionId,
      callbackUrl: p.callbackUrl
    }
  }));
}

const scenes = $('Split Scenes').all().map((item, idx) => ({
  json: {
    ...item.json,
    sceneNumber: idx + 1,
    sceneIndex: idx,
    totalScenes: 5,
    threadId: p.threadId,
    sessionId: p.sessionId,
    callbackUrl: p.callbackUrl
  }
}));

return scenes;

