={{ JSON.stringify((() => {
  let p = {};
  try { p = $('Filter: My Chat Only').first().json || {}; } catch(e) {}
  let yt = {};
  try { yt = $('Dynamic User YouTube Upload').first().json || {}; } catch(e) {}
  let m = {};
  try { m = $('Status = Done?').first().json.movie || {}; } catch(e) {}
  let s = {};
  try { s = $('Split Scenes').first().json || {}; } catch(e) {}

  const vidId = yt.uploadId || yt.id || '';
  const ytUp = yt.ytUploadStatus || null;
  const ytProc = yt.ytProcessingStatus || null;
  const ytBad = ytUp === 'failed' || ytUp === 'rejected' || ytProc === 'failed' || ytProc === 'terminated';
  const ytDone = ytUp === 'processed' || ytProc === 'succeeded';
  const uploadStatus = !vidId ? 'FAILED' : (ytBad ? 'FAILED' : (ytDone ? 'UPLOADED' : 'PROCESSING'));

  // ── R10-B: the scenes the user actually approved (post-refinement) ──
  let finalScenes = [];
  let scenesSource = 'none';
  try {
    finalScenes = $('Restore 5 Scenes').all().map(i => i.json);
    if (finalScenes.length) scenesSource = 'approved_scenes';
  } catch (e) { finalScenes = []; }
  if (!finalScenes.length) {
    try {
      finalScenes = $('Split Scenes').all().map(i => i.json);
      if (finalScenes.length) scenesSource = 'draft';
    } catch (e) { finalScenes = []; }
  }

  // ── R10-B: the settings the user actually finalised at the scenes gate ──
  let w = {};
  try {
    const rw = $('Wait for Scenes Approval').first().json || {};
    w = rw.body || rw.query || rw || {};
  } catch (e) { w = {}; }
  const numOrNull = (v) => { const n = parseFloat(v); return Number.isFinite(n) ? n : null; };
  const finalSettings = {
    voiceId: w.voiceId || p.voiceId || null,
    elevenLabsVoiceId: w.elevenLabsVoiceId || p.elevenLabsVoiceId || null,
    voiceSpeed: numOrNull(w.voiceSpeed !== undefined ? w.voiceSpeed : p.voiceSpeed),
    musicId: w.musicId || p.musicId || null,
    musicTrackUrl: w.musicTrackUrl || p.musicTrackUrl || null,
    musicVolume: numOrNull(w.musicVolume !== undefined ? w.musicVolume : p.musicVolume),
    subtitleSettings: w.subtitleSettings || p.subtitleSettings || null,
    visualStyleId: w.visualStyleId || p.visualStyleId || null,
    visualStyle: w.visualStyle || p.visualStyle || null,
    language: w.language || p.language || null,
    aspectRatio: w.aspectRatio || p.aspectRatio || null
  };

  // ── R10-B: real critic verdict (there is NO numeric score in this workflow) ──
  let criticVerdict = null;
  try { criticVerdict = $('Parse Critic Output (Primary)').first().json.criticVerdict || null; } catch (e) {}
  if (!criticVerdict) {
    try { criticVerdict = $('Parse Critic Output (Backup)').first().json.criticVerdict || null; } catch (e) {}
  }

  const err = $json.error?.message || yt.uploadError || yt.ytFailureReason || yt.ytRejectionReason || 'YouTube Upload Failed (Manual Upload Available)';

  return {
    status: 'VIDEO_COMPLETED',
    youtubeUploadError: err,
    uploadStatus: uploadStatus,
    uploadError: err,
    ytUploadStatus: ytUp,
    ytProcessingStatus: ytProc,
    bytesUploaded: yt.bytesUploaded || null,
    videoUrl: m.url || '',
    title: (finalScenes[0] && finalScenes[0].title) || s.title || p.rawUserInput || 'Viral Video',
    youtubeDescription: (finalScenes[0] && finalScenes[0].youtubeDescription) || s.youtubeDescription || '',
    tags: (finalScenes[0] && finalScenes[0].tags) || s.tags || [],
    scenes: finalScenes,
    scenesSource,
    finalSettings,
    criticVerdict,
    threadId: p.threadId || '',
    sessionId: p.sessionId || '',
    timestamp: new Date().toISOString()
  };
})()) }}

