const headers = raw.headers || {};
const query = raw.query || {};

const VALID_SECRET = 's-vshorts-sec-9a8b7c6d5e4f3a2b1c0';
const providedSecret = headers['x-webhook-secret'] || headers['X-Webhook-Secret'] || body.webhookSecret || body.secretKey || query.secret || raw.webhookSecret;

if (providedSecret !== VALID_SECRET) {
  throw new Error('Unauthorized: Invalid webhook security secret');
}

const videoUrl = body.videoUrl || raw.videoUrl;
if (!videoUrl) {
  throw new Error('videoUrl is required for manual YouTube upload');
}

const userYouTubeAccessToken = body.userYouTubeAccessToken || raw.userYouTubeAccessToken || body.googleAccessToken || raw.googleAccessToken || body.youtubeAccessToken || raw.youtubeAccessToken || '';
