={{ (() => {
  // AI Agent: Story Doctor - USER MESSAGE
  // Carries the creator's order, the current story with measured counts, the locked spine and the five beats.
  let S1 = {};
  try { S1 = $('Parse Strategy Output').first().json || {}; } catch (e) { S1 = {}; }
  let T = {};
  try { T = $('Parse Topic Analyzer Output').first().json || {}; } catch (e) { T = {}; }
  let W = {};
  try { W = $('Filter: My Chat Only').first().json || {}; } catch (e) { W = {}; }
  let PR = {};
  try { PR = $('Parse Refined Story Output').first().json || {}; } catch (e) { PR = {}; }
  let WA = {};
  try { WA = $('Wait for Approval').first().json || {}; } catch (e) { WA = {}; }
  const IN = $json || {};

  const BT = String.fromCharCode(96);
  const S = function (v, d) {
    let s = (v === undefined || v === null) ? '' : String(v);
    s = s.split(BT).join("'").replace(/\$\{/g, '(');
    s = s.replace(/\s+/g, ' ').trim();
    return s ? s : (d || '');
  };
  const L = function (v) {
    const a = Array.isArray(v) ? v : (v ? String(v).split(',') : []);
    const out = [];
    for (let i = 0; i < a.length; i++) { const t = S(a[i], ''); if (t) out.push(t); }
    return out.length ? out.join(', ') : '';
  };
  const wc = function (v) {
    const a = String(v || '').trim().split(/\s+/);
    return (a.length === 1 && a[0] === '') ? 0 : a.length;
  };

  // ---- the creator's order, hunted across every shape the resume webhook can arrive in ----
  const bags = [];
  const addBag = function (o) { if (o && typeof o === 'object' && !Array.isArray(o)) bags.push(o); };
  addBag(IN); addBag(IN.body); addBag(IN.query); addBag(IN.json);
  if (IN.body && typeof IN.body === 'object') { addBag(IN.body.body); addBag(IN.body.query); }
  addBag(WA); addBag(WA.body); addBag(WA.query);
  addBag(PR); addBag(W);
  const NAMED = ['refinePrompt', 'refineInstruction', 'refineText', 'refineMessage', 'refinement',
    'refineRequest', 'storyFeedback', 'feedback', 'userFeedback', 'changeRequest', 'editRequest',
    'instruction', 'instructions', 'changes', 'notes', 'refine'];
  const LOOSE = ['userMessage', 'message', 'comment', 'chatInput', 'text'];
  const topic = S(W.rawUserInput || T.specificTopic || IN.rawUserInput, '');
  const NOTORDER = ['true', 'false', '1', '0', 'yes', 'no', 'refine', 'approve', 'cancel', 'full',
    'refine_story', 'refine_scenes', 'approve_scenes', 'render_video', 'undefined', 'null'];
  const isOrder = function (v) { return !!v && v.length > 1 && NOTORDER.indexOf(v.toLowerCase()) === -1; };
  let instr = '';
  for (let i = 0; i < NAMED.length && !instr; i++) {
    for (let j = 0; j < bags.length && !instr; j++) {
      const v = S(bags[j][NAMED[i]], '');
      if (isOrder(v)) instr = v;
    }
  }
  for (let i = 0; i < LOOSE.length && !instr; i++) {
    for (let j = 0; j < bags.length && !instr; j++) {
      const v = S(bags[j][LOOSE[i]], '');
      if (isOrder(v) && v.length > 3 && v !== topic) instr = v;
    }
  }
  if (instr.length > 1200) instr = instr.slice(0, 1200);

  // ---- scope flags the website sends next to the order: refineMode, refineRound ----
  const pick = function (key) {
    for (let j = 0; j < bags.length; j++) { const v = S(bags[j][key], ''); if (v) return v; }
    return '';
  };
  const modeRaw = pick('refineMode').toLowerCase();
  const modeKey = modeRaw.replace(/[^a-z]/g, '');
  const roundNum = Math.max(1, Math.min(99, parseInt(pick('refineRound'), 10) || 1));
  const FIELD_OF = { title: 'suggestedTitle', suggestedtitle: 'suggestedTitle', hook: 'viralHook',
    viralhook: 'viralHook', brief: 'storyBrief', storybrief: 'storyBrief', story: 'storyBrief' };
  let scopeLine = '';
  if (modeKey && modeKey !== 'full') {
    scopeLine = FIELD_OF[modeKey]
      ? 'The creator typed this into the ' + modeRaw + ' control, so it is aimed at ' + FIELD_OF[modeKey] +
        '. Change that field and return the other two byte for byte, unless the order itself clearly demands more.'
      : 'The website reports refine mode "' + modeRaw + '". Treat it as a hint only and obey the order as written.';
  }
  let roundLine = '';
  if (roundNum > 1) {
    roundLine = 'This is refine round ' + roundNum + ' on this story. Every earlier round is already baked into ' +
      'the text below, so build on top of it and never quietly revert an earlier change.';
  }

  // ---- the story as it stands right now ----
  const curTitle = S(PR.suggestedTitle || S1.suggestedTitle || T.specificTopic, '');
  const curHook = S(PR.viralHook || S1.viralHook, '');
  const curBrief = S(PR.storyBrief || S1.storyBrief, '');

  // ---- the spine Stage 1 locked, which a refine must not quietly break ----
  const lang = S(S1.language || T.language || W.language, 'Hinglish');
  const shape = S(S1.storyShape, 'not set');
  const centralQ = S(S1.centralQuestion, 'not set');
  const theTurn = S(S1.theTurn, 'not set');
  const payoff = S(S1.payoffLine, 'not set');
  const mainChar = S(S1.mainCharacter || S1.mainCharacterHint, 'not set');
  const setting = S(S1.setting, 'not set');
  const era = S(S1.era, 'not set');
  const emo = S(S1.emotionalCore, 'not set');
  const angle = S(S1.viralAngle, 'not set');
  const cType = S(S1.contentType || T.genre, 'not set');
  const forb = L(S1.forbiddenElements);
  const warn = S(S1.contentWarnings, 'none flagged');

  const SB = Array.isArray(S1.sceneBreakdown) ? S1.sceneBreakdown : [];
  const ACTS = ['HOOK', 'SETUP', 'BUILD', 'CLIMAX', 'RESOLUTION'];
  let BEATS = '';
  for (let i = 0; i < 5; i++) {
    const b = SB[i] || {};
    BEATS += 'BEAT ' + (i + 1) + ' - ' + S(b.act, ACTS[i]) +
      ' - job: ' + S(b.beatFunction || b.purpose, 'not specified by Stage 1') +
      ' - spends: ' + S(b.factSpent || b.narrativeFocus, 'not specified') + '\n';
  }

  const orderBlock = instr
    ? 'THE CREATOR TYPED THIS. IT IS AN ORDER, NOT A SUGGESTION.\n<<<\n' + instr + '\n>>>' +
      (roundLine ? '\n' + roundLine : '') + (scopeLine ? '\n' + scopeLine : '')
    : 'NO CHANGE REQUEST REACHED THIS NODE.\nDo not invent one and do not improve anything on your own initiative. Return the three fields exactly as they appear above, changedFields as an empty array, voLengthBias as "default", and set changeSummary to: Koi change request nahi mila, story waisi hi rakhi gayi hai.';

  return `A creator has asked for a change to the story below. Carry it out under the laws you were given.

${orderBlock}

===============================================================
THE STORY AS IT STANDS - THESE COUNTS WERE MEASURED BY THE WORKFLOW, TRUST THEM OVER YOUR OWN COUNTING
===============================================================

TITLE [${curTitle.length} characters, target 45 to 80]
${curTitle || '(empty - write one)'}

HOOK [${wc(curHook)} words, maximum 14]
${curHook || '(empty - write one)'}

STORY BRIEF [${curBrief.length} characters, target 700 to 1100]
${curBrief || '(empty - write one from the spine below)'}

===============================================================
LOCKED BY STAGE 1 - CARRY THESE THROUGH UNLESS THE CREATOR SAYS OTHERWISE
===============================================================

Topic the creator originally asked for: ${topic || 'not recorded'}
Language of the title and hook: ${lang}
Story shape: ${shape}
The question the story answers: ${centralQ}
The turn: ${theTurn}
The line it lands on: ${payoff}
Main character: ${mainChar}
Setting: ${setting}
Era: ${era}
Emotional core: ${emo}
Why it travels: ${angle}
Content type: ${cType}
Must never appear: ${forb || 'nothing specified'}
Sensitivity flags: ${warn}

===============================================================
THE FIVE BEATS STAGE 2 IS BOUND BY - YOUR STORY MUST STILL TRAVEL THROUGH THEM
===============================================================

${BEATS}
===============================================================

Do exactly what the creator asked. Leave everything they did not mention untouched, character for character. Return the one JSON object now, with all seven keys and nothing around it.`;
})() }}

