={{ (() => {
  // AI Agent: Story Doctor - SYSTEM MESSAGE
  // The creator's words outrank everything. Every field the creator did not touch is returned byte for byte.
  let S1 = {};
  try { S1 = $('Parse Strategy Output').first().json || {}; } catch (e) { S1 = {}; }
  let T = {};
