={{ (() => {
  // AI Agent: Screenplay Doctor - USER MESSAGE
  // Carries the creator's order, the five scenes with measured counts, the length target and the locked spine.
  let S1 = {};
  try { S1 = $('Parse Strategy Output').first().json || {}; } catch (e) { S1 = {}; }
  let PR = {};
  try { PR = $('Parse Refined Story Output').first().json || {}; } catch (e) { PR = {}; }
  let T = {};
  try { T = $('Parse Topic Analyzer Output').first().json || {}; } catch (e) { T = {}; }
  let W = {};
  try { W = $('Filter: My Chat Only').first().json || {}; } catch (e) { W = {}; }
  let RK = {};
  try { RK = $('Rotate Primary LLM Key').first().json || {}; } catch (e) { RK = {}; }
  let WA = {};
  try { WA = $('Wait for Scenes Approval').first().json || {}; } catch (e) { WA = {}; }
  const IN = $json || {};

  const BT = String.fromCharCode(96);
  const S = function (v, d) {
    let s = (v === undefined || v === null) ? '' : String(v);
    s = s.split(BT).join("'").replace(/\$\{/g, '(');
    s = s.replace(/\s+/g, ' ').trim();
    return s ? s : (d || '');
  };
  const L = function (v) {
    const a = Array.isArray(v) ? v : (v ? String(v).split(/\s*[|,]\s*/) : []);
    const out = [];
    for (let i = 0; i < a.length; i++) { const t = S(a[i], ''); if (t) out.push(t); }
    return out.length ? out.join(', ') : '';
  };
  const wc = function (v) {
    const a = String(v || '').trim().split(/\s+/);
    return (a.length === 1 && a[0] === '') ? 0 : a.length;
  };
  const num = function (v, d) { const n = Number(v); return (isFinite(n) && n > 0) ? n : d; };

  // ---- the five scenes as they stand: the refined set if a refine already ran, else Stage 2's ----
  let SC = [];
  try { SC = $('Parse Refined Scenes Output').all().map(function (i) { return i.json || {}; }); } catch (e) { SC = []; }
  if (!SC.length) {
    try { SC = $('Split Scenes').all().map(function (i) { return i.json || {}; }); } catch (e) { SC = []; }
  }

  // ---- the creator's order, hunted across every shape the resume webhook can arrive in ----
  const bags = [];
  const addBag = function (o) { if (o && typeof o === 'object' && !Array.isArray(o)) bags.push(o); };
  addBag(IN); addBag(IN.body); addBag(IN.query); addBag(IN.json);
  if (IN.body && typeof IN.body === 'object') { addBag(IN.body.body); addBag(IN.body.query); }
  addBag(WA); addBag(WA.body); addBag(WA.query);
  addBag(W);
  const NAMED = ['refinePrompt', 'refineInstruction', 'refineText', 'refineMessage', 'refinement',
    'refineRequest', 'sceneFeedback', 'storyFeedback', 'feedback', 'userFeedback', 'changeRequest',
    'editRequest', 'instruction', 'instructions', 'changes', 'notes', 'refine'];
  const LOOSE = ['userMessage', 'message', 'comment', 'chatInput', 'text'];
  const topic = S(W.rawUserInput || T.specificTopic || IN.rawUserInput, '');
  const NOTORDER = ['true', 'false', '1', '0', 'yes', 'no', 'refine', 'approve', 'cancel', 'full',
    'refine_story', 'refine_scenes', 'approve_scenes', 'render_video', 'undefined', 'null'];
  const isOrder = function (v) { return !!v && v.length > 1 && NOTORDER.indexOf(v.toLowerCase()) === -1; };
  let instr = '';
  for (let i = 0; i < NAMED.length && !instr; i++) {
    for (let j = 0; j < bags.length && !instr; j++) {
      const v = S(bags[j][NAMED[i]], '');
      if (isOrder(v)) instr = v;
    }
  }
  for (let i = 0; i < LOOSE.length && !instr; i++) {
    for (let j = 0; j < bags.length && !instr; j++) {
      const v = S(bags[j][LOOSE[i]], '');
      if (isOrder(v) && v.length > 3 && v !== topic) instr = v;
    }
  }
  if (instr.length > 1200) instr = instr.slice(0, 1200);

  // ---- scope flags the website sends next to the order: refineMode, refineScenes, refineRound ----
  const pick = function (key) {
    for (let j = 0; j < bags.length; j++) { const v = S(bags[j][key], ''); if (v) return v; }
    return '';
  };
  const pickAny = function (key) {
    for (let j = 0; j < bags.length; j++) {
      const v = bags[j][key];
      if (v !== undefined && v !== null && v !== '') return v;
    }
    return null;
  };
  const modeRaw = pick('refineMode').toLowerCase();
  const modeKey = modeRaw.replace(/[^a-z]/g, '');
  const roundNum = Math.max(1, Math.min(99, parseInt(pick('refineRound'), 10) || 1));

  const ticked = (function () {
    const v = pickAny('refineScenes');
    let a = [];
    if (Array.isArray(v)) { a = v; }
    else if (typeof v === 'string') {
      const t = v.trim();
      if (t.charAt(0) === '[') { try { a = JSON.parse(t); } catch (e) { a = t.replace(/[\[\]]/g, '').split(','); } }
      else { a = t.split(','); }
    } else if (v !== null) { a = [v]; }
    const out = [];
    for (let i = 0; i < a.length; i++) {
      const it = a[i];
      const n = parseInt((it && typeof it === 'object') ? (it.sceneNumber || it.scene || it.number) : it, 10);
      if (n >= 1 && n <= 5 && out.indexOf(n) === -1) out.push(n);
    }
    return out.sort(function (x, y) { return x - y; });
  })();
  // ---- the word band, and the creator's length demand turned into a real target ----
  const lang = S(S1.language || T.language || W.language, 'Hinglish');
  const BASE = { English: 275, Hinglish: 235, Hindi: 175 };
  const CPW = { English: 5.9, Hinglish: 6.2, Hindi: 6.5 };
  const baseChars = BASE[lang] || BASE.Hinglish;
  const cpw = CPW[lang] || CPW.Hinglish;
  const cMin = num(RK.voCharMin, num(S1.voCharMin, Math.round(baseChars * 0.94)));
  const cMax = num(RK.voCharMax, num(S1.voCharMax, Math.round(baseChars * 1.06)));
  const wMin = num(RK.voWordMin, num(S1.voWordMin, Math.round(cMin / cpw)));
  const wMax = num(RK.voWordMax, num(S1.voWordMax, Math.round(cMax / cpw)));
  const bias = S(RK.voLengthBias || S1.voLengthBias, 'default');

  const hay = instr.toLowerCase() + ' ' + instr;
  let f = 0, demandWord = '';
  if (/bahut chhot|bahut chot|bohot chhot|much shorter|way shorter|half|aadha|आधा|बहुत छोट/.test(hay)) { f = 0.72; demandWord = 'much shorter'; }
  else if (/chhot|chot|short|छोट|kam kar|कम कर|ghata|घटा|reduce|shorten|trim|cut it down|less word/.test(hay)) { f = 0.86; demandWord = 'shorter'; }
  else if (/bahut lamb|bahut bad|bohot lamb|much longer|way longer|double|dugn|दुगन|बहुत लंब|बहुत बड़/.test(hay)) { f = 1.28; demandWord = 'much longer'; }
  else if (/lamb|लंब|bada kar|बड़ा कर|badha|बढ़ा|zyada|ज्यादा|ज़्यादा|अधिक|longer|expand|increase|more word/.test(hay)) { f = 1.14; demandWord = 'longer'; }

  let tWMin = wMin, tWMax = wMax, demandLine = '';
  const mW = instr.match(/(\d{1,3})\s*(?:words|word|shabd|शब्द)/i);
  const mS = instr.match(/(\d{1,2})\s*(?:seconds|second|secs|sec|सेकंड|सेकेंड)/i);
  const secN = mS ? parseInt(mS[1], 10) : 0;
  if (mW) {
    const n = Math.max(8, Math.min(120, parseInt(mW[1], 10)));
    tWMin = Math.max(6, n - 3); tWMax = n + 3;
    demandLine = 'The creator named a word count, so the band is built around ' + n + ' words.';
  } else if (secN >= 3 && secN <= 15) {
    const mid = Math.max(8, Math.round(((wMin + wMax) / 2) * (secN / 15)));
    tWMin = Math.max(6, mid - 2); tWMax = mid + 2;
    demandLine = 'The creator named a duration of ' + secN + ' seconds of speech, which is about ' + mid +
      ' words at this voice speed, so the band is built around that.';
  } else if (f) {
    tWMin = Math.max(8, Math.round(wMin * f));
    tWMax = Math.max(tWMin + 3, Math.round(wMax * f));
    demandLine = 'The creator asked for ' + demandWord + ' narration, so the approved band of ' + wMin + ' to ' +
      wMax + ' words has been rescaled for that demand. Landing near the old length is a failure.';
  }
  const tCMin = Math.round(tWMin * cpw), tCMax = Math.round(tWMax * cpw);
  // ---- the spine a scene refine must not quietly break ----
  const title = S(PR.suggestedTitle || S1.suggestedTitle || T.specificTopic, 'not recorded');
  const hook = S(PR.viralHook || S1.viralHook, 'not recorded');
  const brief = S(PR.storyBrief || S1.storyBrief, 'not recorded');
  const identity = S(S1.identityLock || S1.mainCharacterHint || S1.mainCharacter,
    'not recorded - reuse the subject wording that is already inside the videoPrompts, unchanged');
  const style = S(S1.visualStyle || T.visualStyle || W.visualStyle, 'Cinematic Realistic');
  const styleSpec = S(S1.visualStyleDescription, style);
  const setting = S(S1.setting, 'not recorded');
  const centralQ = S(S1.centralQuestion, 'not recorded');
  const payoff = S(S1.payoffLine, 'not recorded');
  const anchors = L(S1.visualAnchors);
  const forb = L(S1.forbiddenElements);
  const warn = S(S1.contentWarnings, 'none flagged');

  // ---- the five scenes, measured ----
  const ACTS = ['HOOK', 'SETUP', 'BUILD', 'CLIMAX', 'RESOLUTION'];
  const SB = Array.isArray(S1.sceneBreakdown) ? S1.sceneBreakdown : [];
  let BLOCK = '';
  for (let i = 0; i < 5; i++) {
    const sc = SC[i] || {};
    const b = SB[i] || {};
    const vo = S(sc.voiceoverText, '');
    const vp = S(sc.videoPrompt, '');
    BLOCK += 'SCENE ' + (i + 1) + ' - ' + S(b.act, ACTS[i]) +
      (ticked.indexOf(i + 1) !== -1 ? '   *** THE CREATOR TICKED THIS SCENE ***' : '') + '\n' +
      'job: ' + S(b.beatFunction || b.purpose, 'not specified by Stage 1') +
      '  |  fact it spends: ' + S(b.factSpent || b.narrativeFocus, 'not specified') + '\n' +
      'NARRATION [' + wc(vo) + ' words, ' + vo.length + ' characters]\n' +
      (vo || '(empty - write one)') + '\n' +
      'VIDEOPROMPT [' + wc(vp) + ' words]\n' +
      (vp || '(empty - write one)') + '\n\n';
  }

  // ---- how the order was scoped by the website ----
  const FIELD_OF = { voiceover: 'voiceoverText', voiceovertext: 'voiceoverText', narration: 'voiceoverText',
    voice: 'voiceoverText', script: 'voiceoverText', audio: 'voiceoverText',
    visual: 'videoPrompt', visuals: 'videoPrompt', video: 'videoPrompt', videoprompt: 'videoPrompt',
    prompt: 'videoPrompt', image: 'videoPrompt', shot: 'videoPrompt' };
  let scopeLine = '';
  if (modeKey === 'selective' || modeKey === 'scene' || modeKey === 'scenes') {
    scopeLine = 'The website reports a selective refine.' + (ticked.length ? '' :
      ' No scene numbers arrived with it, so read the order itself for which scenes are meant and touch only those.');
  } else if (modeKey && modeKey !== 'full') {
    scopeLine = FIELD_OF[modeKey]
      ? 'The creator typed this into the ' + modeRaw + ' control, so it is aimed at ' + FIELD_OF[modeKey] +
        ' only. Return that field only and leave the other one out of your answer entirely.'
      : 'The website reports refine mode "' + modeRaw + '". Treat it as a hint only and obey the order as written.';
  }
  const tickLine = ticked.length
    ? 'THE CREATOR TICKED ' + (ticked.length === 1 ? 'SCENE ' : 'SCENES ') + ticked.join(' and ') +
      '. Those are the only scenes you may return, unless your change to one of them genuinely breaks a ' +
      'neighbouring scene, and then you repair that neighbour too and name it in changeSummary.'
    : '';
  const roundLine = roundNum > 1
    ? 'This is refine round ' + roundNum + ' on this screenplay. Every earlier round is already inside the ' +
      'scenes below, so build on top of them and never quietly revert an earlier change.'
    : '';
  const orderBlock = instr
    ? 'THE CREATOR TYPED THIS. IT IS AN ORDER, NOT A SUGGESTION.\n<<<\n' + instr + '\n>>>' +
      (roundLine ? '\n' + roundLine : '') + (tickLine ? '\n' + tickLine : '') + (scopeLine ? '\n' + scopeLine : '')
    : 'NO CHANGE REQUEST REACHED THIS NODE.\nDo not invent one and do not improve anything on your own initiative. Return scene 1 exactly as it appears below, with both fields unchanged, changedScenes as an empty array, and set changeSummary to: Koi change request nahi mila, scenes waise hi rakhe gaye hain.';
  return `A creator has asked for a change to the five scenes below. Carry it out under the laws you were given.

${orderBlock}

===============================================================
LENGTH TARGET - EVERY COUNT BELOW WAS MEASURED BY THE WORKFLOW, TRUST THEM OVER YOUR OWN COUNTING
===============================================================

Approved band before this refine: ${wMin} to ${wMax} words per scene, about ${cMin} to ${cMax} characters.
Band for any scene you rewrite now: ${tWMin} to ${tWMax} words, about ${tCMin} to ${tCMax} characters.
${demandLine || 'There is no length demand in this order, so the band is unchanged, and a scene nobody complained about keeps its length.'}
Length bias already applied earlier in this run: ${bias}.
Narration language: ${lang}. The videoPrompt stays in English whatever the narration is.

===============================================================
THE FIVE SCENES AS THEY STAND
===============================================================

${BLOCK}===============================================================
LOCKED - CARRY THESE THROUGH UNLESS THE CREATOR SAYS OTHERWISE
===============================================================

IDENTITY LOCK. Copy this into the SUBJECT slot of any videoPrompt you rewrite, character for character, adding nothing:
${identity}

Visual style: ${style}
Style specification for the STYLE slot: ${styleSpec}
Recurring visual anchors: ${anchors || 'none recorded - reuse an object that is already in the prompts'}
Setting: ${setting}
Title on the card: ${title}
The hook: ${hook}
The question the film answers: ${centralQ}
The line it lands on: ${payoff}
Must never appear, in narration or in a videoPrompt: ${forb || 'nothing specified'}
Sensitivity flags: ${warn}

THE STORY THESE FIVE SCENES ARE TELLING
${brief}

===============================================================

Do exactly what the creator asked. Return only the scenes you changed, only the fields you changed, and nothing at all around the JSON.`;
})() }}

options.systemMessage:
={{ (() => {
  // AI Agent: Screenplay Doctor - SYSTEM MESSAGE
