// Parse Refined Scenes Output v2 — strict JSON, per-field merge, no silent revert
const raw = $input.first().json?.output || $input.first().json?.text || '';
const sd = $getWorkflowStaticData('global');

let baseScenes = [];
try { baseScenes = (sd.islamicFullScript && sd.islamicFullScript.scenes) || []; } catch(e) {}
if (!baseScenes.length) {
  try { baseScenes = $('Split Scenes').all().map(i => i.json); } catch(e) { baseScenes = []; }
}

function extractJson(text) {
  if (!text) return null;
  let str = String(text).trim();
  const fence = str.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fence) str = fence[1].trim();
  let a = str.indexOf('{'), b = str.lastIndexOf('}');
  const a2 = str.indexOf('['), b2 = str.lastIndexOf(']');
  if (a2 !== -1 && (a === -1 || a2 < a)) { a = a2; b = b2; }
  if (a === -1 || b === -1 || b <= a) return null;
  str = str.substring(a, b + 1);
  try { return JSON.parse(str); } catch (e) {}
  try { return JSON.parse(str.replace(/,\s*([}\]])/g, '$1')); } catch (e) {}
  return null;
}

let parsed = extractJson(raw);
if (Array.isArray(parsed)) parsed = { scenes: parsed };

let refineFailed = false, failReason = '', changedScenes = [], changeSummary = '';
let finalScenes = baseScenes.map(s => ({ ...s }));

if (parsed && Array.isArray(parsed.scenes) && parsed.scenes.length) {
  parsed.scenes.forEach(ns => {
    const num = parseInt(ns.sceneNumber || ns.scene || 0, 10);
    const idx = num >= 1 && num <= finalScenes.length ? num - 1 : -1;
    if (idx === -1) return;
    const vo  = (ns.voiceoverText || '').toString().trim();
    const vid = (ns.videoPrompt   || '').toString().trim();
    if (vo)  finalScenes[idx].voiceoverText = vo;
    if (vid) finalScenes[idx].videoPrompt   = vid;
    finalScenes[idx].duration = 15;
  });
  changedScenes = Array.isArray(parsed.changedScenes) ? parsed.changedScenes : [];
  changeSummary = parsed.changeSummary || '';
} else {
  refineFailed = true;
  failReason = 'Screenplay Doctor returned unparseable output — original scenes kept';
}

sd.islamicFullScript = sd.islamicFullScript || {};
sd.islamicFullScript.scenes = finalScenes;

return finalScenes.map((s, idx) => ({
  json: {
    ...s,
    sceneIndex: idx,
    sceneNumber: idx + 1,
    duration: 15,
    voiceoverCharCount: (s.voiceoverText || '').length,
    refined: true,
    refineFailed,
    failReason,
    changedScenes,
    changeSummary
  }
}));

// R11-G: build the comment from THIS video's data. No hardcoded story, no invented facts.
let ytData = {};
try { ytData = $('Dynamic User YouTube Upload (Manual)').first().json || {}; } catch (e) {}
const videoId = ytData.uploadId || ytData.id || $input.first()?.json?.uploadId || $input.first()?.json?.id;
if (!videoId) {
  return [{ json: { skipped: true, reason: 'no videoId' } }];
}

let ctx = {};
try { ctx = $('Format Manual Upload Context').first().json || {}; } catch (e) {}

const GENERIC = ['viral youtube short', 'viral story', 'viral video', 'shorts video', ''];
const clean = (s) => String(s || '').replace(/[#*_\x60\r\n]+/g, ' ').replace(/\s+/g, ' ').trim();
const usable = (s) => { const c = clean(s); return (c && !GENERIC.includes(c.toLowerCase())) ? c : ''; };

const subject = (usable(ctx.topic) || usable(ctx.title) || usable(String(ctx.storyBrief || '').split(/[.!?]/)[0])).slice(0, 70);
const lang = String(ctx.language || 'English').toLowerCase();
const isHinglish = lang.includes('hindi') || lang.includes('hinglish') || lang.includes('urdu');

let variants;
if (subject) {
  variants = isHinglish
    ? [
        subject + ' — aapka kya khayal hai? Comment mein batao 👇',
        'Aap ' + subject + ' ki jagah hote toh kya karte? Comment karo 👇',
        subject + ' ka end aapko kaisa laga? Ek line mein batao 👇'
      ]
    : [
        subject + ' — what is your take? Drop it in the comments 👇',
        'If you were in this situation, what would you have done? 👇',
        'Did the ending land for you? One line in the comments 👇'
      ];
} else {
  variants = isHinglish
    ? ['Is video ka end aapko kaisa laga? Comment mein batao 👇']
    : ['What did you think of the ending? Tell me in the comments 👇'];
}

// deterministic per video, so the same video always gets the same comment
let h = 0;
const vid = String(videoId);
for (let i = 0; i < vid.length; i++) { h = (h * 31 + vid.charCodeAt(i)) % 1000003; }
let comment = variants[h % variants.length];

const cta = isHinglish ? ' Aisi stories ke liye Subscribe 🔔' : ' Subscribe for more 🔔';
if ((comment + cta).length <= 200) comment += cta;

return [{ json: { videoId, comment, commentLanguage: isHinglish ? 'hinglish' : 'english', commentSubject: subject || null } }];

// ── R10-A: httpFetch shim — the n8n Code sandbox has no global fetch API.
// Backed by this.helpers.httpRequest. Mimics only the parts of the
// HTTP client API this node uses: .ok .status .headers.get() .json() .text()
const helpers = this.helpers;
async function httpFetch(url, opts = {}) {
  const reqOpts = {
    method: String(opts.method || 'GET').toUpperCase(),
    url,
    headers: opts.headers || {},
    json: false,
    returnFullResponse: true,
    timeout: opts.timeout || 300000
  };
  if (opts.body !== undefined && opts.body !== null) reqOpts.body = opts.body;

  let statusCode = 0;
  let rawHeaders = {};
  let rawBody = '';
  try {
    const r = await helpers.httpRequest(reqOpts);
    statusCode = r.statusCode || 200;
    rawHeaders = r.headers || {};
    rawBody = r.body;
  } catch (err) {
    const resp = (err && (err.response || (err.cause && err.cause.response))) || {};
    statusCode = Number(resp.status || resp.statusCode || err.statusCode || err.httpCode || 0) || 0;
    rawHeaders = resp.headers || {};
    rawBody = resp.data !== undefined ? resp.data
            : (err.description || err.message || String(err));
  }

  const asText = () => {
    if (typeof rawBody === 'string') return rawBody;
    if (rawBody === undefined || rawBody === null) return '';
    if (Buffer.isBuffer(rawBody)) return rawBody.toString('utf8');
    try { return JSON.stringify(rawBody); } catch (e) { return String(rawBody); }
  };

  return {
    ok: statusCode >= 200 && statusCode < 300,
    status: statusCode,
    statusText: '',
    headers: {
      get: (name) => {
        const want = String(name).toLowerCase();
        const keys = Object.keys(rawHeaders || {});
        for (let i = 0; i < keys.length; i++) {
          if (keys[i].toLowerCase() === want) return rawHeaders[keys[i]];
        }
        return null;
      }
    },
    text: async () => asText(),
    json: async () => {
      if (rawBody && typeof rawBody === 'object' && !Buffer.isBuffer(rawBody)) return rawBody;
      try { return JSON.parse(asText()); } catch (e) { return {}; }
    }
  };
}

const inJson = $input.first()?.json || {};
const videoId = inJson.videoId || '';
const text = String(inJson.comment || '').trim();

let ctx = {};
try { ctx = $('Format Manual Upload Context').first().json || {}; } catch (e) {}
const accessToken = ctx.userYouTubeAccessToken || '';

if (!videoId || !text || !accessToken) {
  return [{ json: {
    success: true, videoId, comment: text, commentPosted: false,
    commentError: !accessToken ? 'no access token' : 'no videoId or comment text',
    pinned: false, status: 'COMMENT_NOT_POSTED'
  } }];
}

let posted = false, commentId = null, lastStatus = 0, lastError = null;
for (let attempt = 0; attempt < 3 && !posted; attempt++) {
  if (attempt > 0) { try { await new Promise((r) => setTimeout(r, 5000)); } catch (e) {} }
  let res;
  try {
    res = await httpFetch('https://www.googleapis.com/youtube/v3/commentThreads?part=snippet', {
      method: 'POST',
      headers: { 'Authorization': 'Bearer ' + accessToken, 'Content-Type': 'application/json' },
      body: JSON.stringify({ snippet: { videoId: videoId, topLevelComment: { snippet: { textOriginal: text } } } }),
      timeout: 20000
    });
  } catch (e) { lastError = e.message; continue; }
  lastStatus = res.status;
  if (res.ok) {
    const j = await res.json();
    commentId = j.id || null;
    posted = true;
  } else {
    lastError = (await res.text()).slice(0, 300);
    if (res.status === 401 || res.status === 403) break; // scope/permission — retrying will not help
  }
}

return [{ json: {
  success: true,
  videoId: videoId,
  comment: text,
  commentPosted: posted,
  commentId: commentId,
  commentHttpStatus: lastStatus,
  commentError: posted ? null : lastError,
  pinned: false,
  pinNote: 'The YouTube Data API has no method to pin a comment. Pin it manually in YouTube Studio.',
  status: posted ? 'COMMENT_POSTED' : 'COMMENT_NOT_POSTED'
} }];

