  try {
    videoBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  } catch (e) {
    try {
      const keys = Object.keys(item.binary || {});
      if (keys.length > 0) videoBuffer = await this.helpers.getBinaryDataBuffer(0, keys[0]);
    } catch (_) {}
  }
}
if ((!videoBuffer || !videoBuffer.length) && binaryData && binaryData.data) {
  videoBuffer = Buffer.from(binaryData.data, 'base64');
}

if (!videoBuffer) {
  throw new Error('Video file binary buffer could not be loaded');
}

const mimeType = binaryData?.mimeType || 'video/mp4';

// ── R11-B: never upload a file that is not a decodable MP4 ──
const bytes = videoBuffer.length;
const ftypBox = videoBuffer.slice(4, 8).toString('latin1');
const headHex = videoBuffer.slice(0, 24).toString('latin1').replace(/[^\x20-\x7E]/g, '.');
if (bytes < 200000 || ftypBox !== 'ftyp') {
  throw new Error(
    'Refusing to upload: the downloaded file is not a valid MP4. bytes=' + bytes +
    ' box="' + ftypBox + '" head="' + headHex + '" mimeType=' + mimeType +
    ' reportedFileSize=' + (binaryData?.fileSize || 'n/a') + ' src=' + srcUrl
  );
