  throw new Error('YouTube API did not return upload location URL');
}

const uploadRes = await httpFetch(uploadUrl, {
  method: 'PUT',
  headers: {
    'Content-Type': mimeType,
    'Content-Length': String(bytes),
    'Content-Range': 'bytes 0-' + (bytes - 1) + '/' + bytes
  },
  body: videoBuffer
});

const uploadJson = await uploadRes.json();
const videoId = uploadJson.id;

if (!videoId) {
  throw new Error('YouTube Upload Failed: ' + JSON.stringify(uploadJson));
}

// ── R11-D: a video id is not a playable video. Ask YouTube. ──
async function sleepSafe(ms) {
  try { await new Promise((res) => setTimeout(res, ms)); } catch (e) { /* no timers in sandbox */ }
}

let ytUploadStatus = 'unknown';
let ytProcessingStatus = 'unknown';
let ytFailureReason = null;
let ytRejectionReason = null;

for (let attempt = 0; attempt < 5; attempt++) {
  await sleepSafe(attempt === 0 ? 3000 : 6000);
  let vRes;
  try {
    vRes = await httpFetch('https://www.googleapis.com/youtube/v3/videos?part=status,processingDetails&id=' + videoId, {
      method: 'GET',
      headers: { 'Authorization': 'Bearer ' + accessToken },
      timeout: 20000
    });
  } catch (e) { continue; }
  if (!vRes.ok) continue;
  const vJson = await vRes.json();
  const vItem = (vJson.items || [])[0];
  if (!vItem) continue;
  ytUploadStatus = vItem.status?.uploadStatus || ytUploadStatus;
  ytFailureReason = vItem.status?.failureReason || null;
  ytRejectionReason = vItem.status?.rejectionReason || null;
  ytProcessingStatus = vItem.processingDetails?.processingStatus || ytProcessingStatus;
  if (ytUploadStatus === 'failed' || ytUploadStatus === 'rejected') break;
  if (ytProcessingStatus === 'failed' || ytProcessingStatus === 'terminated') break;
  if (ytUploadStatus === 'processed' || ytProcessingStatus === 'succeeded') break;
}

if (ytUploadStatus === 'failed' || ytUploadStatus === 'rejected' ||
    ytProcessingStatus === 'failed' || ytProcessingStatus === 'terminated') {
  throw new Error(
    'YouTube accepted ' + bytes + ' bytes but could not process the video. videoId=' + videoId +
    ' uploadStatus=' + ytUploadStatus + ' processingStatus=' + ytProcessingStatus +
    ' failureReason=' + (ytFailureReason || 'none') +
    ' rejectionReason=' + (ytRejectionReason || 'none')
  );
}

return [{
  json: {
    success: true,
    uploadId: videoId,
    id: videoId,
    title: title,
    url: 'https://youtube.com/shorts/' + videoId,
    channelTitle: chatCtx.userYouTubeChannelTitle || '',
    userUploaded: true,
    bytesUploaded: bytes,
    mimeType: mimeType,
    ytUploadStatus: ytUploadStatus,
    ytProcessingStatus: ytProcessingStatus,
    ytFailureReason: ytFailureReason,
    ytRejectionReason: ytRejectionReason,
    uploadStatus: (ytUploadStatus === 'processed' || ytProcessingStatus === 'succeeded') ? 'UPLOADED' : 'PROCESSING'
  },
  binary: item.binary
}];

