      if (refreshData.accessToken) {
        accessToken = refreshData.accessToken;
      }
    }
  } catch (refreshErr) {
    console.warn('[n8n Manual YouTube Upload] Token refresh notice:', refreshErr.message);
  }
}

const title = (ctx.title || 'Viral YouTube Short').substring(0, 100);
const baseDesc = ctx.description || '';
const description = baseDesc.includes('#Shorts') ? baseDesc : (baseDesc + '\n\n#Shorts');
const tags = Array.isArray(ctx.tags) ? ctx.tags : (ctx.tags ? ctx.tags.split(',') : []);

if (!accessToken) {
  throw new Error('User YouTube OAuth access token is missing for manual upload');
}

const srcUrl = ctx.videoUrl || '';

// 2. Resolve video binary buffer with robust fallback (getBinaryDataBuffer first for filesystem-v2)
let videoBuffer = null;
if (this.helpers && typeof this.helpers.getBinaryDataBuffer === 'function') {
  try {
    videoBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  } catch (e) {
    try {
      const keys = Object.keys(item.binary || {});
      if (keys.length > 0) videoBuffer = await this.helpers.getBinaryDataBuffer(0, keys[0]);
    } catch (_) {}
  }
}
if ((!videoBuffer || !videoBuffer.length) && binaryData && binaryData.data) {
  videoBuffer = Buffer.from(binaryData.data, 'base64');
}

if (!videoBuffer) {
  throw new Error('Video file binary buffer could not be loaded for manual upload');
}

const mimeType = binaryData?.mimeType || 'video/mp4';

// ── R11-B: never upload a file that is not a decodable MP4 ──
const bytes = videoBuffer.length;
const ftypBox = videoBuffer.slice(4, 8).toString('latin1');
const headHex = videoBuffer.slice(0, 24).toString('latin1').replace(/[^\x20-\x7E]/g, '.');
if (bytes < 200000 || ftypBox !== 'ftyp') {
  throw new Error(
    'Refusing to upload: the downloaded file is not a valid MP4. bytes=' + bytes +
    ' box="' + ftypBox + '" head="' + headHex + '" mimeType=' + mimeType +
    ' reportedFileSize=' + (binaryData?.fileSize || 'n/a') + ' src=' + srcUrl
  );
}

const metadata = {
  snippet: {
    title: title,
    description: description,
    tags: tags.map(t => t.replace(/[<>]/g, '').trim()).filter(t => t.length > 0).slice(0, 30),
    categoryId: '24',
    defaultLanguage: (ctx.language === 'English') ? 'en' : 'hi'
  },
  status: {
    privacyStatus: (['public', 'private', 'unlisted'].includes(String(ctx.privacyStatus || ctx.privacy || '').toLowerCase()) ? String(ctx.privacyStatus || ctx.privacy).toLowerCase() : 'public'),
    selfDeclaredMadeForKids: false,
    embeddable: true,
    publicStatsViewable: true
  }
};

// ── R11-C: Declare the upload length to Google ──
const initRes = await httpFetch('https://www.googleapis.com/upload/youtube/v3/videos?uploadType=resumable&part=snippet,status', {
  method: 'POST',
  headers: {
    'Authorization': 'Bearer ' + accessToken,
    'Content-Type': 'application/json; charset=UTF-8',
    'X-Upload-Content-Type': mimeType,
    'X-Upload-Content-Length': String(bytes)
  },
  body: JSON.stringify(metadata)
});

if (!initRes.ok) {
  const errText = await initRes.text();
  throw new Error('Manual YouTube Upload Init Failed: ' + errText);
}

const uploadUrl = initRes.headers.get('location');
if (!uploadUrl) {
  throw new Error('YouTube API did not return upload location URL');
}

const uploadRes = await httpFetch(uploadUrl, {
  method: 'PUT',
  headers: {
    'Content-Type': mimeType,
    'Content-Length': String(bytes),
    'Content-Range': 'bytes 0-' + (bytes - 1) + '/' + bytes
  },
  body: videoBuffer
});

const uploadJson = await uploadRes.json();
const videoId = uploadJson.id;

if (!videoId) {
  throw new Error('Manual YouTube Upload Failed: ' + JSON.stringify(uploadJson));
}

// ── R11-D: a video id is not a playable video. Ask YouTube. ──
async function sleepSafe(ms) {
  try { await new Promise((res) => setTimeout(res, ms)); } catch (e) { /* no timers in sandbox */ }
}

let ytUploadStatus = 'unknown';
let ytProcessingStatus = 'unknown';
let ytFailureReason = null;
let ytRejectionReason = null;

for (let attempt = 0; attempt < 5; attempt++) {
  await sleepSafe(attempt === 0 ? 3000 : 6000);
  let vRes;
  try {
    vRes = await httpFetch('https://www.googleapis.com/youtube/v3/videos?part=status,processingDetails&id=' + videoId, {
      method: 'GET',
      headers: { 'Authorization': 'Bearer ' + accessToken },
      timeout: 20000
    });
  } catch (e) { continue; }
  if (!vRes.ok) continue;
  const vJson = await vRes.json();
  const vItem = (vJson.items || [])[0];
  if (!vItem) continue;
  ytUploadStatus = vItem.status?.uploadStatus || ytUploadStatus;
  ytFailureReason = vItem.status?.failureReason || null;
  ytRejectionReason = vItem.status?.rejectionReason || null;
  ytProcessingStatus = vItem.processingDetails?.processingStatus || ytProcessingStatus;
  if (ytUploadStatus === 'failed' || ytUploadStatus === 'rejected') break;
  if (ytProcessingStatus === 'failed' || ytProcessingStatus === 'terminated') break;
  if (ytUploadStatus === 'processed' || ytProcessingStatus === 'succeeded') break;
}

if (ytUploadStatus === 'failed' || ytUploadStatus === 'rejected' ||
    ytProcessingStatus === 'failed' || ytProcessingStatus === 'terminated') {
  throw new Error(
    'YouTube accepted ' + bytes + ' bytes but could not process the video. videoId=' + videoId +
    ' uploadStatus=' + ytUploadStatus + ' processingStatus=' + ytProcessingStatus +
    ' failureReason=' + (ytFailureReason || 'none') +
    ' rejectionReason=' + (ytRejectionReason || 'none')
  );
}

return [{
  json: {
    success: true,
    uploadId: videoId,
    id: videoId,
    title: title,
    url: 'https://youtube.com/shorts/' + videoId,
    channelTitle: ctx.userYouTubeChannelTitle || '',
    userUploaded: true,
    bytesUploaded: bytes,
    mimeType: mimeType,
    ytUploadStatus: ytUploadStatus,
    ytProcessingStatus: ytProcessingStatus,
    ytFailureReason: ytFailureReason,
    ytRejectionReason: ytRejectionReason,
    uploadStatus: (ytUploadStatus === 'processed' || ytProcessingStatus === 'succeeded') ? 'UPLOADED' : 'PROCESSING'
  },
  binary: item.binary
}];

// ── R10-A: httpFetch shim — the n8n Code sandbox has no global fetch API.
// Backed by this.helpers.httpRequest. Mimics only the parts of the
// HTTP client API this node uses: .ok .status .headers.get() .json() .text()
const helpers = this.helpers;
async function httpFetch(url, opts = {}) {
  const reqOpts = {
    method: String(opts.method || 'GET').toUpperCase(),
    url,
    headers: opts.headers || {},
    json: false,
    returnFullResponse: true,
    timeout: opts.timeout || 300000
  };
  if (opts.body !== undefined && opts.body !== null) reqOpts.body = opts.body;

  let statusCode = 0;
  let rawHeaders = {};
  let rawBody = '';
  try {
    const r = await helpers.httpRequest(reqOpts);
    statusCode = r.statusCode || 200;
    rawHeaders = r.headers || {};
    rawBody = r.body;
  } catch (err) {
    const resp = (err && (err.response || (err.cause && err.cause.response))) || {};
    statusCode = Number(resp.status || resp.statusCode || err.statusCode || err.httpCode || 0) || 0;
    rawHeaders = resp.headers || {};
    rawBody = resp.data !== undefined ? resp.data
            : (err.description || err.message || String(err));
  }

  const asText = () => {
    if (typeof rawBody === 'string') return rawBody;
    if (rawBody === undefined || rawBody === null) return '';
    if (Buffer.isBuffer(rawBody)) return rawBody.toString('utf8');
    try { return JSON.stringify(rawBody); } catch (e) { return String(rawBody); }
  };

  return {
    ok: statusCode >= 200 && statusCode < 300,
    status: statusCode,
    statusText: '',
    headers: {
      get: (name) => {
        const want = String(name).toLowerCase();
        const keys = Object.keys(rawHeaders || {});
        for (let i = 0; i < keys.length; i++) {
          if (keys[i].toLowerCase() === want) return rawHeaders[keys[i]];
        }
        return null;
      }
    },
    text: async () => asText(),
    json: async () => {
      if (rawBody && typeof rawBody === 'object' && !Buffer.isBuffer(rawBody)) return rawBody;
      try { return JSON.parse(asText()); } catch (e) { return {}; }
    }
  };
}

// Dynamic Google Sheets Logger (Manual Upload): Logs manual upload row directly to User's Connected Spreadsheet
const item = $input.first()?.json || {};
let ctx = {};
try { ctx = $('Format Manual Upload Context').first().json || {}; } catch(e) {}

let userSheetToken = ctx.userSheetAccessToken;
const userSpreadsheetId = ctx.userSpreadsheetId;
const userSheetName = ctx.userSheetName || 'Production Log';
const autoLogEnabled = ctx.autoLogToSheet !== false;
const youtubeLink = item.uploadId ? ('https://youtube.com/shorts/' + item.uploadId) : (item.url || '');

let sheetError = null;
let sheetAppended = false;

if (userSpreadsheetId && autoLogEnabled) {
  if (ctx.threadId) {
    try {
      const refreshRes = await httpFetch('https://bangai.netlify.app/.netlify/functions/refresh-upload-token', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-webhook-secret': 's-vshorts-sec-9a8b7c6d5e4f3a2b1c0'
        },
        body: JSON.stringify({
          threadId: ctx.threadId,
          channelId: userSpreadsheetId,
          scope: 'sheets'
        })
      });
      if (refreshRes.ok) {
        const refreshData = await refreshRes.json();
        if (refreshData.accessToken) userSheetToken = refreshData.accessToken;
      }
    } catch (e) {}
  }

  if (userSheetToken) {
    try {
      const range = encodeURIComponent(userSheetName || 'Sheet1');
      const rowValues = [
        new Date().toISOString().replace('T', ' ').substring(0, 16),
        ctx.title || 'Viral Short',
        ctx.topic || ctx.title || '',
        (ctx.storyBrief || ctx.description || '').toString().slice(0, 480),
        ctx.mainCharacter || '',
        ctx.visualStyle || 'Cinematic',
        ctx.language || 'English',
        'Uploaded to YouTube (Manual)',
        ctx.videoUrl || '',
        youtubeLink
      ];

      const sheetRes = await httpFetch('https://sheets.googleapis.com/v4/spreadsheets/' + userSpreadsheetId + '/values/' + range + ':append?valueInputOption=USER_ENTERED', {
        method: 'POST',
        headers: {
          'Authorization': 'Bearer ' + userSheetToken,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          range: userSheetName || 'Sheet1',
          majorDimension: 'ROWS',
          values: [rowValues]
        })
      });

      if (!sheetRes.ok) {
        const errTxt = await sheetRes.text();
        console.warn('[n8n] Google Sheets API warning (Manual):', errTxt);
        sheetError = 'Google Sheets API error: ' + errTxt;
      }
      if (sheetRes.ok) sheetAppended = true;
    } catch (err) {
      console.warn('[n8n] Error appending manual upload to user Google Sheet:', err.message);
      sheetError = err.message;
    }
  }
}

return [{
  json: {
    ...item,
    sheetLogged: sheetAppended,
    sheetLogSkipped: (!sheetAppended && !sheetError) ? true : undefined,
    error: sheetError || undefined
  }
}];

